@bouclier_group.command(name="secours", description="🧱 Installe un filet AutoMod natif (protège même quand le bot est éteint)")
async def bouclier_secours(i: discord.Interaction):
    """FILET DE SECOURS (owner 2026-06-21) : crée des règles AutoMod NATIVES Discord (mots
    interdits via presets, spam de mentions, invitations) qui tournent CÔTÉ DISCORD — donc
    même si le bot est down (crash/redéploiement). 100% défensif : chaque règle en try/except,
    rapport par règle ; ne casse jamais."""
    await i.response.defer(ephemeral=True)
    g = i.guild
    if g is None:
        return await i.followup.send("Serveur uniquement.", ephemeral=True)
    me = g.me
    if me is None or not me.guild_permissions.manage_guild:
        return await i.followup.send(
            "❌ Il me manque la permission **Gérer le serveur** pour créer des règles AutoMod.\n"
            "Tu peux aussi les créer à la main : Paramètres serveur → **AutoMod** → règles "
            "« Mots interdits » (presets), « Spam de mentions », « Liens d'invitation ».",
            ephemeral=True)
    existing = set()
    try:
        for r in await g.fetch_automod_rules():
            existing.add((getattr(r, 'name', '') or '').lower())
    except Exception:
        pass
    results = []

    async def _mk(name, trigger):
        if name.lower() in existing:
            results.append(f"• {name} — déjà en place ✅")
            return
        try:
            await g.create_automod_rule(
                name=name,
                event_type=discord.AutoModRuleEventType.message_send,
                trigger=trigger,
                actions=[discord.AutoModRuleAction()],   # bloque le message
                enabled=True,
                reason="Filet de secours AutoMod (owner)")
            results.append(f"• {name} — créée ✅")
        except Exception as ex:
            results.append(f"• {name} — échec ❌ ({type(ex).__name__})")

    try:
        await _mk("🛡️ Mots interdits (secours)", discord.AutoModTrigger(
            type=discord.AutoModRuleTriggerType.keyword_preset,
            presets=discord.AutoModPresets(profanity=True, slurs=True, sexual_content=True)))
    except Exception as ex:
        results.append(f"• Mots interdits — non supporté ({type(ex).__name__})")
    try:
        await _mk("🛡️ Spam de mentions (secours)", discord.AutoModTrigger(
            type=discord.AutoModRuleTriggerType.mention_spam, mention_limit=5))
    except Exception as ex:
        results.append(f"• Spam mentions — non supporté ({type(ex).__name__})")
    try:
        await _mk("🛡️ Invitations (secours)", discord.AutoModTrigger(
            type=discord.AutoModRuleTriggerType.keyword,
            keyword_filter=["discord.gg/*", "discord.com/invite/*", "discordapp.com/invite/*"]))
    except Exception as ex:
        results.append(f"• Invitations — non supporté ({type(ex).__name__})")

    await i.followup.send(
        "🧱 **Filet de secours AutoMod** (tourne côté Discord, **même si le bot est éteint**) :\n\n"
        + "\n".join(results)
        + "\n\n_Complète le bot. Ajustable dans Paramètres serveur → AutoMod._",
        ephemeral=True)


