_DISBOARD_ID = 302050872383242240
_bump_last = {}


async def _bump_detect_listener(message):
    """Détecte une confirmation de /bump Disboard → on réarme le rappel à partir de CE moment
    (rappel précis, pas un simple intervalle depuis le boot). FAIL-SAFE."""
    try:
        if getattr(message, 'guild', None) is None or message.author.id != _DISBOARD_ID:
            return
        txt = (message.content or "")
        for e in (getattr(message, 'embeds', None) or []):
            txt += " " + (getattr(e, 'description', '') or "")
        if re.search(r'bump|remont|effectu', txt, re.IGNORECASE):
            _bump_last[message.guild.id] = discord.utils.utcnow().timestamp()
    except Exception:
        pass


@tasks.loop(minutes=10)
async def bump_reminder_task():
    """Rappel auto de /bump (owner 2026-06-27, croissance). Poste dans le salon configuré quand
    l'intervalle est écoulé depuis le dernier bump détecté. FAIL-SAFE, anti-429."""
    try:
        for g in list(bot.guilds):
            try:
                conf = await cfg(g.id)
                ch_id = int(conf.get('bump_reminder_channel', 0) or 0)
                if not ch_id:
                    continue
                interval = max(60, int(conf.get('bump_interval_min', 120) or 120)) * 60
                now_ts = discord.utils.utcnow().timestamp()
                if now_ts - _bump_last.get(g.id, 0) < interval:
                    continue
                ch = bot.get_channel(ch_id)
                if ch is None:
                    continue
                _bump_last[g.id] = now_ts   # évite de re-poster avant le prochain intervalle
                role_id = int(conf.get('bump_reminder_role', 0) or 0)
                head = f"<@&{role_id}> " if role_id else ""
                am = discord.AllowedMentions(roles=bool(role_id), everyone=False, users=False)
                await ch.send(
                    f"{head}⏰ **C'est l'heure de bump !** Pense à bumper le serveur pour nous "
                    f"remonter dans l'annuaire et gagner en visibilité. 🚀", allowed_mentions=am)
                await asyncio.sleep(1)
            except Exception:
                continue
    except Exception as ex:
        print(f"[bump_reminder_task] {ex}")


@bump_reminder_task.before_loop
async def _before_bump_reminder():
    await bot.wait_until_ready()
    await asyncio.sleep(30)






# ═══════════════ RAPPORT SÉCURITÉ HEBDOMADAIRE (owner 2026-06-21 #12) ═══════════════
class SecReportView(discord.ui.View):
    """Menu déroulant du rapport sécu → cibler un membre fiché et voir ses sanctions (éphémère).
    NON persistant (timeout = durée de vie du rapport) : après un reboot/expiration le clic échoue
    — c'est VOULU (le message s'auto-supprime, owner 2026-06-29)."""
    def __init__(self, guild_id, top_players):
        super().__init__(timeout=48 * 3600)
        self.guild_id = int(guild_id)
        opts = [discord.SelectOption(label=str(nm)[:80], value=str(uid),
                                     description=f"{n} sanction(s)"[:90])
                for uid, nm, n in (top_players or [])[:25]]
        if opts:
            sel = discord.ui.Select(
                placeholder="🔎 Cibler un membre fiché → voir ses sanctions…", options=opts)
            sel.callback = self._on_pick
            self.add_item(sel)

    async def _on_pick(self, i):
        try:
            await i.response.defer(ephemeral=True)
            uid = int(i.data['values'][0])
            async with get_db() as db:
                async with db.execute(
                    "SELECT type, reason, created_at FROM infractions WHERE guild_id=? AND user_id=? "
                    "AND datetime(created_at) >= datetime('now','-7 days') ORDER BY created_at DESC LIMIT 20",
                    (self.guild_id, uid)) as cur:
                    rows = await cur.fetchall()
            m = i.guild.get_member(uid) if i.guild else None
            who = m.mention if m else f"<@{uid}>"
            if not rows:
                return await i.followup.send(f"ℹ️ Aucune sanction récente pour {who}.", ephemeral=True)
            lines = []
            for typ, reason, created in rows:
                when = (str(created or ''))[:16]
                r = (reason or '').replace('\n', ' ')[:100] or '—'
                lines.append(f"• **{typ or '—'}** · {r}" + (f" · _{when}_" if when else ''))
            e = discord.Embed(
                title="🔎 Sanctions récentes (7 j)", color=0xE74C3C,
                description=f"{who} (`{uid}`) — **{len(rows)}** sanction(s)\n\n" + "\n".join(lines[:15]))
            e.set_footer(text="Visibilité seule · clic droit sur le membre pour agir (mute/kick…).")
            await i.followup.send(embed=e, ephemeral=True)
        except Exception as ex:
            print(f"[SecReportView pick] {ex}")
            try:
                await i.followup.send("✅ Pris en compte.", ephemeral=True)
            except Exception:
                pass


async def _purge_old_sec_reports(channel):
    """Supprime les anciens rapports sécu empilés (signature dans le titre/desc). Best-effort,
    borné aux 60 derniers messages. Owner 2026-06-29 (« enlève toutes celles du haut »)."""
    try:
        async for m in channel.history(limit=60):
            try:
                txt = (m.content or "")
                for emb in (m.embeds or []):
                    txt += " " + (emb.title or "") + " " + (emb.description or "")
                if "Rapport sécurité hebdomadaire" in txt:
                    await m.delete()
                    await asyncio.sleep(0.3)  # anti-429
            except Exception:
                continue
    except Exception as ex:
        print(f"[_purge_old_sec_reports] {ex}")


async def _post_weekly_security_report(guild):
    """Digest hebdo (visibilité SEULE) : UN SEUL message PAR SEMAINE (anti-doublon, peu importe
    les reboots Railway), supprime les anciens empilés, MENU DÉROULANT des membres les plus
    fichés, AUTO-SUPPRIMÉ après 48 h. owner 2026-06-29. FAIL-SAFE."""
    try:
        c = await cfg(guild.id)
    except Exception:
        c = {}
    wk = datetime.now(timezone.utc).strftime('%G-%V')
    # 🔑 ANTI-DOUBLON par semaine : c'était LE spam — le loop @tasks.loop(168h) tirait son 1er
    # tour ~1 h après CHAQUE redéploiement → 1 rapport par boot. Désormais 1 seul / semaine.
    if str(c.get('sec_report_last_week', '') or '') == wk:
        return
    rows = []
    try:
        async with get_db() as db:
            async with db.execute(
                "SELECT user_id, type, reason, created_at FROM infractions WHERE guild_id=? AND "
                "datetime(created_at) >= datetime('now','-7 days') ORDER BY created_at DESC",
                (guild.id,)) as cur:
                rows = await cur.fetchall()
    except Exception:
        rows = []
    if not rows:
        return  # rien à signaler → AUCUN message (et on ne pose PAS le flag → on pourra poster
                # plus tard dans la semaine si des sanctions arrivent). Fini le « tout est calme ».
    channel = None
    try:
        ch_id = await ulogger2026.resolve_channel_for_category(guild.id, "Sécurité")
        channel = guild.get_channel(int(ch_id)) if ch_id else None
    except Exception:
        channel = None
    if channel is None:
        return
    by_type, by_user = {}, {}
    for uid, typ, reason, created in rows:
        t = typ or '—'
        by_type[t] = by_type.get(t, 0) + 1
        by_user.setdefault(int(uid or 0), []).append(t)
    total = len(rows)
    type_line = " · ".join(f"{t} **{n}**" for t, n in sorted(by_type.items(), key=lambda x: -x[1])[:8])
    ordered = sorted(by_user.items(), key=lambda kv: -len(kv[1]))
    top_players, top_lines = [], []
    medals = ["🥇", "🥈", "🥉"]
    for idx, (uid, infs) in enumerate(ordered[:10]):
        m = guild.get_member(uid)
        nm = m.display_name if m else f"Membre {uid}"
        top_players.append((uid, nm, len(infs)))
        rk = medals[idx] if idx < 3 else f"`#{idx + 1}`"
        top_lines.append(f"{rk} <@{uid}> — **{len(infs)}** sanction(s)")
    extra = f"\n_+{len(ordered) - 10} autre(s) membre(s)_" if len(ordered) > 10 else ""
    e = discord.Embed(
        title="🛡️ Rapport sécurité hebdomadaire", color=0xC0392B, timestamp=now(),
        description=(f"**7 derniers jours** · **{total} sanction(s)**\n{type_line}\n\n"
                     "**Membres les plus fichés :**\n" + "\n".join(top_lines) + extra
                     + "\n\n_Visibilité seule (aucune action auto). Choisis un membre ci-dessous "
                       "pour voir le détail de ses sanctions._"))
    e.set_footer(text="Se supprime tout seul après 48 h · 1 seul rapport par semaine")
    try:
        await _purge_old_sec_reports(channel)
    except Exception:
        pass
    try:
        msg = await channel.send(embed=e, view=SecReportView(guild.id, top_players),
                                 allowed_mentions=discord.AllowedMentions.none())
    except Exception as ex:
        print(f"[_post_weekly_security_report send] {ex}")
        return
    try:
        await _register_for_cleanup(msg, 48 * 3600, 'sec_report')
    except Exception:
        pass
