async def get_ticket(ch_id):
    try:
        async with get_db() as db:
            async with db.execute('SELECT id, user_id, claimed_by, answers, panel_id FROM tickets WHERE channel_id=? AND status="open"', (ch_id,)) as c:
                r = await c.fetchone()
                if r:
                    ans = {}
                    try: ans = json.loads(r[3]) if r[3] else {}
                    except: pass
                    return {'id': r[0], 'user': r[1], 'claimed': r[2] or 0, 'answers': ans, 'panel_id': r[4] or ''}
                return None
    except: return None

async def count_user_tickets(g, uid, pid=None):
    cnt = 0
    to_close = []
    try:
        q = "SELECT id, channel_id FROM tickets WHERE guild_id=? AND user_id=? AND status='open'"
        p = [g.id, uid]
        if pid:
            q += " AND panel_id=?"
            p.append(pid)
        async with get_db() as db:
            async with db.execute(q, p) as c:
                tks = await c.fetchall()
        for tid, chid in tks:
            if g.get_channel(chid): cnt += 1
            else: to_close.append(tid)
        if to_close:
            async with get_db() as db:
                for t in to_close:
                    await db.execute("UPDATE tickets SET status='closed' WHERE id=?", (t,))
                await db.commit()
        return cnt
    except: return 0

def _ticket_event_parts(lt, user, extra, closer):
    """(actor_id, detail) à stocker pour un événement de ticket. FAIL-OPEN."""
    uid = user.id if hasattr(user, 'id') else user
    actor, detail = 0, ''
    try:
        if lt in ('create', 'leave'):
            actor = uid
        elif lt == 'close':
            actor = getattr(closer, 'id', 0) or 0
        elif lt in ('claim', 'add_staff', 'blacklist'):
            actor = extra or 0
        elif lt == 'priority':
            actor, detail = int(extra[0]), str(extra[1])
        elif lt == 'note':
            actor, detail = int(extra[0]), str(extra[1])[:300]
    except Exception:
        try:
            actor = int(extra) if extra else 0
        except Exception:
            actor = 0
    return int(actor or 0), detail


def _ticket_timeline_line(kind, actor_id, detail, ts):
    """Une ligne LISIBLE de la timeline d'un ticket (horodatage Discord relatif)."""
    t = f" · <t:{int(ts)}:t>" if ts else ""
    who = f"<@{int(actor_id)}>" if actor_id else "—"
    lab = {
        'create':    f"🎫 **Créé** par {who}",
        'claim':     f"🙋 **Pris en charge** par {who}",
        'close':     f"🔒 **Fermé** par {who}",
        'leave':     f"🚪 {who} a **quitté** le ticket",
        'add_staff': f"➕ Staff ajouté (par {who})",
        'blacklist': f"🚫 **Blacklisté** par {who}" + (f" · panel {detail}" if detail else ""),
        'priority':  f"🚩 Priorité → **{detail}** (par {who})",
        'note':      f"📌 Note de {who}" + (f" : _{str(detail)[:150]}_" if detail else ""),
    }.get(kind, f"• {kind} ({who})")
    return lab + t


async def send_ticket_log(g, lt, user, ti, extra=None, closer=None, ch=None):
    """owner 2026-06-29 : LOG REGROUPÉ — tous les événements d'un ticket dans UN SEUL message
    qui se met à jour (timeline créé→pris→note→fermé), au lieu d'un message par événement (qui
    se mélangeaient entre tickets). À la fermeture : transcript PRO en pièce jointe. FAIL-SAFE."""
    try:
        c = await cfg(g.id)
        lch = g.get_channel(c.get('ticket_log', 0))
        if not lch:
            return
        try:
            tid = int(ti.get('id', 0) or 0)
        except Exception:
            tid = 0
        uid = user.id if hasattr(user, 'id') else user
        actor, detail = _ticket_event_parts(lt, user, extra, closer)
        ts = int(now().timestamp())
        # 1) enregistre l'événement (pour reconstruire la timeline complète)
        if tid:
            try:
                async with get_db() as db:
                    await db.execute(
                        "INSERT INTO ticket_log_events (guild_id, ticket_id, kind, actor_id, detail, created_unix) "
                        "VALUES (?,?,?,?,?,?)", (g.id, tid, lt, actor, detail, ts))
                    await db.commit()
            except Exception:
                pass
        # 2) reconstruit la timeline depuis TOUS les événements du ticket
        events = []
        if tid:
            try:
                async with get_db() as db:
                    async with db.execute(
                        "SELECT kind, actor_id, detail, created_unix FROM ticket_log_events "
                        "WHERE guild_id=? AND ticket_id=? ORDER BY id ASC", (g.id, tid)) as cur:
                        events = await cur.fetchall()
            except Exception:
                events = []
        if not events:
            events = [(lt, actor, detail, ts)]
        panel_name = ''
        try:
            pid = ti.get('panel_id', '')
            panels = c.get('ticket_panels', {})
            if pid and pid in panels:
                panel_name = panels[pid].get('name', '')
        except Exception:
            panel_name = ''
        last_kind = events[-1][0]
        color = {'create': C.GREEN, 'claim': C.BLUE, 'close': C.RED}.get(last_kind, C.BLURPLE)
        timeline = "\n".join(_ticket_timeline_line(k, a, d, t) for (k, a, d, t) in events[-25:])
        head = f"👤 Ouvert par <@{uid}>" + (f" · panel **{panel_name}**" if panel_name else "")
        ans = ''
        if ti.get('answers'):
            ans = "\n".join(f"**{q}** : {str(a)[:80]}" for q, a in list(ti['answers'].items())[:5])
        desc = (f"{head}\n\n**📜 Historique**\n{timeline}"
                + (f"\n\n**📝 Réponses**\n{ans}" if ans else ""))
        e = discord.Embed(title=f"🎫 Ticket #{tid or ti.get('id', '?')}", color=color,
                          timestamp=now(), description=desc[:4000])
        if last_kind == 'close':
            e.set_footer(text="✅ Ticket clôturé — transcript ci-dessous")
        elif hasattr(user, 'display_avatar'):
            try:
                e.set_thumbnail(url=user.display_avatar.url)
            except Exception:
                pass
        # 3) ÉDITE le message unique du ticket (sinon le crée + mémorise son id)
        msg_id = 0
        if tid:
            try:
                async with get_db() as db:
                    async with db.execute(
                        "SELECT message_id FROM ticket_log_msgs WHERE guild_id=? AND ticket_id=?",
                        (g.id, tid)) as cur:
                        r = await cur.fetchone()
                msg_id = int(r[0]) if r and r[0] else 0
            except Exception:
                msg_id = 0
        edited = False
        if msg_id:
            try:
                old = await lch.fetch_message(msg_id)
                await old.edit(embed=e)
                edited = True
            except Exception:
                edited = False
        if not edited:
            try:
                m = await lch.send(embed=e)
            except Exception:
                m = None
            if m is not None and tid:
                try:
                    async with get_db() as db:
                        await db.execute(
                            "INSERT OR REPLACE INTO ticket_log_msgs (guild_id, ticket_id, message_id) "
                            "VALUES (?,?,?)", (g.id, tid, m.id))
                        await db.commit()
                except Exception:
                    pass
        # 4) à la fermeture : transcript PRO. Priorité = LIEN vers la page RENDUE (self-hosted,
        #    /t/<token>) car Discord affiche un .html joint en CODE BRUT. La pièce jointe reste
        #    en bonus. owner 2026-07-01.
        if lt == 'close' and ch:
            try:
                _tid = tid or ti.get('id', '?')
                base_url = transcript_store.public_base_url()
                token = transcript_store.new_token()
                html = await _render_ticket_transcript_html(
                    ch, _tid, token=token, base_url=base_url)
                url = None
                if html and base_url:
                    try:
                        if await asyncio.to_thread(transcript_store.save_html, token, html):
                            url = transcript_store.transcript_url(token)
                    except Exception:
                        url = None
                if url:
                    # Passe l'URL au MP créateur (évite un 2e rendu + fichier code en MP).
                    try:
                        if len(_recent_transcript_urls) > 500:
                            _recent_transcript_urls.clear()
                        _recent_transcript_urls[str(_tid)] = url
                    except Exception:
                        pass
                    # LIEN prioritaire : GROS bouton, PAS de fichier .html joint (sinon Discord
                    # affiche le code brut qui masque le lien — owner 2026-07-01).
                    e = discord.Embed(
                        title=f"📄 Transcript du ticket #{_tid}",
                        description=("La conversation complète — messages, images, GIFs — est "
                                     "consultable en **un clic** sur une vraie page web 👇"),
                        color=0x5865F2)
                    v = discord.ui.View(timeout=None)
                    v.add_item(discord.ui.Button(
                        style=discord.ButtonStyle.link, url=url, label="🔗 Ouvrir le transcript"))
                    await lch.send(embed=e, view=v, allowed_mentions=discord.AllowedMentions.none())
                else:
                    # Pas de domaine public configuré → repli : pièce jointe téléchargeable.
                    f = None
                    if html:
                        try:
                            f = discord.File(io.BytesIO(html.encode('utf-8')),
                                             filename=f"ticket-{_tid}.html")
                        except Exception:
                            f = None
                    if f is None:
                        f = await _ticket_transcript_file(ch, _tid)
                    if f is not None:
                        await lch.send(content=f"📄 Transcript du ticket **#{_tid}**",
                                       file=f, allowed_mentions=discord.AllowedMentions.none())
            except Exception:
                pass
    except Exception:
        pass

# ─── ⏰ Fenêtre horaire de création de tickets (owner 2026-06-14) ─────────────────
# Création de tickets autorisée UNIQUEMENT 07h–12h ET 13h–22h30 (HEURE DE PARIS), quel que
# soit le type de ticket. Hors créneau → refus + invite à attendre. Exemptés (jamais
# bloqués) : propriétaire du serveur + super-owner. FAIL-OPEN : si l'heure de Paris est
# illisible (zoneinfo absent), on NE bloque PAS (on n'empêche jamais un ticket par bug).
_TICKET_TZ = "Europe/Paris"
# Créneaux [début, fin) en (heure, minute), heure locale Paris (owner 2026-06-16). Faciles
# à ajuster : modifie juste ces paires. La fin est EXCLUSIVE (22h30 = ouvert jusqu'à 22h29).
_TICKET_OPEN_WINDOWS = (((7, 0), (12, 0)), ((13, 0), (22, 30)))


def _ticket_hours_status():
    """(autorisé: bool, heure_actuelle: str, prochain_créneau: str)."""
    try:
        if ZoneInfo is None:
            return (True, "", "")
        now = datetime.now(timezone.utc).astimezone(ZoneInfo(_TICKET_TZ))
        now_min = now.hour * 60 + now.minute
        for ((sh, sm), (eh, em)) in _TICKET_OPEN_WINDOWS:
            if (sh * 60 + sm) <= now_min < (eh * 60 + em):
                return (True, now.strftime("%Hh%M"), "")
        base = now.replace(minute=0, second=0, microsecond=0)
        cands = [base.replace(hour=7), base.replace(hour=13),
                 (base + timedelta(days=1)).replace(hour=7)]
        nxt = next((c for c in cands if c > now), cands[-1])
        when = "aujourd'hui" if nxt.date() == now.date() else "demain"
        return (False, now.strftime("%Hh%M"), f"{nxt.strftime('%Hh%M')} {when}")
    except Exception:
        return (True, "", "")  # FAIL-OPEN : ne jamais bloquer sur erreur technique


def _ticket_hours_blocked_message(now_label, next_label):
    msg = ("🕒 **Les tickets ne peuvent être créés qu'à certaines heures** (heure de Paris).\n"
           "🟢 Créneaux ouverts : **07h–12h** et **13h–22h30**.\n"
           f"Il est actuellement **{now_label or '?'}** — merci de revenir pendant un créneau ouvert 🙏")
    if next_label:
        msg += f"\n⏳ Prochain créneau : **{next_label}**."
    return msg


async def _ticket_hours_allows(user_id, guild):
    """(autorisé: bool, message_refus: str). Exempte propriétaire serveur + super-owner.
    #4 : désactivable via cfg `ticket_hours_enabled` (défaut True)."""
    try:
        if user_id == SUPER_OWNER_ID or (guild is not None and user_id == getattr(guild, 'owner_id', 0)):
            return (True, "")
    except Exception:
        pass
    # Restriction désactivable par l'owner (toggle de config) — défaut activée.
    try:
        if guild is not None and not (await cfg(guild.id)).get('ticket_hours_enabled', True):
            return (True, "")
    except Exception:
        pass
    ok, now_l, next_l = _ticket_hours_status()
    if ok:
        return (True, "")
    return (False, _ticket_hours_blocked_message(now_l, next_l))


async def _access_gate_reason(member, c):
    """#9 (compte Discord trop récent) + #11 (niveau de jeu mini) : RAISON de refus d'une
    action sensible (créer un ticket / une demande d'entraide), ou "" si autorisé. Exempte
    propriétaire serveur + super-owner. FAIL-OPEN (erreur → autorisé). Les deux contrôles
    sont OFF par défaut (cfg = 0)."""
    try:
        if member is None:
            return ""
        uid = getattr(member, 'id', 0)
        g = getattr(member, 'guild', None)
        if uid == SUPER_OWNER_ID or (g is not None and uid == getattr(g, 'owner_id', 0)):
            return ""
        # #9 — âge du compte Discord
        try:
            days = int(c.get('newaccount_gate_days', 0) or 0)
            created = getattr(member, 'created_at', None)
            if days > 0 and created is not None:
                age_days = (datetime.now(timezone.utc) - created).days
                if age_days < days:
                    return (f"🛡️ Ton compte Discord est trop récent ({age_days} j) — cette action "
                            f"est réservée aux comptes de **{days} jours** ou plus. Reviens un peu plus tard 🙏")
        except Exception:
            pass
        # #11 — niveau de jeu minimum
        try:
            minlvl = int(c.get('controls_min_level', 0) or 0)
            if minlvl > 0 and g is not None:
                eco = await get_user_economy(g.id, uid)
                lvl = int((eco or {}).get('level', 1) or 1)
                if lvl < minlvl:
                    return (f"📈 Action réservée au **niveau {minlvl}+** (tu es niveau {lvl}). "
                            f"Joue un peu pour la débloquer 🙂")
        except Exception:
            pass
        return ""
    except Exception:
        return ""


async def count_user_tickets_today(g, uid):
    """#5 : nombre de tickets créés par `uid` dans les dernières 24 h (tout statut). Fail-open → 0."""
    try:
        async with get_db() as db:
            async with db.execute(
                "SELECT COUNT(*) FROM tickets WHERE guild_id=? AND user_id=? "
                "AND created_at > datetime('now','-24 hours')",
                (g.id, uid)) as cur:
                row = await cur.fetchone()
                return int(row[0]) if row else 0
    except Exception:
        return 0


async def _update_support_status(g, c):
    """#2 : met le TOPIC d'un salon configuré à jour avec le statut « support ouvert/fermé »
    (selon la fenêtre horaire tickets). N'édite QUE si le topic change (anti-spam API).
    No-op si support_status_channel non configuré. Fail-open."""
    try:
        ch_id = int(c.get('support_status_channel', 0) or 0)
        if not ch_id:
            return
        ch = g.get_channel(ch_id)
        if ch is None or not isinstance(ch, discord.TextChannel):
            return
        if not c.get('ticket_hours_enabled', True):
            topic = "🎫 Support — ouvert 24/7"
        else:
            ok, _now_l, next_l = _ticket_hours_status()
            if ok:
                topic = "🟢 Support OUVERT — créneaux 07h–12h · 13h–22h30 (heure de Paris)"
            else:
                topic = (f"🔴 Support FERMÉ — réouvre à {next_l or '07h00'} · "
                         f"créneaux 07h–12h · 13h–22h30 (heure de Paris)")
        if (ch.topic or "") != topic:
            await ch.edit(topic=topic, reason="Statut support (contrôles serveur)")
    except Exception as ex:
        print(f"[_update_support_status] {ex}")


async def _apply_night_slowmode(g, c):
    """#1/#2 : applique un slowmode aux salons CHAT la nuit (heure FR) puis le retire le
    matin. OPT-IN : ne fait RIEN si night_slowmode_sec=0. Ne touche QUE les salons chatty, et
    seulement la bascule 0↔sec (ne clobber pas un slowmode manuel d'une autre valeur). Édite
    uniquement aux transitions (pas à chaque tick). IMPORTANT : si le Mode nuit est coupé (ou
    qu'on sort de la fenêtre) alors que le slowmode nocturne est posé, on le RETIRE au tick
    suivant — couper le toggle en pleine nuit nettoie l'effet au lieu de le laisser collé
    jusqu'au matin. Fail-open."""
    try:
        # Cap au maximum Discord (21600 s = 6 h) : empêche une valeur aberrante (config) de
        # poser un slowmode délirant, et borne ce qu'on compare pour le retrait.
        sec = min(int(c.get('night_slowmode_sec', 0) or 0), 21600)
        if sec <= 0:
            return  # aucune valeur de slowmode nuit définie → rien à poser NI à retirer
        # Doit-on appliquer MAINTENANT ? = Mode nuit activé ET dans la fenêtre nocturne.
        # Sinon on est en phase de RETRAIT (mode coupé OU hors fenêtre) : on remet à 0 les
        # salons encore à 'sec' — c'est ce qui débloque le cas « owner coupe le toggle à 23h30 ».
        apply = bool(c.get('night_mode_enabled', False)) and _in_night_window(c)
        for ch in list(getattr(g, 'text_channels', [])):
            try:
                if not await _is_chatty_channel(ch):
                    continue
                cur = int(getattr(ch, 'slowmode_delay', 0) or 0)
                # On n'édite QU'aux transitions (rare) ; un throttle 0,3 s entre deux éditions
                # réelles évite tout flood 429 si beaucoup de salons basculent d'un coup.
                if apply and cur == 0:
                    await ch.edit(slowmode_delay=sec, reason="Mode nuit (contrôles serveur)")
                    await asyncio.sleep(0.3)
                elif (not apply) and cur == sec:
                    await ch.edit(slowmode_delay=0, reason="Fin du mode nuit (contrôles serveur)")
                    await asyncio.sleep(0.3)
            except Exception:
                continue
    except Exception as ex:
        print(f"[_apply_night_slowmode] {ex}")


@tasks.loop(minutes=5)
async def server_controls_task():
    """Tâche périodique des CONTRÔLES SERVEUR (supervisée, fail-open) : (#2) statut support
    ouvert/fermé + (#1/#2) slowmode nuit. Par guilde, tout en try/except (ne casse jamais)."""
    try:
        for g in list(bot.guilds):
            try:
                c = await cfg(g.id)
                await _update_support_status(g, c)
                await _apply_night_slowmode(g, c)
                await asyncio.sleep(0.5)  # throttle anti-429 (espace les edits entre guildes)
            except Exception:
                continue
    except Exception as ex:
        print(f"[server_controls_task] {ex}")


