@tasks.loop(hours=24)
async def gdpr_retention_task():
    """RGPD : (1) purge auto des logs sécu datés (minimisation des données) ; (2) auto-contrôle
    de la carte gdpr.py vs le schéma réel — toute dérive (table/colonne renommée/oubliée) est
    journalisée pour correction. Fail-open : n'interrompt jamais le bot."""
    _ok = True
    res = {}
    mc = []
    try:
        async with get_db() as db:
            res = await gdpr.run_retention(db)
        purged = sum(res.values()) if res else 0
        if purged:
            print(f"⚠️ [gdpr_retention] {purged} ligne(s) purgée(s) par rétention : {res}")
        async with get_db() as db:
            drift = await gdpr.validate_map(db)
        # NB : les « tables absentes » au runtime sont NORMALES — beaucoup de tables sont créées
        # en LAZY (à la 1re utilisation de leur fonctionnalité : mod_notes/gift_log/user_theme_pref…)
        # et la purge est fail-safe (table absente = rien à purger, elle sera couverte une fois créée).
        # On n'alerte donc QUE sur les colonnes manquantes d'une table EXISTANTE = vraie dérive de
        # schéma. (La carte a déjà été vérifiée exhaustivement hors-ligne, cf. workflow gdpr-map-vs-schema.)
        mc = drift.get('missing_columns') or []
        if mc:
            print(f"⚠️ [gdpr_validate] dérive de schéma — colonnes absentes {mc[:40]}")
    except Exception as ex:
        _ok = False
        # owner 2026-06-18 : ne plus échouer en SILENCE — on enregistre l'erreur dans
        # error_logger (visible owner via le burst DM existant) EN PLUS du print console.
        try:
            _logerr("gdpr_retention_task", ex)
        except Exception:
            print(f"⚠️ [gdpr_retention_task] {ex}")
    # owner 2026-06-18 : TRAIL D'AUDIT RGPD persistant (visibilité conformité : « la purge
    # tourne-t-elle ? a-t-elle échoué ? »). 1 ligne par run (résumé + dérive + statut), borné
    # aux 200 derniers. Fail-safe (n'interrompt jamais la tâche).
    try:
        async with get_db() as db:
            await db.execute(
                "CREATE TABLE IF NOT EXISTS gdpr_retention_audit ("
                "id INTEGER PRIMARY KEY AUTOINCREMENT, run_at DATETIME DEFAULT CURRENT_TIMESTAMP, "
                "purged_total INTEGER DEFAULT 0, detail TEXT, drift TEXT, status TEXT)")
            await db.execute(
                "INSERT INTO gdpr_retention_audit(purged_total, detail, drift, status) "
                "VALUES(?,?,?,?)",
                (int(sum(res.values()) if res else 0), json.dumps(res or {})[:1000],
                 json.dumps(list(mc or [])[:40])[:1000], "ok" if _ok else "error"))
            await db.execute(
                "DELETE FROM gdpr_retention_audit WHERE id NOT IN "
                "(SELECT id FROM gdpr_retention_audit ORDER BY id DESC LIMIT 200)")
            await db.commit()
    except Exception:
        pass


@gdpr_retention_task.before_loop
async def _gdpr_retention_wait():
    await bot.wait_until_ready()


async def create_ticket(i, pid, ans=None):
    ch = None
    try:
        # ⏰ FENÊTRE HORAIRE (owner) : filet AUTORITATIF — couvre TOUS les chemins de
        # création (bouton direct + soumission du questionnaire). Hors créneau → refus.
        _ok_h, _msg_h = await _ticket_hours_allows(i.user.id, i.guild)
        if not _ok_h:
            return None, _msg_h
        # 🚦 COOLDOWN anti-rafale (owner 2026-06-29, audit) : filet AUTORITATIF couvrant les 2
        # chemins (bouton + questionnaire). Empêche le spam fermer→rouvrir. Owner/super-owner
        # exemptés. 100% mémoire (zéro DB, zéro 429, zéro MP).
        if getattr(i.user, 'id', 0) not in (SUPER_OWNER_ID, getattr(i.guild, 'owner_id', 0)):
            if not check_rate_limit(i.guild.id, i.user.id, 'ticket_create'):
                return None, ("⏳ Tu viens d'ouvrir un ticket — patiente un court instant avant "
                              "d'en rouvrir un 🙏")
        c = await cfg(i.guild.id)
        # #9/#11 GATE accès (compte récent / niveau de jeu) + #5 QUOTA tickets/jour.
        # Tout OFF par défaut ; owner/super-owner jamais bloqués. Fail-open.
        _gate = await _access_gate_reason(getattr(i, 'user', None), c)
        if _gate:
            return None, _gate
        try:
            _qpd = int(c.get('tickets_per_day', 0) or 0)
            if _qpd > 0 and getattr(i.user, 'id', 0) not in (SUPER_OWNER_ID, getattr(i.guild, 'owner_id', 0)):
                if await count_user_tickets_today(i.guild, i.user.id) >= _qpd:
                    return None, (f"📊 Tu as atteint la limite de **{_qpd} ticket(s) par jour**. "
                                  f"Réessaie demain, ou contacte le staff autrement 🙏")
        except Exception:
            pass
        pnl = c.get('ticket_panels', {}).get(pid, {})
        # 🚫 BLACKLIST — filet AUTORITATIF (owner 2026-06-29, audit) : re-vérifie dans le SINK
        # (le check du bouton reste pour le feedback immédiat avant le formulaire). Défense en
        # profondeur : si create_ticket est un jour appelé par un autre chemin, le blacklisté
        # ne passe pas. Owner/super-owner exemptés. Blacklist per-panel indexée par pid.
        if i.user.id in (pnl.get('blacklist') or []) and \
                getattr(i.user, 'id', 0) not in (SUPER_OWNER_ID, getattr(i.guild, 'owner_id', 0)):
            return None, ("🚫 Vous avez été blacklisté de ce panel de tickets. "
                          "Contactez un administrateur si vous pensez que c'est une erreur.")
        cat = i.guild.get_channel(pnl.get('category', 0))
        
        # Utiliser le rôle staff du panel, sinon le rôle staff global
        staff_role_id = pnl.get('staff_role', 0) or c.get('ticket_staff', 0)
        staff = i.guild.get_role(staff_role_id)
        
        mx = pnl.get('max', 1)
        if not cat: return None, "❌ Catégorie non configurée"
        if await count_user_tickets(i.guild, i.user.id, pid) >= mx:
            return None, f"❌ Max {mx} ticket(s)"
        # owner 2026-07-09 : dans un ticket, l'ouvreur ET le staff peuvent envoyer IMAGES / GIFs /
        # vidéos / liens (utile pour des PREUVES). On accorde attach_files + embed_links + réactions +
        # emojis/stickers/GIFs externes. Le CONTRÔLE reste : anti-phishing + anti-scam tournent
        # toujours dans les tickets (is_ticket_channel), donc un lien phishing / doc suspect est bien
        # supprimé/surveillé — seule la restriction « texte uniquement » saute.
        ow = {
            i.guild.default_role: discord.PermissionOverwrite(view_channel=False),
            i.user: discord.PermissionOverwrite(
                view_channel=True, send_messages=True, read_message_history=True,
                attach_files=True, embed_links=True, add_reactions=True,
                use_external_emojis=True, use_external_stickers=True),
            i.guild.me: discord.PermissionOverwrite(view_channel=True, send_messages=True, manage_channels=True, manage_permissions=True)
        }
        if staff:
            ow[staff] = discord.PermissionOverwrite(
                view_channel=True, send_messages=True, read_message_history=True,
                attach_files=True, embed_links=True, add_reactions=True,
                use_external_emojis=True, use_external_stickers=True)
        if i.guild.owner:
            ow[i.guild.owner] = discord.PermissionOverwrite(
                view_channel=True, send_messages=True, read_message_history=True, manage_channels=True,
                attach_files=True, embed_links=True, add_reactions=True,
                use_external_emojis=True, use_external_stickers=True)
        ch = await i.guild.create_text_channel(f"ticket-{i.user.name}"[:50], category=cat, overwrites=ow)
        aj = json.dumps(ans or {}, ensure_ascii=False)
        async with get_db() as db:
            await db.execute('INSERT INTO tickets(guild_id, channel_id, user_id, panel_id, claimed_by, status, answers) VALUES(?,?,?,?,0,"open",?)',
                (i.guild.id, ch.id, i.user.id, pid, aj))
            await db.commit()
            async with db.execute('SELECT id FROM tickets WHERE channel_id=?', (ch.id,)) as cur:
                row = await cur.fetchone()
                tid = row[0] if row else 0
        
        # ═══════════════════════════════════════════════════════════════════════════════
        #                    📨 EMBED PRINCIPAL DU TICKET
        # ═══════════════════════════════════════════════════════════════════════════════
        panel_name = pnl.get('name', 'Support')
        emb = discord.Embed(color=0x5865F2, timestamp=now())
        emb.set_author(name=f"🎫 Ticket #{tid} • {panel_name}", icon_url=i.guild.icon.url if i.guild.icon else None)
        emb.description = f"Ouvert par {i.user.mention} · panel **{panel_name}**"
        emb.set_thumbnail(url=i.user.display_avatar.url)
        if ans:
            for t, a in ans.items():
                emb.add_field(name=f"📝 {t}", value=a[:1024], inline=False)
        emb.set_footer(text="⏳ En attente du staff")
        # owner 2026-07-20 : PLUS de ping à la création (avant : ouvreur + ROLE staff entier =
        # ping de masse inutile à chaque ticket). L'embed indique déjà qui a ouvert ; le staff
        # voit le ticket dans la catégorie + le salon de logs (send_ticket_log 'create' ci-dessous).
        await webhook_send(ch, 'ticket', embed=emb, view=TicketControlView())
        
        # ═══════════════════════════════════════════════════════════════════════════════
        #                    👋 MESSAGE D'ACCUEIL PERSONNALISÉ
        # ═══════════════════════════════════════════════════════════════════════════════
        welcome_message = pnl.get('welcome_message', '').strip()
        if welcome_message:
            # Créer un embed pour le message d'accueil
            welcome_emb = discord.Embed(
                title="👋 Bienvenue !",
                description=welcome_message,
                color=0x3498DB  # Bleu clair
            )
            welcome_emb.set_footer(text=f"Panel: {pnl.get('name', 'Support')}")
            await webhook_send(ch, 'ticket', embed=welcome_emb)
        
        await send_ticket_log(i.guild, 'create', i.user, {'id': tid, 'answers': ans or {}, 'panel_id': pid})
        return ch, None
    except Exception as ex:
        _logerr("ticket.create", ex, guild_id=getattr(i.guild, "id", 0))
        if ch:
            try: await ch.delete()
            except: pass
        return None, f"❌ {ex}"

class TicketQuestionnaireModal(Modal):
    def __init__(self, pid, qs):
        super().__init__(title="📝 Créer un ticket")
        self.pid = pid
        self.qs = qs
        for i, q in enumerate(qs[:5]):
            self.add_item(TextInput(
                label=q.get('title', f'Q{i+1}')[:45],
                placeholder=q.get('question', '')[:100],
                style=discord.TextStyle.paragraph if len(q.get('question', '')) > 50 else discord.TextStyle.short,
                required=True,
                max_length=500
            ))
    
    async def on_submit(self, i):
        try:
            ans = {self.qs[j].get('title', f'Q{j+1}'): ch.value for j, ch in enumerate(self.children) if j < len(self.qs)}
            await i.response.defer(ephemeral=True)
            ch, err = await create_ticket(i, self.pid, ans)
            await i.followup.send(err if err else f"✅ Ticket créé: {ch.mention}", ephemeral=True)
        except Exception as ex:
            try: await i.followup.send(f"❌ {ex}", ephemeral=True)
            except: pass

class TicketConfirmCreateView(View):
    """Confirmation ÉPHÉMÈRE avant création d'un ticket SANS questionnaire (owner 2026-06-29,
    audit) : évite les tickets ouverts par erreur (« il se trompe / crée pour rien »). Le bouton
    Confirmer appelle create_ticket INCHANGÉ (re-checks autoritatifs heures/cooldown/gate/quota/
    max/blacklist conservés). Non persistant (vue courte, éphémère) → callbacks locaux OK."""
    def __init__(self, pid):
        super().__init__(timeout=120)
        self.pid = pid

    @discord.ui.button(label="✅ Confirmer l'ouverture", style=discord.ButtonStyle.success)
    async def _confirm(self, i, button):
        try:
            await i.response.defer(ephemeral=True)
            ch, err = await create_ticket(i, self.pid)
            await i.followup.send(err if err else f"✅ Ticket créé : {ch.mention}", ephemeral=True)
        except Exception as ex:
            try:
                await i.followup.send(f"❌ {ex}", ephemeral=True)
            except Exception:
                pass

    @discord.ui.button(label="✖️ Annuler", style=discord.ButtonStyle.secondary)
    async def _cancel(self, i, button):
        try:
            await i.response.edit_message(content="Annulé — aucun ticket créé.", view=None)
        except Exception:
            pass


class TicketCreateButton(Button):
    def __init__(self, pid):
        super().__init__(label="📩 Créer un ticket", style=discord.ButtonStyle.success, custom_id=f"ticket_create_{pid}")
        self.pid = pid
    
    async def callback(self, i):
        try:
            c = await cfg(i.guild.id)
            pnl = c.get('ticket_panels', {}).get(self.pid, {})
            if not pnl:
                return await i.response.send_message("❌ Panel introuvable", ephemeral=True)

            # ⏸️ DÉSACTIVATION TEMPORAIRE (fondateur) : si le panneau est désactivé, on
            # refuse la création avec un message clair (le fondateur a coupé via le toggle).
            if pnl.get('disabled'):
                return await i.response.send_message(
                    "⏸️ **Ce ticket est désactivé temporairement.**\nVeuillez revenir plus tard.",
                    ephemeral=True)

            # ═══════════════════════════════════════════════════════════════════════════════
            #                    🚫 VÉRIFICATION BLACKLIST
            # ═══════════════════════════════════════════════════════════════════════════════
            blacklist = pnl.get('blacklist', [])
            if i.user.id in blacklist:
                return await i.response.send_message(
                    "🚫 **Accès refusé**\n\nVous avez été blacklisté de ce panel de tickets.\nContactez un administrateur si vous pensez que c'est une erreur.",
                    ephemeral=True
                )

            # ⏰ FENÊTRE HORAIRE (owner) : refus hors 07h–12h / 13h–22h30 (Paris) — feedback
            # IMMÉDIAT avant le modal/la création (pour ne pas faire remplir un formulaire
            # pour rien). Le filet dans create_ticket reste l'enforcement autoritatif.
            _ok_h, _msg_h = await _ticket_hours_allows(i.user.id, i.guild)
            if not _ok_h:
                return await i.response.send_message(_msg_h, ephemeral=True)

            qs = pnl.get('questions', [])
            mx = pnl.get('max', 1)
            if await count_user_tickets(i.guild, i.user.id, self.pid) >= mx:
                return await i.response.send_message(f"❌ Max {mx} ticket(s)", ephemeral=True)
            if qs:
                await i.response.send_modal(TicketQuestionnaireModal(self.pid, qs))
            else:
                # owner 2026-06-29 (audit) : sur le chemin SANS formulaire, on demande une
                # CONFIRMATION (récap du type) AVANT de créer — évite les tickets ouverts par
                # erreur. Le chemin AVEC formulaire est déjà une saisie volontaire (inchangé).
                _nm = (pnl.get('name') or 'Support').strip()
                _dsc = (pnl.get('embed_description') or '').strip()
                _recap = (f"📩 Tu vas ouvrir un ticket **« {_nm} »**."
                          + (f"\n> _{_dsc[:200]}_" if _dsc else "")
                          + "\n\nUn **salon privé** sera créé et le **staff prévenu**. "
                            "Confirme si c'est bien ce que tu veux 👇")
                await i.response.send_message(
                    _recap, view=TicketConfirmCreateView(self.pid), ephemeral=True)
        except Exception as ex:
            # Phase 263 : TOUJOURS accuser réception même si cfg/DB plante AVANT l'ack,
            # sinon « Échec de l'interaction » et le bouton paraît cassé.
            _logerr("ticket.create_button", ex)
            try:
                _msg = "❌ Erreur lors de la création du ticket. Réessaie dans un instant."
                if not i.response.is_done():
                    await i.response.send_message(_msg, ephemeral=True)
                else:
                    await i.followup.send(_msg, ephemeral=True)
            except Exception:
                pass

class TicketCreateView(View):
    def __init__(self, pid):
        super().__init__(timeout=None)
        self.add_item(TicketCreateButton(pid))


async def _build_ticket_panel_view(guild, pid):
    """Construit la LayoutView V2 du PANNEAU PUBLIC de tickets (refonte owner 2026-06-16 :
    plus propre + plus pro). Réutilisé à l'ENVOI et au RE-RENDER quand le fondateur active/
    désactive. Inclut le bouton « Créer un ticket » + le toggle fondateur. FAIL-SAFE."""
    c = await cfg(guild.id)
    pnl = (c.get('ticket_panels', {}) or {}).get(pid, {}) or {}
    qs = pnl.get('questions', []) or []
    mx = int(pnl.get('max', 1) or 1)
    disabled = bool(pnl.get('disabled', False))
    name = (pnl.get('name') or 'Support').strip()
    emb_title = (pnl.get('embed_title', '').strip() or f"🎫 {name}")[:256]
    emb_desc = (pnl.get('embed_description', '').strip()
                or "Besoin d'aide ? Ouvre un ticket — l'équipe te répond au plus vite.")[:1500]
    # Liens utiles (format « Texte | url » ou url brute, 1 par ligne).
    links_text = ""
    for line in (pnl.get('embed_links', '') or '').split('\n'):
        line = line.strip()
        if '|' in line:
            _t, _u = line.split('|', 1)
            if _u.strip().startswith('http'):
                links_text += f"• [{_t.strip()}]({_u.strip()})\n"
        elif line.startswith('http'):
            links_text += f"• {line}\n"
        elif line:
            links_text += f"• {line}\n"
    links_text = links_text.strip()

    create_btn = TicketCreateButton(pid)
    # owner 2026-06-29 (audit) : le bouton affiche le TYPE du panneau (sinon « 📩 Créer un
    # ticket » identique partout → le membre se trompe de panneau). custom_id INCHANGÉ.
    try:
        create_btn.label = f"📩 Ouvrir : {name}"[:80]
    except Exception:
        pass
    toggle_btn = Button(
        label=("🔴 Tickets : OFF" if disabled else "🟢 Tickets : ON"),
        style=(discord.ButtonStyle.danger if disabled else discord.ButtonStyle.success),
        custom_id=f"ticket_toggle_{pid}")

    accent = 0xED4245 if disabled else C.BLURPLE
    items = [v2_title(emb_title), v2_subtitle("Système de tickets"), v2_divider()]
    if disabled:
        items.append(v2_body(
            "🔴 **Tickets désactivés temporairement.**\n"
            "_Reviens un peu plus tard — l'équipe les rouvrira bientôt._"))
        items.append(v2_divider())
    # Section principale : description + bouton « Créer un ticket » en accessoire.
    items.append(_section_with_button("📩 Ouvrir un ticket", emb_desc, create_btn))
    # Badges d'info compacts.
    _badge = (f"📝 `{len(qs)}` question(s)   ·   " if qs else "")
    _badge += f"🎫 max `{mx}` ticket(s) simultané(s)"
    items.append(v2_body(_badge))
    if links_text:
        items.append(v2_divider())
        items.append(v2_body(f"🔗 **Liens utiles**\n{links_text}"))
    # Toggle FONDATEUR (discret, en bas) — visible mais utilisable par le fondateur seul.
    items.append(v2_divider())
    items.append(v2_subtitle("⚙️ Activer / désactiver — réservé au fondateur"))
    items.append(discord.ui.ActionRow(toggle_btn))

    class _TicketPanelLayout(LayoutView):
        def __init__(self):
            super().__init__(timeout=None)
            self.add_item(v2_container(*items, color=accent))
    return _TicketPanelLayout()


async def _ticket_toggle_click(i, pid):
    """Toggle ACTIVÉ/DÉSACTIVÉ d'un panneau de tickets — RÉSERVÉ AU FONDATEUR (super-owner).
    Désactivé → la création affiche « désactivé temporairement ». Re-render le panneau.
    FAIL-SAFE / anti Échec-interaction."""
    try:
        if not owner_ids_module.is_super_owner(i.user.id):
            return await i.response.send_message(
                "🔒 Ce réglage est réservé au **fondateur**.", ephemeral=True)
        if i.guild is None:
            return await i.response.send_message("❌ Serveur uniquement.", ephemeral=True)
        c = await cfg(i.guild.id)
        panels = c.get('ticket_panels', {}) or {}
        if pid not in panels:
            return await i.response.send_message("❌ Panneau introuvable.", ephemeral=True)
        new_state = not bool(panels[pid].get('disabled', False))
        panels[pid]['disabled'] = new_state
        await db_set(i.guild.id, 'ticket_panels', panels)
        try:
            view = await _build_ticket_panel_view(i.guild, pid)
            await i.response.edit_message(content=None, view=view, embed=None, attachments=[])
        except Exception as _e:
            print(f"[ticket_toggle render] {_e}")
            if not i.response.is_done():
                await i.response.defer()
        try:
            await i.followup.send(
                f"{'🔴 Tickets **désactivés**' if new_state else '🟢 Tickets **réactivés**'} "
                f"sur ce panneau.", ephemeral=True)
        except Exception:
            pass
    except Exception as ex:
        print(f"[_ticket_toggle_click] {ex}")
        try:
            if not i.response.is_done():
                await i.response.send_message("✅ Pris en compte.", ephemeral=True)
        except Exception:
            pass


class TicketToggleDynamic(discord.ui.DynamicItem[Button],
                          template=r"ticket_toggle_(?P<pid>.+)"):
    """Bouton ACTIVER/DÉSACTIVER du panneau de tickets (fondateur seul). Persistant
    (re-capté au reboot). Le pid (clé du panel) est extrait du custom_id."""
    def __init__(self, pid):
        super().__init__(Button(label="🟢 Tickets : ON", style=discord.ButtonStyle.success,
                                custom_id=f"ticket_toggle_{pid}"))
        self.pid = pid

    @classmethod
    async def from_custom_id(cls, interaction, item, match):
        return cls(match["pid"])

    async def callback(self, i):
        await _ticket_toggle_click(i, self.pid)


def _resolve_transcript_text(text, guild):
    """Rend le contenu LISIBLE pour un transcript pro (owner 2026-06-29 — « pas de pavés de
    numéro ») : <@id>→@pseudo, <@&id>→@rôle, <#id>→#salon, <:nom:id>/<a:nom:id>→:nom:,
    <t:ts:..>→date. FAIL-OPEN (texte tel quel sur erreur)."""
    if not text:
        return text
    try:
        def _user(mm):
            uid = int(mm.group(1))
            m = guild.get_member(uid) if guild else None
            return f"@{m.display_name}" if m else f"@membre-{uid}"
        text = re.sub(r'<@!?(\d+)>', _user, text)

        def _role(mm):
            rid = int(mm.group(1))
            r = guild.get_role(rid) if guild else None
            return f"@{r.name}" if r else f"@rôle-{rid}"
        text = re.sub(r'<@&(\d+)>', _role, text)

        def _chan(mm):
            cid = int(mm.group(1))
            c = guild.get_channel(cid) if guild else None
            return f"#{c.name}" if c else f"#salon-{cid}"
        text = re.sub(r'<#(\d+)>', _chan, text)

        text = re.sub(r'<a?:([A-Za-z0-9_]+):\d+>', r':\1:', text)  # emojis custom → :nom:

        def _ts(mm):
            try:
                return datetime.fromtimestamp(int(mm.group(1)), timezone.utc).strftime('%Y-%m-%d %H:%M')
            except Exception:
                return mm.group(0)
        text = re.sub(r'<t:(\d+)(?::[a-zA-Z])?>', _ts, text)
    except Exception:
        pass
    return text


async def _ticket_transcript_file(ch, tid):
    """Transcript .txt PROFESSIONNEL d'un salon de ticket (log + DM au créateur) : mentions/rôles/
    salons/emojis RÉSOLUS en clair + contenu des embeds inclus. Renvoie un discord.File ou None."""
    try:
        guild = getattr(ch, 'guild', None)
        lines = []
        async for m in ch.history(limit=500, oldest_first=True):
            stamp = m.created_at.strftime('%Y-%m-%d %H:%M')
            body = _resolve_transcript_text(m.content or '', guild)
            # Embeds → texte lisible (titre · description · champs · footer), sinon « [embed] » vide.
            for emb in (m.embeds or []):
                parts = []
                if emb.title:
                    parts.append(str(emb.title))
                if emb.description:
                    parts.append(str(emb.description))
                for f in (getattr(emb, 'fields', None) or []):
                    parts.append(f"{f.name}: {f.value}")
                if getattr(emb, 'footer', None) and emb.footer.text:
                    parts.append(str(emb.footer.text))
                if parts:
                    body += (("\n      " if body.strip() else "")
                             + _resolve_transcript_text(" · ".join(parts), guild).replace("\n", " "))
            if m.attachments:
                body += ' ' + ' '.join(a.url for a in m.attachments)
            if not body.strip():
                body = '[média]'
            who = m.author.display_name
            if getattr(m.author, 'bot', False):
                who += " [bot]"
            lines.append(f"[{stamp}] {who}: {body}")
        if not lines:
            lines = ["(aucun message)"]
        header = (f"Transcript du ticket #{tid}\n"
                  + (f"Serveur : {guild.name}\n" if guild else "")
                  + f"Généré le {now().strftime('%Y-%m-%d %H:%M')} · {len(lines)} message(s)\n"
                  + "=" * 48 + "\n\n")
        data = header + "\n".join(lines)
        return discord.File(io.BytesIO(data.encode('utf-8')), filename=f"ticket-{tid}.txt")
    except Exception:
        return None


