async def _render_ticket_transcript_html(ch, tid, token=None, base_url=None):
    """Construit la CHAÎNE HTML du transcript (thème Discord) : avatars, pseudos, horodatage,
    contenu RÉSOLU (mentions/rôles/emojis) et ÉCHAPPÉ (anti-injection), embeds stylés, images/
    GIFs/vidéos/stickers. Si (token ET base_url) → RÉ-HÉBERGE les images/GIFs sur le volume
    (`transcript_store`) et pointe des URLs PERMANENTES servies ; sinon → URLs CDN Discord (qui
    expirent ~24 h). Retourne str ou None. owner 2026-07-01."""
    try:
        from html import escape as _hesc
        guild = getattr(ch, 'guild', None)
        rehost = bool(token and base_url)
        rows = []
        n = 0
        asset_idx = 0
        rehosted_bytes = 0
        async for m in ch.history(limit=1000, oldest_first=True):
            n += 1
            stamp = m.created_at.strftime('%d/%m/%Y %H:%M')
            try:
                avatar = m.author.display_avatar.url  # CDN stable (pas d'expiration signée)
            except Exception:
                avatar = ''
            name = _hesc(m.author.display_name)
            badge = '<span class="bot">BOT</span>' if getattr(m.author, 'bot', False) else ''
            content = _resolve_transcript_text(m.content or '', guild)
            content_html = _hesc(content).replace('\n', '<br>')
            embeds_html = ''
            for emb in (m.embeds or []):
                try:
                    color = f"#{emb.color.value:06x}" if getattr(emb, 'color', None) else "#5865f2"
                except Exception:
                    color = "#5865f2"
                ep = []
                if emb.title:
                    ep.append(f'<div class="etitle">{_hesc(_resolve_transcript_text(str(emb.title), guild))}</div>')
                if emb.description:
                    ep.append('<div>' + _hesc(_resolve_transcript_text(str(emb.description), guild)).replace('\n', '<br>') + '</div>')
                for f in (getattr(emb, 'fields', None) or []):
                    ep.append(f'<div class="efield"><b>{_hesc(str(f.name))}</b><br>'
                              + _hesc(_resolve_transcript_text(str(f.value), guild)).replace('\n', '<br>') + '</div>')
                if getattr(emb, 'footer', None) and emb.footer.text:
                    ep.append(f'<div class="efooter">{_hesc(str(emb.footer.text))}</div>')
                # image d'embed (ex. GIF Tenor rendu par Discord)
                try:
                    if getattr(emb, 'image', None) and emb.image.url:
                        ep.append(f'<img class="att" loading="lazy" src="{_hesc(emb.image.url)}" alt="">')
                    elif getattr(emb, 'thumbnail', None) and emb.thumbnail.url:
                        ep.append(f'<img class="att" loading="lazy" src="{_hesc(emb.thumbnail.url)}" alt="">')
                except Exception:
                    pass
                if ep:
                    embeds_html += f'<div class="embed" style="border-left:4px solid {color}">' + ''.join(ep) + '</div>'
            att_html = ''
            for a in (m.attachments or []):
                fn = (a.filename or '').lower()
                is_img = (a.content_type or '').startswith('image') or \
                    fn.endswith(('.png', '.jpg', '.jpeg', '.gif', '.webp'))
                is_vid = (a.content_type or '').startswith('video') or \
                    fn.endswith(('.mp4', '.webm', '.mov'))
                # SÉCURITÉ : on ne RÉ-HÉBERGE que des images MATRICIELLES (jamais de SVG →
                # servi same-origin = XSS potentiel). Le SVG reste affiché via l'URL CDN.
                is_rehostable = (a.content_type or '') in (
                    'image/png', 'image/jpeg', 'image/gif', 'image/webp') or \
                    fn.endswith(('.png', '.jpg', '.jpeg', '.gif', '.webp'))
                src = a.url
                # Ré-héberge (permanence) sous plafonds : nombre, taille/asset, budget TOTAL/ticket.
                if is_rehostable and rehost and asset_idx < transcript_store._MAX_ASSETS \
                        and rehosted_bytes < transcript_store._MAX_TICKET_BYTES \
                        and 0 < (getattr(a, 'size', 0) or 0) <= transcript_store._MAX_ASSET_BYTES:
                    try:
                        data = await a.read()
                        ext = fn.rsplit('.', 1)[-1] if '.' in fn else 'png'
                        served = await asyncio.to_thread(
                            transcript_store.save_asset, token, asset_idx, data, ext)
                        if served:
                            src = base_url + served
                            asset_idx += 1
                            rehosted_bytes += len(data)
                    except Exception:
                        src = a.url
                u = _hesc(src)
                if is_img:
                    att_html += f'<img class="att" loading="lazy" src="{u}" alt="image">'
                elif is_vid:
                    att_html += f'<video class="att" src="{u}" controls preload="none"></video>'
                else:
                    att_html += f'<div><a href="{u}" target="_blank" rel="noopener">📎 {_hesc(a.filename)}</a></div>'
            # Stickers (URL CDN stable) → affichés comme image.
            for st in (getattr(m, 'stickers', None) or []):
                try:
                    if getattr(st, 'url', None):
                        att_html += f'<img class="att" loading="lazy" src="{_hesc(st.url)}" alt="sticker" title="{_hesc(getattr(st, "name", "sticker"))}">'
                except Exception:
                    pass
            if not content_html.strip() and not embeds_html and not att_html:
                content_html = '<i style="color:#949ba4">[média]</i>'
            rows.append(
                f'<div class="msg"><img class="avatar" loading="lazy" src="{_hesc(avatar)}" alt="">'
                f'<div class="mbody"><div class="mhead"><span class="author">{name}</span>{badge}'
                f'<span class="ts">{stamp}</span></div>'
                f'<div class="content">{content_html}</div>{embeds_html}{att_html}</div></div>')
        title = _hesc(f"Ticket #{tid}") + (f" — {_hesc(guild.name)}" if guild else "")
        body = ''.join(rows) or '<i style="color:#949ba4">(aucun message)</i>'
        return (
            "<!DOCTYPE html><html lang='fr'><head><meta charset='utf-8'>"
            "<meta name='viewport' content='width=device-width, initial-scale=1'>"
            f"<title>{title}</title><style>{_TRANSCRIPT_CSS}</style></head><body>"
            f"<div class='header'><h1>🎫 {title}</h1>"
            f"<div class='sub'>{n} message(s) · généré le {now().strftime('%d/%m/%Y %H:%M')}</div></div>"
            f"<div class='chat'>{body}</div></body></html>")
    except Exception as ex:
        print(f"[_render_ticket_transcript_html] {ex}")
        return None


async def _ticket_transcript_html(ch, tid):
    """Wrapper compat : renvoie un discord.File (.html) avec URLs CDN (pas de ré-hébergement)."""
    html = await _render_ticket_transcript_html(ch, tid, token=None, base_url=None)
    if not html:
        return None
    try:
        return discord.File(io.BytesIO(html.encode('utf-8')), filename=f"ticket-{tid}.html")
    except Exception:
        return None


class TicketCloseModal(Modal):
    """Fermeture de ticket EN 2 TEMPS (quick-win pro) : le bouton 🔒 ouvre ce modal —
    la SOUMISSION = la confirmation, le ✖ annule (fini le delete instantané sans filet).
    À la fermeture : transcript .txt envoyé en DM au CRÉATEUR + récap (avec transcript)
    dans le salon de logs, puis suppression après un court délai. NB : ceci n'a RIEN à
    voir avec l'auto-close (désactivé) — c'est une fermeture 100 % MANUELLE par le staff."""
    def __init__(self, tk, prefill: str = ""):
        super().__init__(title="🔒 Fermer le ticket")
        self.tk = tk
        # `prefill` = motif rapide pré-rempli (cliqué dans TicketCloseReasonView) ;
        # le staff peut le garder, le compléter ou l'effacer avant de soumettre.
        self.reason = TextInput(
            label="Raison de fermeture (optionnel)",
            placeholder="Ex. Résolu · doublon · pas de réponse… (laisse vide si tu veux)",
            default=(prefill or None),
            style=discord.TextStyle.paragraph, required=False, max_length=500)
        self.add_item(self.reason)

    async def on_submit(self, i):
        try:
            await i.response.defer()
        except Exception:
            pass
        ch = i.channel
        tk = self.tk
        reason = (self.reason.value or '').strip() or "Aucune raison précisée"
        tid = tk.get('id', '?')
        # 1) Log staff (envoie déjà l'embed + transcript dans le salon de logs).
        try:
            tu_log = i.guild.get_member(tk['user'])
            await send_ticket_log(i.guild, 'close', tu_log or tk['user'], tk, closer=i.user, ch=ch)
        except Exception:
            pass
        # 2) Transcript en DM au CRÉATEUR (fallback silencieux si DM fermés).
        try:
            creator = i.guild.get_member(tk['user'])
            if creator:
                # Réutilise l'URL rendue par send_ticket_log (sinon rend un fichier de repli).
                _dm_url = _recent_transcript_urls.pop(str(tid), None)
                f = None
                if not _dm_url:
                    f = await _ticket_transcript_html(ch, tid) or await _ticket_transcript_file(ch, tid)
                _dm_link_line = (
                    f"🔗 **Transcript complet (page web) :** {_dm_url}\n"
                    if _dm_url else
                    "_Transcript de la conversation ci-joint._\n")
                dm_txt = (
                    f"🔒 Ton ticket **#{tid}** sur **{i.guild.name}** a été fermé par "
                    f"**{i.user.display_name}**.\n**Raison :** {reason}\n\n"
                    f"{_dm_link_line}"
                    f"_Tu peux rouvrir un ticket si tu as encore besoin d'aide._\n\n"
                    f"**Comment s'est passée la prise en charge ?** _(un clic — ça nous aide)_")
                # #16 : note de satisfaction (boutons persistants) si l'id de ticket est numérique.
                _fbview = None
                try:
                    _fbview = _ticket_feedback_view(i.guild.id, int(tid), i.user.id)
                except Exception:
                    _fbview = None
                try:
                    _kw = {"content": dm_txt}
                    if f:
                        _kw["file"] = f
                    if _fbview:
                        _kw["view"] = _fbview
                    await creator.send(**_kw)
                except Exception:
                    pass
        except Exception:
            pass
        # 3) Marquer fermé (DB) + annonce dans le salon + suppression différée.
        try:
            async with get_db() as db:
                await db.execute("UPDATE tickets SET status='closed' WHERE channel_id=?", (ch.id,))
                await db.commit()
        except Exception as _e:
            _logerr("ticket.close_db", _e)
        try:  # Lot 2 : audit-trail (qui a fermé, motif)
            await tix_module.log_action(i.guild.id, ch.id, i.user.id, "close", reason[:200])
        except Exception:
            pass
        try:
            await ch.send(
                f"🔒 **Ticket fermé** par {i.user.mention}\n**Raison :** {reason}\n"
                f"_Transcript envoyé en MP au créateur. Suppression du salon dans 5 s…_")
        except Exception:
            pass
        await asyncio.sleep(5)
        try:
            await ch.delete()
        except Exception:
            pass


class TicketControlView(View):
    def __init__(self):
        super().__init__(timeout=None)
    
    @discord.ui.button(label="🙋 Prendre en charge", style=discord.ButtonStyle.success, custom_id="ticket_ctrl_claim")
    async def claim(self, i, btn):
        try:
            tk = await get_ticket(i.channel.id)
            if not tk: return await i.response.send_message("❌ Ticket non trouvé", ephemeral=True)
            c = await cfg(i.guild.id)
            sr = i.guild.get_role(c.get('ticket_staff', 0))
            
            if i.user.id == tk['user']:
                return await i.response.send_message("❌ Vous ne pouvez pas prendre votre propre ticket", ephemeral=True)
            
            # Vérifier si l'utilisateur est immunisé (peut tout faire sur les tickets)
            is_immune = await is_fully_immune(i.user)
            
            is_s = sr and sr in i.user.roles
            is_o = i.user.id == i.guild.owner_id
            is_a = i.user.guild_permissions.administrator
            
            if not (is_s or is_o or is_a or is_immune):
                return await i.response.send_message("❌ Réservé au staff", ephemeral=True)
            
            # Si le ticket est déjà claim, vérifier si on peut sur-claim
            if tk['claimed'] and tk['claimed'] != i.user.id:
                if not (is_immune or is_o or is_a):
                    return await i.response.send_message(
                        f"❌ Ce ticket est déjà pris par <@{tk['claimed']}>.\n"
                        "*Seuls les immunisés/admins peuvent sur-claim.*",
                        ephemeral=True
                    )
                # Sur-claim autorisé
                await i.channel.send(f"⚠️ **Sur-claim** : {i.user.mention} reprend ce ticket (anciennement <@{tk['claimed']}>)")
            
            tu = i.guild.get_member(tk['user'])
            ow = {
                i.guild.default_role: discord.PermissionOverwrite(view_channel=False),
                i.guild.me: discord.PermissionOverwrite(view_channel=True, send_messages=True, manage_channels=True, manage_permissions=True),
                # owner 2026-07-20 : le staff qui CLAIM doit AUSSI pouvoir poster images/vidéos/GIF/
                # liens (avant : send_messages seul → média bloqué pour le staff en charge).
                i.user: discord.PermissionOverwrite(
                    view_channel=True, send_messages=True, read_message_history=True,
                    attach_files=True, embed_links=True, add_reactions=True,
                    use_external_emojis=True, use_external_stickers=True)
            }
            if tu:
                ow[tu] = discord.PermissionOverwrite(view_channel=True, send_messages=True, attach_files=True, read_message_history=True, embed_links=True, add_reactions=True, use_external_emojis=True, use_external_stickers=True)
            if i.guild.owner and i.guild.owner != i.user:
                ow[i.guild.owner] = discord.PermissionOverwrite(view_channel=True, send_messages=True, read_message_history=True, manage_channels=True)
            if sr:
                ow[sr] = discord.PermissionOverwrite(view_channel=False)
            await i.channel.edit(overwrites=ow)
            async with get_db() as db:
                await db.execute('UPDATE tickets SET claimed_by=? WHERE channel_id=?', (i.user.id, i.channel.id))
                await db.commit()
            # Phase 235.4 : le panneau de ticket est posté par un WEBHOOK (nom custom
            # « Tickets ») → i.message.edit() échouait (403 50005 : on ne peut pas
            # éditer le message d'un AUTRE auteur). On met à jour le bouton via la
            # RÉPONSE d'interaction (autorisée sur le message du composant, même
            # webhook), PUIS on annonce dans le salon. Plus de 50005.
            btn.disabled = True
            btn.label = f"Pris par {i.user.display_name}"[:80]
            btn.style = discord.ButtonStyle.secondary
            try:
                await i.response.edit_message(view=self)
            except Exception:
                # Filet : si l'édition du panneau échoue, on acquitte quand même
                # l'interaction pour éviter « Échec de l'interaction ».
                try:
                    if not i.response.is_done():
                        await i.response.defer()
                except Exception:
                    pass
            try:
                await i.channel.send(
                    f"✅ **{i.user.display_name}** prend ce ticket en charge\n\n"
                    "*Les autres staffs ne peuvent plus voir ce ticket.*")
            except Exception:
                pass
            await send_ticket_log(i.guild, 'claim', tk['user'], tk, extra=i.user.id)
            try:  # Lot 2 : audit-trail (qui a pris en charge, quand)
                await tix_module.log_action(i.guild.id, i.channel.id, i.user.id, "claim")
            except Exception:
                pass
        except Exception as _tk_ex:
            _logerr("ticket.claim", _tk_ex)
            import traceback; traceback.print_exc()
            try:
                if not i.response.is_done():
                    await i.response.send_message(f"❌ Erreur : `{type(_tk_ex).__name__}: {_tk_ex}`", ephemeral=True)
                else:
                    await i.followup.send(f"❌ Erreur : `{type(_tk_ex).__name__}: {_tk_ex}`", ephemeral=True)
            except Exception:
                pass
    
    @discord.ui.button(label="➕ Ajouter Staff", style=discord.ButtonStyle.primary, custom_id="ticket_ctrl_add")
    async def add_staff(self, i, btn):
        try:
            tk = await get_ticket(i.channel.id)
            if not tk: return await i.response.send_message("❌ Ticket non trouvé", ephemeral=True)
            
            # Vérifier l'immunité
            is_immune = await is_fully_immune(i.user)
            is_o = i.user.id == i.guild.owner_id
            is_c = i.user.id == tk['claimed']
            is_a = i.user.guild_permissions.administrator
            
            # Les immunisés peuvent toujours ajouter du staff
            if not tk['claimed'] and not is_immune:
                return await i.response.send_message("❌ Le ticket doit d'abord être pris en charge", ephemeral=True)
            
            if not (is_c or is_o or is_a or is_immune):
                return await i.response.send_message("❌ Seul le staff en charge peut ajouter quelqu'un", ephemeral=True)
            c = await cfg(i.guild.id)
            sr = i.guild.get_role(c.get('ticket_staff', 0))
            if not sr:
                return await i.response.send_message("❌ Aucun rôle staff configuré", ephemeral=True)
            staffs = [m for m in sr.members if m.id != tk['claimed'] and m.id != tk['user']][:25]
            if not staffs:
                return await i.response.send_message("❌ Aucun autre staff disponible", ephemeral=True)
            opts = [discord.SelectOption(label=f"@{m.display_name}"[:25], value=str(m.id)) for m in staffs]
            await i.response.send_message("👥 Choisir un staff:", view=AddStaffView(opts, i.channel.id), ephemeral=True)
        except Exception as _tk_ex:
            _logerr("ticket.add_staff_open", _tk_ex)
            import traceback; traceback.print_exc()
            try:
                if not i.response.is_done():
                    await i.response.send_message(f"❌ Erreur : `{type(_tk_ex).__name__}: {_tk_ex}`", ephemeral=True)
                else:
                    await i.followup.send(f"❌ Erreur : `{type(_tk_ex).__name__}: {_tk_ex}`", ephemeral=True)
            except Exception:
                pass
    
    @discord.ui.button(label="🔄 Transférer", style=discord.ButtonStyle.primary, custom_id="ticket_ctrl_transfer")
    async def transfer(self, i, btn):
        # POURQUOI : transfert de la PRISE EN CHARGE uniquement (réassigne claimed_by +
        # recalcule les overwrites comme Claim). Jamais de fermeture, jamais d'argent/items.
        # Réservé au claimant actuel ou à un admin/immunisé. custom_id stable (persistant).
        try:
            tk = await get_ticket(i.channel.id)
            if not tk: return await i.response.send_message("❌ Ticket non trouvé", ephemeral=True)

            # Garde : le ticket doit déjà être pris pour pouvoir être transféré.
            if not tk['claimed']:
                return await i.response.send_message("❌ Personne n'a encore pris ce ticket", ephemeral=True)

            is_immune = await is_fully_immune(i.user)
            is_o = i.user.id == i.guild.owner_id
            is_c = i.user.id == tk['claimed']
            is_a = i.user.guild_permissions.administrator

            # Seul le staff EN CHARGE (claimant) ou un admin/owner/immunisé peut transférer.
            if not (is_c or is_o or is_a or is_immune):
                return await i.response.send_message("❌ Seul le staff en charge peut transférer", ephemeral=True)

            c = await cfg(i.guild.id)
            sr = i.guild.get_role(c.get('ticket_staff', 0))
            if not sr:
                return await i.response.send_message("❌ Aucun rôle staff configuré", ephemeral=True)
            # Destinataires possibles : membres du rôle staff, hors claimant actuel et hors créateur.
            staffs = [m for m in sr.members if m.id != tk['claimed'] and m.id != tk['user']][:25]
            if not staffs:
                return await i.response.send_message("❌ Aucun autre staff disponible", ephemeral=True)
            opts = [discord.SelectOption(label=f"@{m.display_name}"[:25], value=str(m.id)) for m in staffs]
            await i.response.send_message("🔄 Transférer la prise en charge à :", view=TransferTicketView(opts, i.channel.id), ephemeral=True)
        except Exception as _tk_ex:
            _logerr("ticket.transfer_open", _tk_ex)
            import traceback; traceback.print_exc()
            try:
                if not i.response.is_done():
                    await i.response.send_message(f"❌ Erreur : `{type(_tk_ex).__name__}: {_tk_ex}`", ephemeral=True)
                else:
                    await i.followup.send(f"❌ Erreur : `{type(_tk_ex).__name__}: {_tk_ex}`", ephemeral=True)
            except Exception:
                pass

