def advanced_scam_check(content):
    """Vérifie le contenu pour détecter les scams avec analyse avancée"""
    content_lower = content.lower()
    
    # 1. Vérifier les mots-clés de scam
    scam_score = 0
    detected_keywords = []
    
    for keyword in SCAM_KEYWORDS:
        if keyword in content_lower:
            scam_score += 10
            detected_keywords.append(keyword)
    
    # 2. Combinaisons dangereuses
    dangerous_combos = [
        (['free', 'nitro', 'http'], 30),
        (['@everyone', 'http'], 25),
        (['@here', 'http'], 25),
        (['free', 'gift', 'http'], 25),
        (['click', 'claim', 'http'], 20),
        (['dm', 'me', 'money'], 15),
        (['crypto', 'investment', 'profit'], 20),
        (['send', 'eth', 'receive'], 30),
        (['double', 'crypto'], 30),
        # 2026 (owner 2026-06-21) : faux ban/appeal + lien = arnaque quasi-certaine.
        (['appeal', 'ban', 'http'], 25),
        (['banned', 'click', 'http'], 20),
    ]
    
    for combo, score in dangerous_combos:
        if all(word in content_lower for word in combo):
            scam_score += score
            detected_keywords.extend(combo)
    
    # 3. Urgence artificielle
    urgency_patterns = [
        r'(only|seulement)\s*\d+\s*(left|remaining|restant)',
        r'(expire|end)s?\s*(in|dans)\s*\d+',
        r'(hurry|vite|dépêche)',
        r'(last|dernier)\s*(chance|opportunit)',
        r'(act|agir)\s*(now|maintenant)',
    ]
    
    for pattern in urgency_patterns:
        if re.search(pattern, content_lower):
            scam_score += 10

    # owner 2026-06-27 : HÉBERGEMENT GRATUIT abusé pour le phishing (faux support Discord/Steam,
    # « appeal your ban », faux Nitro…). Un domaine gratuit SEUL = souvent légitime (portfolio
    # github.io) → on n'agit QUE s'il s'accompagne d'une PHRASE de phishing claire (haute précision).
    if any(h in content_lower for h in _FREE_HOST_DOMAINS) and _FREE_HOST_SCAM_RE.search(content_lower):
        scam_score += 30
        detected_keywords.append('hébergement gratuit + phishing')

    # Seuil de détection
    if scam_score >= 25:
        return True, ", ".join(set(detected_keywords[:5])), scam_score

    return False, None, 0


def check_dangerous_file(filename):
    """Vérifie si un fichier a une extension dangereuse OU un nom DÉGUISÉ (caractères de
    contrôle bidi / RTL-override qui masquent la vraie extension — ex. « photo‮gpj.exe »
    s'affiche « photo.exe.jpg »). owner 2026-06-21 #7. L'extension finale (.exe…) couvre
    déjà la double-extension type photo.jpg.exe (endswith)."""
    filename_lower = filename.lower()
    # Caractères de contrôle de direction (LRE/RLE/PDF/LRO/RLO + isolates) = déguisement.
    if any(ord(ch) in (0x202A, 0x202B, 0x202C, 0x202D, 0x202E,
                       0x2066, 0x2067, 0x2068, 0x2069) for ch in (filename or "")):
        return True, "nom déguisé (caractère RTL/bidi)"
    for ext in DANGEROUS_EXTENSIONS:
        if filename_lower.endswith(ext):
            return True, ext
    return False, None


