def check_shortener(ct):
    """Détecte un raccourcisseur d'URL (destination masquée). owner 2026-06-21 #6.
    Plus fort qu'un dépliage réseau : on n'autorise tout simplement pas de masquer la
    destination (un lien légitime peut être posté en clair)."""
    try:
        for host in re.findall(r'https?://([^\s/:?#]+)', ct or "", re.IGNORECASE):
            dom = host.lower()
            if dom.startswith('www.'):
                dom = dom[4:]
            if dom in URL_SHORTENERS:
                return True, dom
    except Exception:
        pass
    return False, None

def check_qr_code_scam(content):
    """Détecte les tentatives de scam par QR code"""
    qr_patterns = [
        r'scan.*qr.*code',
        r'qr.*code.*scan',
        r'scanner.*code',
        r'discord.*token',
        r'login.*qr',
        r'authenticate.*qr',
        r'qr.*gift',
        r'qr.*nitro',
    ]
    
    content_lower = content.lower()
    for pattern in qr_patterns:
        if re.search(pattern, content_lower):
            return True, pattern
    
    return False, None

