class _RgpdPurgeModal(Modal, title="🔒 Effacement RGPD d'un membre"):
    """Saisie de l'ID + confirmation explicite, puis purge via gdpr.purge_user. Defer-first
    (la purge balaie ~280 tables → on ne dépasse jamais la fenêtre 3 s)."""
    def __init__(self, g):
        super().__init__(timeout=300)
        self.g = g
        self.uid = TextInput(label="ID Discord du membre", placeholder="ex. 123456789012345678",
                             required=True, max_length=20)
        self.confirm = TextInput(label="Tape PURGER pour confirmer", placeholder="PURGER",
                                 required=True, max_length=10)
        self.add_item(self.uid)
        self.add_item(self.confirm)

    async def on_submit(self, i):
        try:
            await i.response.defer(ephemeral=True, thinking=True)
        except Exception:
            pass
        # ⚠️ DURCISSEMENT SÉCU (owner 2026-06-16) : l'effacement RGPD est DESTRUCTIF (purge
        # ~280 tables). Défense en profondeur — on le réserve au PROPRIÉTAIRE du serveur +
        # super-owner, même si un admin atteint ce modal via le panneau (qui, lui, reste
        # consultable par les admins pour le diagnostic de carte non destructif).
        try:
            _purge_ok = (i.user.id == (i.guild.owner_id if i.guild else 0)
                         or owner_ids_module.is_super_owner(i.user.id))
        except Exception:
            _purge_ok = False
        if not _purge_ok:
            try:
                await i.followup.send(
                    "🔒 L'effacement RGPD est réservé au **propriétaire du serveur**.\n"
                    "**Aucune donnée n'a été touchée.**", ephemeral=True)
            except Exception:
                pass
            return
        if (self.confirm.value or "").strip().upper() != "PURGER":
            try:
                await i.followup.send("❌ Confirmation absente (tape `PURGER`). **Aucune donnée touchée.**", ephemeral=True)
            except Exception:
                pass
            return
        try:
            uid = int((self.uid.value or "").strip())
        except Exception:
            try:
                await i.followup.send("❌ ID invalide. **Aucune donnée touchée.**", ephemeral=True)
            except Exception:
                pass
            return
        # Hash confession (MÊME schéma que la création) pour matcher les tables HMAC.
        try:
            secret = f"conf_{self.g.id}_{_CONFESSION_HMAC_KEY}"
            hmac_user = _hmac_p41.new(secret.encode(), f"{uid}".encode(), 'sha256').hexdigest()[:16]
        except Exception:
            hmac_user = None
        try:
            async with get_db() as db:
                summ = await gdpr.purge_user(db, self.g.id, uid, hmac_user=hmac_user)
        except Exception as ex:
            print(f"[gdpr purge {uid}] FATAL {ex}")
            try:
                await i.followup.send(f"❌ Échec de la purge : `{ex}`", ephemeral=True)
            except Exception:
                pass
            return
        d = sum((summ.get("deleted") or {}).values())
        a = sum((summ.get("anonymized") or {}).values())
        b = sum((summ.get("blobs") or {}).values())
        errs = summ.get("errors") or []
        if errs:
            print(f"[gdpr purge {uid}] {len(errs)} skip/erreur(s) : {errs[:40]}")
        txt = (f"✅ **Effacement RGPD effectué** pour `{uid}`.\n"
               f"• Lignes supprimées : **{d}**\n"
               f"• Lignes anonymisées (audit/sécu préservés) : **{a}**\n"
               f"• Blobs JSON nettoyés : **{b}**\n"
               f"• Tables ignorées (absentes/erreurs) : **{len(errs)}**"
               + ("\n_(détails techniques dans les logs Railway)_" if errs else ""))
        try:
            await i.followup.send(txt[:1900], ephemeral=True)
        except Exception:
            pass


async def _afficher_panneau(vue, interaction, edit: bool) -> None:
    """Affiche un panneau — et supporte une interaction DÉJÀ acquittée.

    ⚠️ PIÈGE À NE PAS DÉFAIRE — « L'INTERACTION A ÉCHOUÉ », SIGNALÉ EN PROD.
    Discord laisse 3 secondes pour acquitter. Les panneaux lisent la base avant
    de répondre ; l'onglet Veille Roblox fait quatre lectures. Au-delà des 3 s,
    Discord affiche « L'interaction a échoué » et refuse tout.

    `_module_select` fait donc `defer()` d'abord. Mais `defer()` consomme la
    réponse : `response.edit_message()` lève ensuite `InteractionResponded`.
    D'où ce point de passage unique, qui choisit le bon appel selon l'état.

    Ne PAS revenir à `interaction.response.edit_message()` en direct : le
    chemin nominal est identique, seul le cas « déjà acquitté » change.
    """
    if edit:
        if interaction.response.is_done():
            await interaction.edit_original_response(
                content=None, view=vue, embed=None, attachments=[])
        else:
            await interaction.response.edit_message(
                content=None, view=vue, embed=None, attachments=[])
    else:
        if interaction.response.is_done():
            await interaction.followup.send(view=vue, ephemeral=True)
        else:
            await interaction.response.send_message(view=vue, ephemeral=True)


class RgpdPanelV2(LayoutView):
    """🔒 Données & RGPD (owner/admin via /configure). Droit à l'effacement (art. 17) :
    purge/anonymise toutes les données d'un membre + diagnostic de la carte RGPD."""
    def __init__(self, u, g):
        super().__init__(timeout=600)
        self.u = u
        self.g = g

    async def interaction_check(self, i):
        try:
            if i.user.id != self.u.id:
                return False
            return bool(i.user.guild_permissions.manage_guild)
        except Exception:
            return False

    async def render_to(self, interaction, *, edit: bool = True):
        b_purge = Button(label="Effacer un membre", emoji="🗑️", style=discord.ButtonStyle.danger, custom_id="rgpd_purge")
        b_purge.callback = self._open_purge
        b_check = Button(label="Vérifier la carte", emoji="🩺", style=discord.ButtonStyle.secondary, custom_id="rgpd_check")
        b_check.callback = self._check
        b_back = Button(label="◀️ Retour", style=discord.ButtonStyle.secondary, custom_id="rgpd_back")
        b_back.callback = self._back

        self.clear_items()
        self.add_item(v2_container(
            v2_title("🔒 Données & RGPD"),
            v2_subtitle("Droit à l'effacement (art. 17 RGPD)"),
            v2_divider(),
            v2_body(
                "**🗑️ Effacer un membre** : supprime ou anonymise *toutes* ses données de ce serveur "
                "(éco, inventaire, stats, préférences, logs…). L'historique de modération d'**autrui** "
                "est préservé — seul l'identifiant du membre y est neutralisé. _Irréversible : une "
                "confirmation (`PURGER`) est demandée._\n\n"
                "**🩺 Vérifier la carte** : compare le registre RGPD au schéma réel de la base "
                "(diagnostic — repère une table éventuellement oubliée).\n\n"
                "_Les logs de sécurité datés sont purgés automatiquement chaque jour (rétention)._"
            ),
            v2_divider(),
            discord.ui.ActionRow(b_purge, b_check, b_back),
            color=Palette.PRIMARY,
        ))
        await _afficher_panneau(self, interaction, edit)

    async def _open_purge(self, i):
        try:
            await i.response.send_modal(_RgpdPurgeModal(self.g))
        except Exception as ex:
            print(f"[RgpdPanelV2 _open_purge] {ex}")

    async def _check(self, i):
        try:
            await i.response.defer(ephemeral=True, thinking=True)
        except Exception:
            pass
        try:
            async with get_db() as db:
                drift = await gdpr.validate_map(db)
        except Exception as ex:
            try:
                await i.followup.send(f"❌ {ex}", ephemeral=True)
            except Exception:
                pass
            return
        mt = drift.get("missing_tables") or []
        mc = drift.get("missing_columns") or []
        if not mt and not mc:
            await i.followup.send("✅ Carte RGPD **conforme** au schéma.", ephemeral=True)
            return
        msg = ""
        if mc:
            msg += "⚠️ **Colonnes absentes** (vraie dérive à corriger) : " + ", ".join(f"{t}.{c}" for t, c in mc[:25]) + "\n"
        if mt:
            msg += (f"ℹ️ **Tables non encore créées** ({len(mt)}) — normal : créées à la 1ʳᵉ "
                    f"utilisation de leur fonctionnalité (purge fail-safe) : {', '.join(mt[:25])}")
        await i.followup.send((msg or "✅ Conforme.")[:1900], ephemeral=True)

    async def _back(self, i):
        try:
            await MainPanelV2(self.u, self.g).render_to(i, edit=True)
        except Exception as ex:
            print(f"[RgpdPanelV2 _back] {ex}")


