async def _event_notify_role(guild, etype: str, *, create: bool = True):
    """Get-or-create le rôle 🔔 de la catégorie `etype`. Retourne le rôle ou None.
    create=False → simple lookup (utilisé au spawn : on ne ping que si le rôle existe
    déjà, càd si ≥1 membre s'est abonné)."""
    if guild is None or etype not in _EVENT_NOTIFY_TYPES:
        return None
    name = _EVENT_NOTIFY_TYPES[etype][0]
    cfg_key = f"notify_type_{etype}_id"
    try:
        c = await cfg(guild.id)
        rid = int(c.get(cfg_key, 0) or 0)
        if rid:
            r = guild.get_role(rid)
            if r:
                return r
        r = discord.utils.get(guild.roles, name=name)
        if r:
            await db_set(guild.id, cfg_key, r.id)
            return r
        if not create:
            return None
        me = guild.me
        if not (me and me.guild_permissions.manage_roles):
            return None
        r = await guild.create_role(name=name, mentionable=False,
                                    reason="Notif par type (opt-in bouton)")
        await db_set(guild.id, cfg_key, r.id)
        return r
    except Exception as ex:
        print(f"[_event_notify_role {etype}] {ex}")
        return None




async def _toggle_event_notify(i: discord.Interaction, etype: str):
    """Toggle le rôle 🔔 de la catégorie `etype` pour le membre. Réutilisé par le
    DynamicItem EventNotifyButton (panneaux V2 nus) ET par les boutons à callback des
    Views suivies/enregistrées (boss raid, world boss) — où un bouton nu ne serait pas
    capté. Fail-open."""
    try:
        await i.response.defer(ephemeral=True)
    except (discord.NotFound, discord.HTTPException, discord.InteractionResponded):
        pass
    if i.guild is None:
        try:
            await i.followup.send("❌ Serveur uniquement.", ephemeral=True)
        except Exception:
            pass
        return
    label = _EVENT_NOTIFY_TYPES.get(etype, ("ce type",))[0]
    role = await _event_notify_role(i.guild, etype, create=True)
    if role is None:
        try:
            await i.followup.send(
                "❌ Rôle de notif indisponible (permissions). Préviens un admin.",
                ephemeral=True)
        except Exception:
            pass
        return
    try:
        member = i.user if isinstance(i.user, discord.Member) else i.guild.get_member(i.user.id)
        if member is None:
            return
        if role in member.roles:
            await member.remove_roles(role, reason="Désabonnement notif (bouton)")
            msg = f"🔕 Ok, tu ne seras **plus** notifié pour **{label}**."
        else:
            await member.add_roles(role, reason="Abonnement notif (bouton)")
            msg = (f"🔔 C'est noté ! Tu seras notifié pour **{label}**.\n"
                   f"_Reclique pour te désabonner._")
        await i.followup.send(msg, ephemeral=True)
    except discord.Forbidden:
        try:
            await i.followup.send("❌ Je n'ai pas la permission de gérer ce rôle.", ephemeral=True)
        except Exception:
            pass
    except Exception as ex:
        print(f"[_toggle_event_notify {etype}] {ex}")
        try:
            await i.followup.send("❌ Erreur, réessaie.", ephemeral=True)
        except Exception:
            pass


class EventNotifyButton(discord.ui.DynamicItem[Button],
                        template=r"evtnotif:(?P<etype>[a-z_]+)"):
    """1er clic = abonné au type, 2e clic = désabonné. Persistant (DynamicItem)."""
    def __init__(self, etype: str):
        super().__init__(Button(label="🔔 Me notifier",
                                style=discord.ButtonStyle.secondary,
                                custom_id=f"evtnotif:{etype}"))
        self.etype = etype

    @classmethod
    async def from_custom_id(cls, interaction, item, match):
        return cls(match["etype"])

    async def callback(self, i: discord.Interaction):
        await _toggle_event_notify(i, self.etype)






# ═══════════════ NOTE DE SATISFACTION DE TICKET (#16) ═══════════════
# À la fermeture, le DM transcript au créateur porte 3 boutons de note. Persistant
# (DynamicItem) → marche DANS le MP (i.guild=None, IDs portés par le custom_id) et survit
# aux reboots. 1 note/ticket (UPSERT). Distingue « fermé » de « vraiment résolu ». L'avis
# remonte au salon de logs pour que l'owner voie la qualité réelle du support.
_TFB_META = {3: ("👍 Résolu", discord.ButtonStyle.success),
             2: ("😐 Moyen", discord.ButtonStyle.secondary),
             1: ("👎 Non résolu", discord.ButtonStyle.danger)}


async def _ensure_ticket_feedback_table():
    try:
        async with get_db() as db:
            await db.execute(
                "CREATE TABLE IF NOT EXISTS ticket_feedback ("
                "guild_id INTEGER, ticket_id INTEGER, user_id INTEGER, staff_id INTEGER, "
                "rating INTEGER, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, "
                "PRIMARY KEY (guild_id, ticket_id))")
            await db.commit()
    except Exception as ex:
        print(f"[ticket_feedback table] {ex}")


class TicketFeedbackButton(discord.ui.DynamicItem[Button],
                           template=r"tfb:(?P<g>\d+):(?P<t>\d+):(?P<s>\d+):(?P<r>[123])"):
    """Bouton de note de satisfaction (persistant, capté même dans le MP du bot)."""
    def __init__(self, gid, tid, sid, rating):
        self.gid, self.tid, self.sid, self.rating = int(gid), int(tid), int(sid), int(rating)
        label, style = _TFB_META.get(int(rating), ("Note", discord.ButtonStyle.secondary))
        super().__init__(Button(label=label, style=style,
                                custom_id=f"tfb:{int(gid)}:{int(tid)}:{int(sid)}:{int(rating)}"))

    @classmethod
    async def from_custom_id(cls, interaction, item, match):
        return cls(int(match["g"]), int(match["t"]), int(match["s"]), int(match["r"]))

    async def callback(self, i):
        try:
            await _ensure_ticket_feedback_table()
            async with get_db() as db:
                await db.execute(
                    "INSERT INTO ticket_feedback(guild_id, ticket_id, user_id, staff_id, rating) "
                    "VALUES(?,?,?,?,?) ON CONFLICT(guild_id, ticket_id) DO UPDATE SET "
                    "rating=excluded.rating, user_id=excluded.user_id, created_at=CURRENT_TIMESTAMP",
                    (self.gid, self.tid, i.user.id, self.sid, self.rating))
                await db.commit()
        except Exception as ex:
            print(f"[ticket_feedback record] {ex}")
        # Remonte l'avis au salon de logs (visibilité owner sur la qualité réelle du support).
        try:
            guild = bot.get_guild(self.gid)
            if guild is not None:
                c = await cfg(self.gid)
                log_ch = guild.get_channel(int(c.get('mod_log_channel', 0) or 0))
                if log_ch is not None:
                    emo = {3: "👍 Résolu", 2: "😐 Moyen", 1: "👎 Non résolu"}.get(self.rating, "?")
                    await log_ch.send(
                        f"⭐ **Satisfaction ticket #{self.tid}** : {emo} — par {getattr(i.user, 'mention', i.user.id)} "
                        f"(staff : <@{self.sid}>)",
                        allowed_mentions=discord.AllowedMentions.none())
        except Exception:
            pass
        try:
            await i.response.send_message(
                "🙏 **Merci pour ton retour !** Ça nous aide à améliorer le support.", ephemeral=True)
        except Exception:
            try:
                await i.followup.send("🙏 Merci pour ton retour !", ephemeral=True)
            except Exception:
                pass


def _ticket_feedback_view(gid, tid, sid):
    """View jetable portant les 3 boutons de note (captés par TicketFeedbackButton)."""
    try:
        v = discord.ui.View(timeout=None)
        for r in (3, 2, 1):
            v.add_item(TicketFeedbackButton(gid, tid, sid, r))
        return v
    except Exception:
        return None


