class LogsEventsPanelV2(LayoutView):
    """Phase 26.3 — toggle individuel par event_type (en plus des catégories).

    Permet de désactiver précisément certains événements (ex: 'msg.delete' uniquement)
    sans toucher à la catégorie entière.
    """

    def __init__(self, u, g, category: str = None):
        super().__init__(timeout=600)
        self.u = u
        self.g = g
        self.category = category  # filtre par catégorie ; None = toutes

    async def interaction_check(self, i):
        return i.user.id == self.u.id

    async def render_to(self, interaction, *, edit: bool = True):
        all_cats = sorted(set(m["cat"] for m in ulogger2026.EVENT_META.values()))
        disabled = await ulogger2026.get_disabled_events(self.g.id)

        # Si aucune catégorie choisie : afficher select catégorie
        self.clear_items()
        items = [
            v2_title("🔍 Détail par évènement"),
            v2_subtitle("Active/désactive chaque type d'évènement individuellement"),
            v2_divider(),
        ]

        if self.category is None:
            # Étape 1 : choix de la catégorie
            opts = []
            cat_emojis = {
                "Modération": "🔨", "Sécurité": "🛡️", "Membres": "👥",
                "Messages": "💬", "Vocal": "🎤", "Serveur": "🏷️",
                "Tickets": "🎫", "Config": "⚙️",
            }
            for c in all_cats:
                count = sum(1 for m in ulogger2026.EVENT_META.values() if m["cat"] == c)
                opts.append(discord.SelectOption(
                    label=c, value=c, emoji=cat_emojis.get(c, "📋"),
                    description=f"{count} types d'évènements",
                ))
            sel = Select(placeholder="Choisis une catégorie…", options=opts[:25])
            sel.callback = self._cb_pick_cat
            items.append(v2_body("Étape 1 : choisis la catégorie à détailler."))
            items.append(discord.ui.ActionRow(sel))
        else:
            # Étape 2 : toggles des events de la catégorie
            ev_items = [(ev, meta) for ev, meta in ulogger2026.EVENT_META.items() if meta["cat"] == self.category]
            ev_items.sort(key=lambda x: x[1]["label"])

            # Construire le multi-select avec defaults selon disabled
            sel_opts = []
            for ev, meta in ev_items[:25]:
                value = ev.value
                is_enabled = value not in disabled
                sel_opts.append(discord.SelectOption(
                    label=meta["label"][:80],
                    value=value,
                    description=f"`{value}`"[:90],
                    emoji=meta["icon"],
                    default=is_enabled,
                ))
            sel = Select(
                placeholder=f"Évènements actifs dans « {self.category} »…",
                min_values=0, max_values=len(sel_opts),
                options=sel_opts,
            )
            sel.callback = self._cb_pick_events

            items.append(v2_body(
                f"**Catégorie :** {self.category}\n"
                f"Coche/décoche pour activer ou désactiver chaque type.\n"
                f"_Si la catégorie est désactivée globalement (`Catégories`), tout est skippé peu importe ces toggles._"
            ))
            items.append(v2_divider())
            items.append(discord.ui.ActionRow(sel))

            b_change_cat = Button(label="↩️ Changer de catégorie", style=discord.ButtonStyle.secondary)
            b_change_cat.callback = self._cb_change_cat
            items.append(discord.ui.ActionRow(b_change_cat))

        b_back = Button(label="◀️ Retour", style=discord.ButtonStyle.secondary, custom_id="logsv2_evts_back")
        b_back.callback = self._cb_back
        items.append(discord.ui.ActionRow(b_back))

        self.add_item(v2_container(*items, color=Palette.PRIMARY))

        await _afficher_panneau(self, interaction, edit)

    async def _cb_pick_cat(self, i):
        try:
            cat = i.data['values'][0]
            self.category = cat
            await self.render_to(i, edit=True)
        except Exception as ex:
            print(f"[LogsEventsPanelV2 _cb_pick_cat] {ex}")

    async def _cb_pick_events(self, i):
        try:
            chosen = set(i.data.get('values', []))
            disabled = await ulogger2026.get_disabled_events(self.g.id)

            # Tous les events de la catégorie courante
            cat_events = {
                ev.value for ev, meta in ulogger2026.EVENT_META.items()
                if meta["cat"] == self.category
            }
            # On retire de disabled tous ceux de cette catégorie, puis on ajoute ceux non cochés
            new_disabled = set(disabled) - cat_events
            for ev_value in cat_events:
                if ev_value not in chosen:
                    new_disabled.add(ev_value)

            await ulogger2026.set_disabled_events(self.g.id, new_disabled)
            await self.render_to(i, edit=True)
        except Exception as ex:
            print(f"[LogsEventsPanelV2 _cb_pick_events] {ex}")

    async def _cb_change_cat(self, i):
        self.category = None
        await self.render_to(i, edit=True)

    async def _cb_back(self, i):
        v = LogsPanelV2(self.u, self.g)
        await v.render_to(i, edit=True)


# ═══════════════════════════════════════════════════════════════════════════════
#  🛡️ Phase 26.3 : LogsExclusionsPanelV2 — rôles épargnés par event
# ═══════════════════════════════════════════════════════════════════════════════

class LogsExclusionsPanelV2(LayoutView):
    """Phase 26.3 — pour chaque event_type, choisir les rôles épargnés.

    Si un membre concerné (user ou modérateur) a l'un des rôles épargnés,
    le log n'est PAS envoyé. Utile pour ne pas pister les actions du staff.
    """

    def __init__(self, u, g, selected_event: str = None):
        super().__init__(timeout=600)
        self.u = u
        self.g = g
        self.selected_event = selected_event  # ex: 'msg.delete'

    async def interaction_check(self, i):
        return i.user.id == self.u.id

    async def render_to(self, interaction, *, edit: bool = True):
        exclusions = await ulogger2026.get_role_exclusions(self.g.id)

        self.clear_items()
        items = [
            v2_title("🛡️ Rôles épargnés des logs"),
            v2_subtitle("Choisis quels rôles ne doivent JAMAIS apparaître dans tel ou tel log"),
            v2_divider(),
        ]

        if not self.selected_event:
            # Étape 1 : choisir un event
            opts = []
            for ev, meta in list(ulogger2026.EVENT_META.items())[:25]:
                excl_count = len(exclusions.get(ev.value, []) or [])
                desc = f"{meta['cat']}"
                if excl_count:
                    desc += f" · {excl_count} rôle(s) épargné(s)"
                opts.append(discord.SelectOption(
                    label=f"{meta['label']}"[:80],
                    value=ev.value,
                    description=desc[:90],
                    emoji=meta["icon"],
                ))

            sel = Select(placeholder="Choisis un type d'évènement…", options=opts)
            sel.callback = self._cb_pick_event

            # Résumé : combien d'events ont des exclusions
            with_excl = sum(1 for v in exclusions.values() if v)
            items.append(v2_body(
                f"**Statut :** `{with_excl}` type(s) d'évènements ont des rôles épargnés.\n\n"
                f"_Cas d'usage : si tu mets le rôle Owner épargné sur `msg.delete`, "
                f"quand tu supprimes un message, ça n'apparaît pas dans les logs._"
            ))
            items.append(v2_divider())
            items.append(discord.ui.ActionRow(sel))
        else:
            # Étape 2 : RoleSelect pour cet event
            meta = ulogger2026.EVENT_META.get(_resolve_event_type(self.selected_event), {})
            current_role_ids = exclusions.get(self.selected_event, []) or []
            current_roles = [self.g.get_role(rid) for rid in current_role_ids if self.g.get_role(rid)]

            current_str = ", ".join(r.mention for r in current_roles) if current_roles else "_aucun_"

            items.append(v2_body(
                f"**Évènement :** {meta.get('icon', '📋')} {meta.get('label', self.selected_event)}\n"
                f"`{self.selected_event}`\n\n"
                f"**Rôles actuellement épargnés :** {current_str}"
            ))
            items.append(v2_divider())

            role_sel = discord.ui.RoleSelect(
                placeholder="Choisis les rôles épargnés (multi)…",
                min_values=0,
                max_values=10,
                custom_id="logsv2_excl_roles",
            )
            role_sel.callback = self._cb_pick_roles
            items.append(discord.ui.ActionRow(role_sel))

            b_change = Button(label="↩️ Autre évènement", style=discord.ButtonStyle.secondary)
            b_change.callback = self._cb_change_event
            items.append(discord.ui.ActionRow(b_change))

        b_back = Button(label="◀️ Retour", style=discord.ButtonStyle.secondary, custom_id="logsv2_excl_back")
        b_back.callback = self._cb_back
        items.append(discord.ui.ActionRow(b_back))

        self.add_item(v2_container(*items, color=Palette.PRIMARY))

        await _afficher_panneau(self, interaction, edit)

    async def _cb_pick_event(self, i):
        try:
            ev_value = i.data['values'][0]
            self.selected_event = ev_value
            await self.render_to(i, edit=True)
        except Exception as ex:
            print(f"[LogsExclusionsPanelV2 _cb_pick_event] {ex}")

    async def _cb_pick_roles(self, i):
        try:
            role_ids = [int(rid) for rid in i.data.get('values', [])]
            exclusions = await ulogger2026.get_role_exclusions(self.g.id)
            exclusions[self.selected_event] = role_ids
            await ulogger2026.set_role_exclusions(self.g.id, exclusions)
            await self.render_to(i, edit=True)
        except Exception as ex:
            print(f"[LogsExclusionsPanelV2 _cb_pick_roles] {ex}")

    async def _cb_change_event(self, i):
        self.selected_event = None
        await self.render_to(i, edit=True)

    async def _cb_back(self, i):
        v = LogsPanelV2(self.u, self.g)
        await v.render_to(i, edit=True)


def _resolve_event_type(value: str):
    """Retourne l'EventType pour une valeur 'msg.delete' etc."""
    for ev in ulogger2026.EventType:
        if ev.value == value:
            return ev
    return None


# ═══════════════════════════════════════════════════════════════════════════════
#                           🛡️ PROTECTION PANEL (REFAIT PROPREMENT)
# ═══════════════════════════════════════════════════════════════════════════════


class ProtPanelV2(LayoutView):
    """Panneau Protection du Serveur en V2."""

    def __init__(self, u, g):
        super().__init__(timeout=600)
        self.u = u
        self.g = g

    async def interaction_check(self, i):
        return i.user.id == self.u.id

    async def render_to(self, interaction: discord.Interaction, *, edit: bool = True):
        c = await cfg(self.g.id)

        enabled_count = 0
        lines_out = []
        for key, emoji, name in PROTS:
            is_on = bool(c.get(key))
            if is_on:
                enabled_count += 1
            # Phase 5.3 : radio-style 🔘 / ⚪ au lieu de feu 🟢 / 🔴
            dot = "🔘" if is_on else "⚪"
            lines_out.append(f"{dot} {emoji} **{name}**")

        total = len(PROTS)
        pct = round(enabled_count / total * 100) if total > 0 else 0

        sel = Select(
            placeholder="🛡️ Choisir une protection à configurer…",
            options=[discord.SelectOption(label=nm, value=k, emoji=em) for k, em, nm in PROTS],
            custom_id="ppv2_sel",
        )
        sel.callback = self._cb_sel
        b_back = Button(label="◀️ Retour", style=discord.ButtonStyle.secondary, custom_id="ppv2_back")
        b_back.callback = self._cb_back

        self.clear_items()
        items: list = []
        if self.g.icon:
            items.append(v2_section(
                v2_title("🛡️ Protection"),
                v2_subtitle(f"`{enabled_count}/{total}` filtres actifs · `{pct}%`"),
                accessory=v2_thumb(self.g.icon.url),
            ))
        else:
            items.append(v2_title("🛡️ Protection"))
            items.append(v2_subtitle(f"`{enabled_count}/{total}` filtres actifs · `{pct}%`"))

        items.append(v2_divider())
        items.append(v2_body("\n".join(lines_out)))
        items.append(v2_divider())
        items.append(discord.ui.ActionRow(sel))
        items.append(discord.ui.ActionRow(b_back))

        self.add_item(v2_container(*items, color=Palette.INFO))

        await _afficher_panneau(self, interaction, edit)

    async def _cb_sel(self, interaction):
        val = interaction.data['values'][0]
        prot = next(p for p in PROTS if p[0] == val)
        v = ProtDetailV2(self.u, self.g, prot)
        await v.render_to(interaction, edit=True)

    async def _cb_back(self, i):
        # Refonte 2026-08 : retour direct à la racine /configure (MainPanelV2).
        v = MainPanelV2(self.u, self.g)
        await v.render_to(i, edit=True)



class ProtDetailV2(LayoutView):
    """Detail d'une protection en V2 — toutes les sub-panels accessibles."""

    def __init__(self, u, g, prot):
        super().__init__(timeout=600)
        self.u = u
        self.g = g
        self.prot = prot
        self.key = prot[0]

    async def interaction_check(self, i):
        return i.user.id == self.u.id

    async def render_to(self, interaction: discord.Interaction, *, edit: bool = True):
        c = await cfg(self.g.id)
        on = bool(c.get(self.key))

        # Helper sanction (action + durée)
        def _sanction_line(protection_key):
            try:
                ak = get_prot_action_key(protection_key)
                dk = get_prot_duration_key(protection_key)
                act = c.get(ak, get_prot_default_action(protection_key))
                dur = c.get(dk, get_prot_default_duration(protection_key))
                act_emoji = {'delete': '🗑️', 'mute': '🔇', 'kick': '👢', 'ban': '🔨'}.get(act, '⚡')
                line = f"⚡ **Sanction** · {act_emoji} `{act.upper()}`"
                if act == 'mute':
                    line += f"  ·  ⏱️ Durée mute · `{dur}` min"
                return line
            except Exception:
                return None

        # Items de base : titre + status (Phase 11 : radio dot)
        items: list = [
            v2_title(f"{self.prot[1]} {self.prot[2]}"),
            v2_subtitle(f"{'🔘 Activé' if on else '⚪ Désactivé'}"),
            v2_divider(),
        ]

        # Configs spécifiques par protection
        if self.key == "anti_link":
            wl = c.get('link_whitelist', [])
            chs = c.get('link_allowed_channels', [])
            wl_txt = ", ".join(f"`{d}`" for d in wl[:15]) if wl else "_Aucun domaine_"
            ch_txt = ", ".join(f"<#{x}>" for x in chs[:10]) if chs else "_Aucun salon_"
            items.append(v2_body(f"🌐 **Whitelist domaines** · {wl_txt}\n📍 **Salons autorisés** · {ch_txt}"))
            sl = _sanction_line(self.key)
            if sl: items.append(v2_body(sl))

        elif self.key == "anti_image":
            allowed = c.get('image_allowed', [])
            fmts = ['png', 'jpg', 'jpeg', 'gif', 'webp', 'tenor', 'giphy']
            fmt_txt = "  ".join(f"{'✅' if f in allowed else '❌'} `{f}`" for f in fmts)
            items.append(v2_body(f"📁 **Formats autorisés**\n{fmt_txt}"))
            sl = _sanction_line(self.key)
            if sl: items.append(v2_body(sl))

        elif self.key == "anti_badwords":
            words = c.get('badwords_list', [])
            if words:
                if len(words) <= 30:
                    words_txt = ", ".join(f"`{w}`" for w in words)
                else:
                    words_txt = ", ".join(f"`{w}`" for w in words[:30]) + f"\n_… + {len(words) - 30} autres_"
                items.append(v2_body(f"🚫 **Mots interdits** ({len(words)})\n{words_txt[:1000]}"))
            else:
                items.append(v2_body("🚫 **Mots interdits** · _Aucun mot configuré_"))
            sl = _sanction_line(self.key)
            if sl: items.append(v2_body(sl))

        elif self.key == "anti_spam":
            items.append(v2_body(
                f"📊 **Max messages** · `{c.get('spam_max', 5)}`  ·  "
                f"⏱️ **Intervalle** · `{c.get('spam_interval', 5)}` sec"
            ))
            sl = _sanction_line(self.key)
            if sl: items.append(v2_body(sl))

        elif self.key == "anti_caps":
            items.append(v2_body(f"📊 **Pourcentage max** · `{c.get('caps_percent', 70)}%`"))
            sl = _sanction_line(self.key)
            if sl: items.append(v2_body(sl))

        elif self.key == "anti_mass_mention":
            items.append(v2_body(f"📊 **Max mentions** · `{c.get('mention_limit', 5)}` par message"))
            sl = _sanction_line(self.key)
            if sl: items.append(v2_body(sl))
            items.append(v2_body("ℹ️ Détecte @everyone, @here, et les mentions massives de membres/rôles"))

        elif self.key == "anti_newaccount":
            items.append(v2_body(f"📅 **Jours minimum** · `{c.get('newaccount_days', 7)}`"))

        elif self.key == "anti_invite":
            sl = _sanction_line(self.key)
            if sl: items.append(v2_body(sl))

        elif self.key == "anti_compromised":
            # Ce bloc décrivait `check_compromised_behavior`, une fonction morte, et
            # affichait une ligne « Sanction » construite sur des clés jamais appliquées.
            # Il décrit maintenant ce que le détecteur fait RÉELLEMENT.
            _cad_ch = self.g.get_channel(
                c.get('compromised_alerts_channel', 0)
                or c.get('log_anti_compromised', 0)
                or c.get('mod_log_channel', 0)
            )
            items.append(v2_body(
                "🔐 **Détection des comptes compromis/hackés**\n\n"
                "Chaque message reçoit un score de compromission : lien de phishing connu, "
                "invitation Discord doublée d'une mention massive, même message répété dans "
                "plusieurs salons, compte récent qui poste soudainement un lien…"
            ))
            items.append(v2_body(
                f"🎯 **Seuil** · `{c.get('compromised_alert_threshold', 60)}`/100  ·  "
                f"⏱️ **Anti-rafale** · `{c.get('compromised_alert_cooldown', 300)}` s\n"
                f"📬 **Dossier envoyé dans** · "
                f"{_cad_ch.mention if _cad_ch else '⚠️ _aucun salon — utilise « 📜 Log »_'}"
            ))
            items.append(v2_body(
                "⚡ **Sanction** · aucune sanction automatique. Le compte est **gelé** et un "
                "dossier avec les boutons Mute 24 h / Kick / Ban est posté pour le staff "
                "(kick et ban réservés au fondateur)."
            ))

        elif self.key == "anti_qrcode":
            items.append(v2_body(
                "📱 **Protection contre les scams par QR Code**\n\n"
                "Détecte les tentatives de vol de compte via QR code Discord :\n"
                "• Messages demandant de scanner un QR code\n"
                "• Faux QR codes de 'cadeaux'\n"
                "• Tentatives de vol de token"
            ))
            sl = _sanction_line(self.key)
            if sl: items.append(v2_body(sl))

        elif self.key == "anti_phishing":
            items.append(v2_body(
                "🎣 **Protection Anti-Phishing Avancée 2026**\n\nProtège contre :\n"
                "• Faux sites Discord/Steam/Nitro/Roblox\n"
                "• Typosquatting (dlscord, steampowored…)\n"
                "• Liens masqués [texte](url phishing)\n"
                "• Scam 'Verify age group' / Safeguard bot\n"
                "• IP grabbers et raccourcisseurs suspects\n"
                "• TLD dangereux (.ru, .tk, .xyz…)\n"
                "• URLs dans les embeds de messages"
            ))
            sl = _sanction_line(self.key)
            if sl: items.append(v2_body(sl))
            items.append(v2_body(f"📊 **Base de données** · `{len(PHISHING_DOMAINS)}` domaines blacklistés"))

        elif self.key == "anti_scam":
            items.append(v2_body(
                "🚨 **Protection Anti-Scam Avancée 2026**\n\nDétecte :\n"
                "• Free Nitro / Steam Gift scams\n"
                "• Crypto giveaway / Airdrop scams\n"
                "• Scam vérification âge Discord\n"
                "• Token grabbers / ClickFix\n"
                "• Faux jeux à tester (playtest)\n"
                "• Investment / Job / Romance scams\n"
                "• Urgence artificielle"
            ))
            sl = _sanction_line(self.key)
            if sl: items.append(v2_body(sl))
            items.append(v2_body(f"📊 **Base de données** · `{len(SCAM_KEYWORDS)}` mots-clés détectés"))

        elif self.key == "anti_alt":
            alt_cfg = c.get('alt_config', {})
            action = c.get('alt_action', 'kick')
            auto = alt_cfg.get('auto_action', False)
            min_conf = alt_cfg.get('min_confidence', 70)
            try:
                alts = await get_alt_accounts(self.g.id)
                suspected = len([a for a in alts if a[5] == 'suspected'])
                confirmed = len([a for a in alts if a[5] == 'confirmed'])
            except Exception:
                suspected = confirmed = 0
            items.append(v2_body(
                "👥 **Détection des Comptes Secondaires**\n\n"
                "Détecte automatiquement les comptes secondaires (alts) :\n"
                "• Avatar identique à un membre existant/banni\n"
                "• Nom d'utilisateur similaire\n"
                "• Compte créé juste après un ban\n"
                "• Comportement suspect"
            ))
            items.append(v2_body(
                f"⚡ **Action** · `{action.upper()}`  ·  "
                f"🤖 **Action auto** · {'✅' if auto else '❌'}  ·  "
                f"📊 **Confiance min.** · `{min_conf}%`\n"
                f"🔍 **Détections** · ⚠️ `{suspected}` suspects · ✅ `{confirmed}` confirmés"
            ))

        # Salon de log (commun à toutes)
        log_ch = self.g.get_channel(c.get(f'log_{self.key}', 0))
        items.append(v2_divider())
        items.append(v2_body(f"📜 **Salon de log** · {log_ch.mention if log_ch else '⚪ _non configuré_'}"))

        # Boutons
        self.clear_items()
        b_toggle = Button(
            label=("⏸️ Désactiver" if on else "▶️ Activer"),
            style=(discord.ButtonStyle.danger if on else discord.ButtonStyle.success),
            custom_id="pdv2_toggle",
        )
        b_toggle.callback = self._cb_toggle
        b_config = Button(label="⚙️ Configurer", style=discord.ButtonStyle.primary, custom_id="pdv2_config")
        b_config.callback = self._cb_config
        b_sanction = Button(label="⚡ Sanction", style=discord.ButtonStyle.secondary, custom_id="pdv2_sanction")
        b_sanction.callback = self._cb_sanction
        b_log = Button(label="📜 Définir Log", style=discord.ButtonStyle.secondary, custom_id="pdv2_log")
        b_log.callback = self._cb_log
        b_back = Button(label="◀️ Retour", style=discord.ButtonStyle.secondary, custom_id="pdv2_back")
        b_back.callback = self._cb_back

        items.append(v2_divider())
        items.append(discord.ui.ActionRow(b_toggle, b_config, b_sanction, b_log, b_back))

        color = Palette.SUCCESS if on else Palette.DANGER
        self.add_item(v2_container(*items, color=color))

        await _afficher_panneau(self, interaction, edit)

    async def _cb_toggle(self, i):
        c = await cfg(self.g.id)
        new_val = 0 if c.get(self.key) else 1
        await db_set(self.g.id, self.key, new_val)
        await ProtDetailV2(self.u, self.g, self.prot).render_to(i, edit=True)

    async def _cb_config(self, i):
        # Sub-configs V2 dédiés
        if self.key == "anti_image":
            v = ImageConfigPanelV2(self.u, self.g)
            return await v.render_to(i, edit=True)
        if self.key == "anti_badwords":
            v = BadwordsConfigPanelV2(self.u, self.g)
            return await v.render_to(i, edit=True)
        if self.key == "anti_link":
            v = LinkConfigPanelV2(self.u, self.g)
            return await v.render_to(i, edit=True)
        # Modals directs
        if self.key in ["anti_spam", "anti_caps", "anti_newaccount", "anti_mass_mention"]:
            return await i.response.send_modal(NumberConfigModal(self.g, self.u, self.key))
        # Sub-configs V2 dédiés (suite)
        if self.key == "anti_alt":
            v = AltConfigPanelV2(self.u, self.g)
            return await v.render_to(i, edit=True)
        # Default : ActionConfigPanelV2 pour toutes les autres protections
        v = ActionConfigPanelV2(self.u, self.g, self.key)
        await v.render_to(i, edit=True)

    async def _cb_sanction(self, i):
        # Trois protections ne se règlent PAS par ActionConfigPanelV2 : il écrirait une clé
        # que le chemin d'exécution ne relit jamais, donc un bouton sans effet (UI.md §3).
        if self.key == "anti_badwords":
            # La sanction réelle est badwords_sanction_action / badwords_sanction_duration,
            # lues par _badword_strike. ActionConfigPanelV2 écrirait `badwords_action`,
            # clé qui n'existe nulle part ailleurs dans le fichier.
            return await _BadwordsSanctionActionView(self.u, self.g).render_to(i, edit=True)
        if self.key == "anti_compromised":
            # Cette protection ne sanctionne pas automatiquement : le panneau doit le dire
            # plutôt que de proposer un réglage qui ne s'appliquerait jamais.
            return await i.response.send_message(
                "ℹ️ Cette protection ne sanctionne **pas** automatiquement : elle gèle le "
                "compte et ouvre un dossier que le staff tranche à la main.",
                ephemeral=True,
            )
        v = ActionConfigPanelV2(self.u, self.g, self.key)
        await v.render_to(i, edit=True)

    async def _cb_log(self, i):
        # UI.md §2 : ChannelSelect natif via V2GenericChannelPicker. L'ancien
        # LogSelectView paginait les salons 23 par 23 (limite des 25 options d'un
        # Select classique) et renvoyait un Embed depuis un panneau V2.
        try:
            v = V2GenericChannelPicker(
                self.u, self.g,
                config_key=f'log_{self.key}',
                return_panel_factory=lambda: ProtDetailV2(self.u, self.g, self.prot),
                title="📜 Salon de log",
                description=f"Où envoyer les alertes de **{self.prot[2]}**.",
                color=0x9B59B6,
            )
            await v.render_to(i, edit=True)
        except Exception as ex:
            print(f"[ProtDetailV2 _cb_log] {ex}")
            try:
                if not i.response.is_done():
                    await i.response.send_message(f"❌ Erreur : {ex}", ephemeral=True)
                else:
                    await i.followup.send(f"❌ Erreur : {ex}", ephemeral=True)
            except Exception:
                pass

    async def _cb_back(self, i):
        v = ProtPanelV2(self.u, self.g)
        await v.render_to(i, edit=True)




