class AltConfigPanelV2(LayoutView):
    """Configuration Anti-MultiCompte (alts) en V2."""

    def __init__(self, u, g):
        super().__init__(timeout=600)
        self.u = u
        self.g = g

    async def interaction_check(self, i):
        return i.user.id == self.u.id

    async def render_to(self, interaction: discord.Interaction, *, edit: bool = True):
        c = await cfg(self.g.id)
        alt_cfg = c.get('alt_config', {})

        enabled = bool(c.get('anti_alt', 0))
        action = c.get('alt_action', 'kick')
        action_emoji = {'kick': '👢', 'ban': '🔨', 'mute': '🔇'}.get(action, '⚡')
        auto = alt_cfg.get('auto_action', False)
        min_conf = alt_cfg.get('min_confidence', 70)

        try:
            alts = await get_alt_accounts(self.g.id)
            suspected = len([a for a in alts if a[5] == 'suspected'])
            confirmed = len([a for a in alts if a[5] == 'confirmed'])
            actioned = len([a for a in alts if a[7]])
        except Exception:
            suspected = confirmed = actioned = 0

        # Phase 11 : radio dots + compact
        self.clear_items()
        if enabled:
            b_toggle = Button(label="⚪ Désactiver", style=discord.ButtonStyle.danger, custom_id="alcv2_toggle")
        else:
            b_toggle = Button(label="🔘 Activer", style=discord.ButtonStyle.success, custom_id="alcv2_toggle")
        b_toggle.callback = self._cb_toggle
        b_action = Button(label=f"⚡ Action · {action.upper()}", style=discord.ButtonStyle.primary, custom_id="alcv2_action")
        b_action.callback = self._cb_cycle_action
        b_auto = Button(
            label=("🔘 Auto" if auto else "⚪ Auto"),
            style=(discord.ButtonStyle.success if auto else discord.ButtonStyle.secondary),
            custom_id="alcv2_auto",
        )
        b_auto.callback = self._cb_toggle_auto
        b_conf = Button(label=f"📊 Confiance · {min_conf}%", style=discord.ButtonStyle.primary, custom_id="alcv2_conf")
        b_conf.callback = self._cb_conf
        b_scan = Button(label="🔍 Scanner", style=discord.ButtonStyle.success, custom_id="alcv2_scan")
        b_scan.callback = self._cb_scan
        b_view = Button(label="📋 Détections", style=discord.ButtonStyle.secondary, disabled=(not (suspected or confirmed)), custom_id="alcv2_view")
        b_view.callback = self._cb_view
        b_back = Button(label="◀️ Retour", style=discord.ButtonStyle.secondary, custom_id="alcv2_back")
        b_back.callback = self._cb_back

        items: list = [
            v2_title("👥 Anti-MultiCompte"),
            v2_subtitle(f"{'🔘 actif' if enabled else '⚪ désactivé'} · `{suspected}` suspect(s)"),
            v2_divider(),
        ]

        if enabled:
            items.append(v2_body(
                f"⚡ **Action** · `{action.upper()}`\n"
                f"{'🔘' if auto else '⚪'} **Action auto**\n"
                f"📊 **Confiance minimum** · `{min_conf}%`"
            ))
            items.append(v2_divider())
            items.append(v2_body(
                f"⚠️ Suspects · `{suspected}`  ·  "
                f"✅ Confirmés · `{confirmed}`  ·  "
                f"⚡ Sanctionnés · `{actioned}`"
            ))
            items.append(v2_divider())

        items.append(discord.ui.ActionRow(b_toggle, b_action, b_auto, b_conf))
        items.append(discord.ui.ActionRow(b_scan, b_view, b_back))

        self.add_item(v2_container(*items, color=Palette.ACCENT))

        await _afficher_panneau(self, interaction, edit)

    async def _cb_toggle(self, i):
        c = await cfg(self.g.id)
        await db_set(self.g.id, 'anti_alt', 0 if c.get('anti_alt') else 1)
        await AltConfigPanelV2(self.u, self.g).render_to(i, edit=True)

    async def _cb_cycle_action(self, i):
        c = await cfg(self.g.id)
        actions = ['kick', 'ban', 'mute']
        current = c.get('alt_action', 'kick')
        try:
            next_idx = (actions.index(current) + 1) % len(actions)
        except ValueError:
            next_idx = 0
        await db_set(self.g.id, 'alt_action', actions[next_idx])
        await AltConfigPanelV2(self.u, self.g).render_to(i, edit=True)

    async def _cb_toggle_auto(self, i):
        c = await cfg(self.g.id)
        alt_cfg = c.get('alt_config', {})
        alt_cfg['auto_action'] = not alt_cfg.get('auto_action', False)
        await db_set(self.g.id, 'alt_config', alt_cfg)
        await AltConfigPanelV2(self.u, self.g).render_to(i, edit=True)

    async def _cb_conf(self, i):
        await i.response.send_modal(AltConfidenceModal(self.g, self.u))

    async def _cb_scan(self, i):
        await i.response.send_message("🔍 **Scan des comptes secondaires en cours…**", ephemeral=True)
        try:
            detected = await scan_all_members_for_alts(self.g)
            if detected:
                v = AltScanResultsPanelV2(self.u, self.g, detected)
                await v.render_after_defer(i)
            else:
                await i.edit_original_response(
                    content="✅ **Aucun compte secondaire détecté !**\n\nTous les membres semblent être des comptes uniques.",
                    embed=None,
                    view=None,
                )
        except Exception as ex:
            print(f"[ALT SCAN V2] {ex}")
            try:
                await i.edit_original_response(content=f"❌ Erreur: {ex}")
            except Exception:
                pass

    async def _cb_view(self, i):
        alts = await get_alt_accounts(self.g.id)
        if not alts:
            return await i.response.send_message("📋 Aucun compte secondaire détecté.", ephemeral=True)
        v = AltDetectionsPanelV2(self.u, self.g, alts)
        await v.render_to(i, edit=True)

    async def _cb_back(self, i):
        prot = next(p for p in PROTS if p[0] == "anti_alt")
        v = ProtDetailV2(self.u, self.g, prot)
        await v.render_to(i, edit=True)



class AltConfidenceModal(Modal, title="📊 Confiance minimum"):
    value = TextInput(
        label="Pourcentage de confiance (40-100)",
        placeholder="70",
        default="70",
        max_length=3
    )
    
    def __init__(self, g, u):
        super().__init__()
        self.g = g
        self.u = u
    
    async def on_submit(self, i):
        try:
            val = int(self.value.value)
            val = max(40, min(100, val))
            
            c = await cfg(self.g.id)
            alt_cfg = c.get('alt_config', {})
            alt_cfg['min_confidence'] = val
            await db_set(self.g.id, 'alt_config', alt_cfg)
            
            # Phase 3.6 : retour V2
            v = AltConfigPanelV2(self.u, self.g)
            await v.render_to(i, edit=True)
            try:
                await i.followup.send(f"✅ Confiance minimum définie à **{val}%**", ephemeral=True)
            except Exception:
                pass
        except Exception:
            try:
                await i.response.send_message("❌ Valeur invalide", ephemeral=True)
            except discord.InteractionResponded:
                pass

class AltScanResultsPanelV2(LayoutView):
    """Resultats d'un scan d'alts en V2."""

    def __init__(self, u, g, detected):
        super().__init__(timeout=300)
        self.u = u
        self.g = g
        self.detected = detected
        self.page = 0
        self.per_page = 5

    async def interaction_check(self, i):
        return i.user.id == self.u.id

    def _build(self):
        total = len(self.detected)
        high_conf = len([d for d in self.detected if d['confidence'] >= 70])
        very_high = len([d for d in self.detected if d['confidence'] >= 80])
        max_page = max(0, (total - 1) // self.per_page) if total else 0
        start = self.page * self.per_page
        end = start + self.per_page
        page_items = self.detected[start:end]

        item_blocks = []
        for item in page_items:
            member = item['member']
            confidence = item['confidence']
            main_id = item['main_id']
            reasons = item['reasons']
            conf_emoji = "🔴" if confidence >= 80 else ("🟠" if confidence >= 60 else "🟡")
            main_member = self.g.get_member(main_id)
            main_txt = f"{main_member.name}" if main_member else f"ID `{main_id}` (parti)"
            block = (
                f"**👤 {member.display_name}** (`{member.id}`)\n"
                f"  ┣ Confiance · {conf_emoji} `{confidence}%`\n"
                f"  ┣ Compte principal · {main_txt}\n"
                f"  ┗ Raisons · {', '.join(reasons[:2])}"
            )
            item_blocks.append(block)
        list_block = "\n\n".join(item_blocks) if item_blocks else "_Aucun résultat sur cette page_"

        self.clear_items()
        b_prev = Button(label="◀️", style=discord.ButtonStyle.secondary, disabled=(self.page <= 0), custom_id="asrv2_prev")
        b_prev.callback = self._cb_prev
        b_page = Button(label=f"Page {self.page + 1}/{max_page + 1}", style=discord.ButtonStyle.secondary, disabled=True, custom_id="asrv2_page")
        b_next = Button(label="▶️", style=discord.ButtonStyle.secondary, disabled=(self.page >= max_page), custom_id="asrv2_next")
        b_next.callback = self._cb_next
        b_kick70 = Button(label="👢 Kick tous (>=70%)", style=discord.ButtonStyle.danger, disabled=(high_conf == 0), custom_id="asrv2_kick70")
        b_kick70.callback = self._cb_kick70
        b_ban80 = Button(label="🔨 Ban tous (>=80%)", style=discord.ButtonStyle.danger, disabled=(very_high == 0), custom_id="asrv2_ban80")
        b_ban80.callback = self._cb_ban80
        b_back = Button(label="◀️ Retour", style=discord.ButtonStyle.secondary, custom_id="asrv2_back")
        b_back.callback = self._cb_back

        items: list = [
            v2_title("🔍 Résultats du Scan"),
            v2_subtitle(f"`{total}` alts potentiels · `{high_conf}` haute confiance (>=70%) · `{very_high}` très haute (>=80%)"),
            v2_divider(),
            v2_body(list_block),
            v2_divider(),
            discord.ui.ActionRow(b_prev, b_page, b_next),
            discord.ui.ActionRow(b_kick70, b_ban80, b_back),
        ]

        self.add_item(v2_container(*items, color=Palette.DANGER))

    async def render_to(self, interaction, *, edit=True):
        self._build()
        await _afficher_panneau(self, interaction, edit)

    async def render_after_defer(self, interaction):
        self._build()
        await interaction.edit_original_response(view=self, embed=None, attachments=[], content=None)

    async def _cb_prev(self, i):
        if self.page > 0:
            self.page -= 1
        await self.render_to(i, edit=True)

    async def _cb_next(self, i):
        max_page = max(0, (len(self.detected) - 1) // self.per_page) if self.detected else 0
        if self.page < max_page:
            self.page += 1
        await self.render_to(i, edit=True)

    async def _cb_kick70(self, i):
        high_conf = [d for d in self.detected if d['confidence'] >= 70]
        if not high_conf:
            return await i.response.send_message("✅ Aucun compte avec >=70% de confiance", ephemeral=True)
        v = ConfirmAltActionView(self.u, self.g, high_conf, 'kick')
        await i.response.send_message(
            embed=discord.Embed(
                title="⚠️ Confirmation",
                description=f"Voulez-vous **KICK** {len(high_conf)} compte(s) secondaire(s) avec >=70% de confiance ?",
                color=0xE74C3C,
            ),
            view=v,
            ephemeral=True,
        )

    async def _cb_ban80(self, i):
        very_high = [d for d in self.detected if d['confidence'] >= 80]
        if not very_high:
            return await i.response.send_message("✅ Aucun compte avec >=80% de confiance", ephemeral=True)
        v = ConfirmAltActionView(self.u, self.g, very_high, 'ban')
        await i.response.send_message(
            embed=discord.Embed(
                title="⚠️ Confirmation",
                description=f"Voulez-vous **BAN** {len(very_high)} compte(s) secondaire(s) avec >=80% de confiance ?",
                color=0xE74C3C,
            ),
            view=v,
            ephemeral=True,
        )

    async def _cb_back(self, i):
        v = AltConfigPanelV2(self.u, self.g)
        await v.render_to(i, edit=True)



class ConfirmAltActionView(View):
    def __init__(self, u, g, targets, action):
        super().__init__(timeout=60)
        self.u = u
        self.g = g
        self.targets = targets
        self.action = action
    
    async def interaction_check(self, i) -> bool:
        # Garde : seul l'ouvrant peut confirmer (anti-clic d'un tiers sur ce message).
        try:
            if i.user.id != self.u.id:
                await i.response.send_message("⛔ Ce panneau ne t'est pas destiné.", ephemeral=True)
                return False
        except Exception:
            return False
        return True

    @discord.ui.button(label="✅ Confirmer", style=discord.ButtonStyle.danger, row=0)
    async def confirm(self, i, b):
        await i.response.edit_message(content="⏳ Exécution en cours...", embed=None, view=None)

        success = 0
        failed = 0

        for item in self.targets:
            member = item['member']
            try:
                # RÈGLE FONDATEUR-ONLY (2026-06-13) : on ne kick/ban JAMAIS en masse →
                # on ISOLE (réversible ; les alts sont souvent des faux positifs). Le
                # fondateur reste seul à pouvoir bannir, au cas par cas.
                if self.action in ('kick', 'ban'):
                    await isolate_member(member, f"Compte secondaire (confiance: {item['confidence']}%)")
                await update_alt_status(self.g.id, member.id, 'actioned', 'isolate')
                success += 1
            except Exception:
                failed += 1

        await i.edit_original_response(
            content=f"🔒 **{success}** compte(s) isolé(s) (quarantaine)\n❌ **{failed}** échec(s)\n"
                    f"_Le bannissement éventuel reste au fondateur._"
        )
    
    @discord.ui.button(label="❌ Annuler", style=discord.ButtonStyle.secondary, row=0)
    async def cancel(self, i, b):
        await i.response.edit_message(content="❌ Action annulée", embed=None, view=None)

class AltDetectionsPanelV2(LayoutView):
    """Historique des detections d'alts en V2."""

    def __init__(self, u, g, alts):
        super().__init__(timeout=300)
        self.u = u
        self.g = g
        self.alts = alts
        self.page = 0
        self.per_page = 5

    async def interaction_check(self, i):
        return i.user.id == self.u.id

    async def render_to(self, interaction, *, edit=True):
        total = len(self.alts)
        max_page = max(0, (total - 1) // self.per_page) if total else 0
        start = self.page * self.per_page
        end = start + self.per_page
        page_items = self.alts[start:end]

        item_blocks = []
        for alt in page_items:
            _, main_id, alt_id, confidence, reasons_json, status, detected_at, action_taken = alt
            try:
                reasons = json.loads(reasons_json) if reasons_json else []
            except Exception:
                reasons = []
            status_emoji = {'suspected': '⚠️', 'confirmed': '✅', 'dismissed': '❌', 'actioned': '⚡'}.get(status, '❓')
            conf_emoji = "🔴" if confidence >= 80 else ("🟠" if confidence >= 60 else "🟡")
            alt_member = self.g.get_member(alt_id)
            main_member = self.g.get_member(main_id)
            alt_txt = f"{alt_member.name}" if alt_member else f"ID `{alt_id}` (parti)"
            main_txt = f"{main_member.name}" if main_member else f"ID `{main_id}`"
            block = (
                f"**👤 {alt_txt}**\n"
                f"  ┣ Principal · {main_txt}\n"
                f"  ┣ Confiance · {conf_emoji} `{confidence}%`\n"
                f"  ┣ Status · {status_emoji} `{status}`\n"
                f"  ┗ Raisons · {', '.join(reasons[:2]) if reasons else '_N/A_'}"
            )
            if action_taken:
                block += f"\n  ⚡ **Action** · `{action_taken.upper()}`"
            item_blocks.append(block)
        list_block = "\n\n".join(item_blocks) if item_blocks else "_Aucune détection enregistrée_"

        self.clear_items()
        b_prev = Button(label="◀️", style=discord.ButtonStyle.secondary, disabled=(self.page <= 0), custom_id="adpv2_prev")
        b_prev.callback = self._cb_prev
        b_page = Button(label=f"Page {self.page + 1}/{max_page + 1}", style=discord.ButtonStyle.secondary, disabled=True, custom_id="adpv2_page")
        b_next = Button(label="▶️", style=discord.ButtonStyle.secondary, disabled=(self.page >= max_page), custom_id="adpv2_next")
        b_next.callback = self._cb_next
        b_clear = Button(label="🗑️ Effacer historique", style=discord.ButtonStyle.danger, disabled=(not self.alts), custom_id="adpv2_clear")
        b_clear.callback = self._cb_clear
        b_back = Button(label="◀️ Retour", style=discord.ButtonStyle.secondary, custom_id="adpv2_back")
        b_back.callback = self._cb_back

        items: list = [
            v2_title("📋 Détections de Comptes Secondaires"),
            v2_subtitle(f"`{total}` détection(s) enregistrée(s)"),
            v2_divider(),
            v2_body(list_block),
            v2_divider(),
            discord.ui.ActionRow(b_prev, b_page, b_next),
            discord.ui.ActionRow(b_clear, b_back),
        ]

        self.add_item(v2_container(*items, color=Palette.ACCENT))

        await _afficher_panneau(self, interaction, edit)

    async def _cb_prev(self, i):
        if self.page > 0:
            self.page -= 1
        await self.render_to(i, edit=True)

    async def _cb_next(self, i):
        max_page = max(0, (len(self.alts) - 1) // self.per_page) if self.alts else 0
        if self.page < max_page:
            self.page += 1
        await self.render_to(i, edit=True)

    async def _cb_clear(self, i):
        try:
            async with get_db() as db:
                await db.execute('DELETE FROM alt_accounts WHERE guild_id = ?', (self.g.id,))
                await db.commit()
            v = AltConfigPanelV2(self.u, self.g)
            await v.render_to(i, edit=True)
        except Exception as ex:
            try:
                if not i.response.is_done():
                    await i.response.send_message(f"❌ Erreur: {ex}", ephemeral=True)
                else:
                    await i.followup.send(f"❌ Erreur: {ex}", ephemeral=True)
            except Exception:
                pass

    async def _cb_back(self, i):
        v = AltConfigPanelV2(self.u, self.g)
        await v.render_to(i, edit=True)



class SuspectScanPanelV2(LayoutView):
    """Resultats du scan suspects en V2 (delegue le scan a SuspectScanPanel V1)."""

    def __init__(self, u, g, suspects=None, bots=None):
        super().__init__(timeout=300)
        self.u = u
        self.g = g
        self.suspects = suspects if suspects is not None else []
        self.bots = bots if bots is not None else []
        self.page = 0
        self.per_page = 8

    async def interaction_check(self, i):
        return i.user.id == self.u.id

    async def scan_members(self):
        helper = SuspectScanPanel(self.u, self.g)
        await helper.scan_members()
        self.suspects = helper.suspects
        self.bots = helper.bots

    def _build(self):
        critical = len([s for s in self.suspects if s['severity'] == 'critical'])
        high = len([s for s in self.suspects if s['severity'] == 'high'])
        medium = len([s for s in self.suspects if s['severity'] == 'medium'])
        max_page = max(0, (len(self.suspects) - 1) // self.per_page) if self.suspects else 0

        start = self.page * self.per_page
        end = start + self.per_page
        page_suspects = self.suspects[start:end]

        sus_lines = []
        for s in page_suspects:
            member = s['member']
            severity_emoji = {'critical': '🚨', 'high': '⚠️', 'medium': '⚡', 'low': '📋'}.get(s['severity'], '📋')
            reasons_short = ", ".join(s['reasons'][:2])
            sus_lines.append(f"{severity_emoji} **{member.display_name}** (`{member.id}`)\n  ┗ {reasons_short}")
        sus_block = "\n".join(sus_lines) if sus_lines else "✅ _Aucun compte suspect détecté !_"

        bot_lines = []
        for b in self.bots[:5]:
            bot_lines.append(f"🤖 **{b['member'].name}** (`{b['member'].id}`)")
        if len(self.bots) > 5:
            bot_lines.append(f"_… et {len(self.bots) - 5} autres_")
        bot_block = "\n".join(bot_lines) if bot_lines else None

        self.clear_items()
        b_prev = Button(label="◀️ Préc.", style=discord.ButtonStyle.secondary, disabled=(self.page <= 0), custom_id="sspv2_prev")
        b_prev.callback = self._cb_prev
        b_next = Button(label="▶️ Suiv.", style=discord.ButtonStyle.secondary, disabled=(self.page >= max_page), custom_id="sspv2_next")
        b_next.callback = self._cb_next
        b_rescan = Button(label="🔄 Re-scanner", style=discord.ButtonStyle.primary, custom_id="sspv2_rescan")
        b_rescan.callback = self._cb_rescan
        b_kick_crit = Button(label="👢 Kick Critiques", style=discord.ButtonStyle.danger, disabled=(critical == 0), custom_id="sspv2_kick_crit")
        b_kick_crit.callback = self._cb_kick_crit
        b_kick_bots = Button(label="🤖 Kick Bots", style=discord.ButtonStyle.danger, disabled=(not self.bots), custom_id="sspv2_kick_bots")
        b_kick_bots.callback = self._cb_kick_bots
        b_kick_all = Button(label="👢 Kick Tous Suspects", style=discord.ButtonStyle.danger, disabled=((critical + high) == 0), custom_id="sspv2_kick_all")
        b_kick_all.callback = self._cb_kick_all
        b_close = Button(label="❌ Fermer", style=discord.ButtonStyle.secondary, custom_id="sspv2_close")
        b_close.callback = self._cb_close

        items: list = [
            v2_title("🔍 Scan des Comptes Suspects"),
            v2_subtitle(f"🚨 {critical} crit · ⚠️ {high} elevés · ⚡ {medium} moyens · 🤖 {len(self.bots)} bots non vérifiés"),
            v2_divider(),
            v2_title(f"👥 Suspects ({len(self.suspects)}) — Page {self.page + 1}/{max_page + 1}", level=3),
            v2_body(sus_block),
        ]
        if bot_block:
            items.append(v2_divider())
            items.append(v2_title("🤖 Bots non vérifiés", level=3))
            items.append(v2_body(bot_block))
        items.append(v2_divider())
        items.append(v2_subtitle("⚠️ Vérifie manuellement avant d'agir · Les scores sont indicatifs"))
        items.append(discord.ui.ActionRow(b_prev, b_next, b_rescan))
        items.append(discord.ui.ActionRow(b_kick_crit, b_kick_bots, b_kick_all))
        items.append(discord.ui.ActionRow(b_close))

        self.add_item(v2_container(*items, color=Palette.DANGER))

    async def render_to(self, interaction, *, edit=True):
        self._build()
        await _afficher_panneau(self, interaction, edit)

    async def render_after_defer(self, interaction):
        self._build()
        await interaction.edit_original_response(view=self, embed=None, attachments=[], content=None)

    async def _cb_prev(self, i):
        if self.page > 0:
            self.page -= 1
        await self.render_to(i, edit=True)

    async def _cb_next(self, i):
        max_page = max(0, (len(self.suspects) - 1) // self.per_page) if self.suspects else 0
        if self.page < max_page:
            self.page += 1
        await self.render_to(i, edit=True)

    async def _cb_rescan(self, i):
        await i.response.defer()
        await self.scan_members()
        self.page = 0
        await self.render_after_defer(i)

    async def _cb_kick_crit(self, i):
        critical = [s for s in self.suspects if s['severity'] == 'critical']
        if not critical:
            return await i.response.send_message("✅ Aucun compte critique à kick", ephemeral=True)
        v = ConfirmKickView(self.u, self.g, critical, 'critical')
        await i.response.send_message(
            embed=discord.Embed(title="⚠️ Confirmer le kick", description=f"Tu vas kick **{len(critical)}** compte(s) critique(s).", color=0xFF0000),
            view=v, ephemeral=True,
        )

    async def _cb_kick_bots(self, i):
        if not self.bots:
            return await i.response.send_message("✅ Aucun bot non vérifié à kick", ephemeral=True)
        v = ConfirmKickView(self.u, self.g, self.bots, 'bots')
        await i.response.send_message(
            embed=discord.Embed(title="⚠️ Confirmer le kick des bots", description=f"Tu vas kick **{len(self.bots)}** bot(s) non vérifié(s).", color=0xFF0000),
            view=v, ephemeral=True,
        )

    async def _cb_kick_all(self, i):
        high_and_critical = [s for s in self.suspects if s['severity'] in ['critical', 'high']]
        if not high_and_critical:
            return await i.response.send_message("✅ Aucun compte à kick", ephemeral=True)
        v = ConfirmKickView(self.u, self.g, high_and_critical, 'all')
        await i.response.send_message(
            embed=discord.Embed(
                title="⚠️ Confirmer le kick massif",
                description=f"Tu vas kick **{len(high_and_critical)}** compte(s) suspects (critiques + élevés).\n\n**⚠️ Action irréversible !**",
                color=0xFF0000,
            ),
            view=v, ephemeral=True,
        )

    async def _cb_close(self, i):
        await i.response.edit_message(content="✅ Scan fermé", embed=None, view=None, attachments=[])


class SuspectScanPanel(View):
    """Panel pour scanner et afficher les comptes suspects"""
    def __init__(self, u, g):
        super().__init__(timeout=300)
        self.u = u
        self.g = g
        self.suspects = []
        self.bots = []
        self.page = 0
        self.per_page = 8
        self.scan_complete = False
    
    async def scan_members(self):
        """Scanne tous les membres pour détecter les comptes suspects"""
        self.suspects = []
        self.bots = []
        self.scan_complete = False
        
        try:
            # Récupérer la liste des membres
            members = list(self.g.members)
            print(f"[SCANNER] Scan de {len(members)} membres sur {self.g.name}")
            
            for member in members:
                try:
                    # Ignorer le bot lui-même
                    if member.id == bot.user.id:
                        continue
                    
                    if member.bot:
                        # Vérifier si c'est un bot non vérifié
                        try:
                            if not member.public_flags.verified_bot:
                                self.bots.append({
                                    'member': member,
                                    'reason': "Bot non vérifié par Discord",
                                    'severity': 'medium'
                                })
                        except:
                            pass
                        continue
                    
                    # Calculer le score de suspicion
                    suspicion_score = 0
                    reasons = []
                    
                    # 1. Âge du compte
                    try:
                        created = member.created_at
                        if created.tzinfo is None:
                            created = created.replace(tzinfo=timezone.utc)
                        account_age = (now() - created).days
                        
                        if account_age < 1:
                            suspicion_score += 50
                            reasons.append(f"Créé aujourd'hui")
                        elif account_age < 7:
                            suspicion_score += 30
                            reasons.append(f"Compte récent ({account_age}j)")
                        elif account_age < 30:
                            suspicion_score += 10
                            reasons.append(f"Compte jeune ({account_age}j)")
                    except Exception as e:
                        print(f"[SCANNER] Erreur âge {member.id}: {e}")
                    
                    # 2. Pas d'avatar personnalisé
                    try:
                        if member.avatar is None:
                            suspicion_score += 15
                            reasons.append("Pas d'avatar")
                    except:
                        pass
                    
                    # 3. Nom suspect
                    try:
                        name = member.name.lower()
                        # Finit par des chiffres
                        if len(name) > 4 and name[-4:].isdigit():
                            suspicion_score += 10
                            reasons.append("Nom générique")
                        # Pattern de bot (User1234)
                        if re.match(r'^[a-z]+\d{4,}$', name):
                            suspicion_score += 20
                            reasons.append("Pattern bot")
                    except:
                        pass
                    
                    # 4. Flags Discord
                    try:
                        flags = member.public_flags
                        if flags.spammer:
                            suspicion_score += 100
                            reasons.append("🚨 SPAMMER Discord")
                    except:
                        pass
                    
                    # 5. Pas de rôles
                    try:
                        if len(member.roles) <= 1:
                            suspicion_score += 5
                            reasons.append("Aucun rôle")
                    except:
                        pass
                    
                    # 6. Rejoint récemment
                    try:
                        if member.joined_at:
                            joined = member.joined_at
                            if joined.tzinfo is None:
                                joined = joined.replace(tzinfo=timezone.utc)
                            joined_hours = (now() - joined).total_seconds() / 3600
                            if joined_hours < 1:
                                suspicion_score += 15
                                reasons.append("Rejoint < 1h")
                            elif joined_hours < 24:
                                suspicion_score += 5
                                reasons.append("Rejoint aujourd'hui")
                    except:
                        pass
                    
                    # Ajouter si score suffisant
                    if suspicion_score >= 15 and reasons:
                        severity = 'critical' if suspicion_score >= 80 else 'high' if suspicion_score >= 50 else 'medium' if suspicion_score >= 30 else 'low'
                        self.suspects.append({
                            'member': member,
                            'score': suspicion_score,
                            'reasons': reasons,
                            'severity': severity
                        })
                        
                except Exception as ex:
                    print(f"[SCANNER] Erreur membre {member.id}: {ex}")
                    continue
            
            # Trier par score décroissant
            self.suspects.sort(key=lambda x: x['score'], reverse=True)
            self.scan_complete = True
            print(f"[SCANNER] Terminé: {len(self.suspects)} suspects, {len(self.bots)} bots non vérifiés")
            
        except Exception as ex:
            print(f"[SCANNER] Erreur globale: {ex}")
            import traceback
            traceback.print_exc()
            self.scan_complete = True
    
    async def embed(self):
        e = discord.Embed(title="🔍 Scan des Comptes Suspects", color=0xE74C3C)
        
        # Résumé
        critical = len([s for s in self.suspects if s['severity'] == 'critical'])
        high = len([s for s in self.suspects if s['severity'] == 'high'])
        medium = len([s for s in self.suspects if s['severity'] == 'medium'])
        
        summary = f"**🚨 Critiques:** {critical}\n**⚠️ Élevés:** {high}\n**⚡ Moyens:** {medium}\n**🤖 Bots non vérifiés:** {len(self.bots)}"
        e.add_field(name="📊 Résumé", value=summary, inline=False)
        
        # Liste des suspects (paginée)
        if self.suspects:
            start = self.page * self.per_page
            end = start + self.per_page
            page_suspects = self.suspects[start:end]
            
            lines = []
            for s in page_suspects:
                member = s['member']
                severity_emoji = {'critical': '🚨', 'high': '⚠️', 'medium': '⚡', 'low': '📋'}.get(s['severity'], '📋')
                reasons_short = ", ".join(s['reasons'][:2])
                lines.append(f"{severity_emoji} **{member.display_name}** (`{member.id}`)\n   └ {reasons_short}")
            
            e.add_field(
                name=f"👥 Suspects ({len(self.suspects)}) - Page {self.page + 1}/{max(1, (len(self.suspects) - 1) // self.per_page + 1)}",
                value="\n".join(lines) if lines else "*Aucun*",
                inline=False
            )
        else:
            e.add_field(name="👥 Suspects", value="✅ Aucun compte suspect détecté !", inline=False)
        
        # Bots non vérifiés
        if self.bots:
            bot_lines = [f"🤖 **{b['member'].name}** (`{b['member'].id}`)" for b in self.bots[:5]]
            if len(self.bots) > 5:
                bot_lines.append(f"*... et {len(self.bots) - 5} autres*")
            e.add_field(name="🤖 Bots non vérifiés", value="\n".join(bot_lines), inline=False)
        
        e.set_footer(text="⚠️ Vérifiez manuellement avant d'agir • Les scores sont indicatifs")
        return e
    
    @discord.ui.button(label="◀️ Préc.", style=discord.ButtonStyle.secondary, row=0)
    async def prev_page(self, i, b):
        if self.page > 0:
            self.page -= 1
        await i.response.edit_message(embed=await self.embed(), view=self)
    
    @discord.ui.button(label="▶️ Suiv.", style=discord.ButtonStyle.secondary, row=0)
    async def next_page(self, i, b):
        max_page = max(0, (len(self.suspects) - 1) // self.per_page)
        if self.page < max_page:
            self.page += 1
        await i.response.edit_message(embed=await self.embed(), view=self)
    
    @discord.ui.button(label="🔄 Re-scanner", style=discord.ButtonStyle.primary, row=0)
    async def rescan(self, i, b):
        await i.response.defer()
        await self.scan_members()
        await i.edit_original_response(embed=await self.embed(), view=self)
    
    @discord.ui.button(label="👢 Kick Critiques", style=discord.ButtonStyle.danger, row=1)
    async def kick_critical(self, i, b):
        critical = [s for s in self.suspects if s['severity'] == 'critical']
        if not critical:
            return await i.response.send_message("✅ Aucun compte critique à kick", ephemeral=True)
        
        v = ConfirmKickView(self.u, self.g, critical, 'critical')
        await i.response.send_message(
            embed=discord.Embed(
                title="⚠️ Confirmer le kick",
                description=f"Vous allez kick **{len(critical)}** compte(s) critique(s).\n\nÊtes-vous sûr ?",
                color=0xFF0000
            ),
            view=v,
            ephemeral=True
        )
    
    @discord.ui.button(label="🤖 Kick Bots", style=discord.ButtonStyle.danger, row=1)
    async def kick_bots(self, i, b):
        if not self.bots:
            return await i.response.send_message("✅ Aucun bot non vérifié à kick", ephemeral=True)
        
        v = ConfirmKickView(self.u, self.g, self.bots, 'bots')
        await i.response.send_message(
            embed=discord.Embed(
                title="⚠️ Confirmer le kick des bots",
                description=f"Vous allez kick **{len(self.bots)}** bot(s) non vérifié(s).\n\nÊtes-vous sûr ?",
                color=0xFF0000
            ),
            view=v,
            ephemeral=True
        )
    
    @discord.ui.button(label="👢 Kick Tous Suspects", style=discord.ButtonStyle.danger, row=1)
    async def kick_all(self, i, b):
        high_and_critical = [s for s in self.suspects if s['severity'] in ['critical', 'high']]
        if not high_and_critical:
            return await i.response.send_message("✅ Aucun compte à kick", ephemeral=True)
        
        v = ConfirmKickView(self.u, self.g, high_and_critical, 'all')
        await i.response.send_message(
            embed=discord.Embed(
                title="⚠️ Confirmer le kick massif",
                description=f"Vous allez kick **{len(high_and_critical)}** compte(s) suspects (critiques + élevés).\n\n**⚠️ Cette action est irréversible !**",
                color=0xFF0000
            ),
            view=v,
            ephemeral=True
        )
    
    @discord.ui.button(label="❌ Fermer", style=discord.ButtonStyle.secondary, row=2)
    async def close(self, i, b):
        await i.response.edit_message(content="✅ Scan fermé", embed=None, view=None)

class ConfirmKickView(View):
    """Vue de confirmation pour kick les suspects"""
    def __init__(self, u, g, targets, kick_type):
        super().__init__(timeout=60)
        self.u = u
        self.g = g
        self.targets = targets
        self.kick_type = kick_type
    
    async def interaction_check(self, i) -> bool:
        # Garde : seul l'ouvrant peut confirmer (anti-clic d'un tiers).
        try:
            if i.user.id != self.u.id:
                await i.response.send_message("⛔ Ce panneau ne t'est pas destiné.", ephemeral=True)
                return False
        except Exception:
            return False
        return True

    @discord.ui.button(label="✅ Confirmer", style=discord.ButtonStyle.danger)
    async def confirm(self, i, b):
        await i.response.defer()

        kicked = 0
        failed = 0

        for t in self.targets:
            member = t['member']
            try:
                reason = f"Anti-Raid: {t.get('reason', 'Compte suspect')} (score: {t.get('score', 'N/A')})"
                # RÈGLE FONDATEUR-ONLY (2026-06-13) : pas de kick de masse → on ISOLE
                # (réversible). Le fondateur reste seul à pouvoir bannir/kicker.
                await isolate_member(member, reason)
                kicked += 1
            except Exception:
                failed += 1

        await i.edit_original_response(
            embed=discord.Embed(
                title="🔒 Isolement terminé",
                description=f"**{kicked}** membre(s) isolé(s) en quarantaine\n**{failed}** échec(s)\n"
                            f"_Le bannissement éventuel reste au fondateur._",
                color=0x2ECC71 if failed == 0 else 0xE67E22
            ),
            view=None
        )
    
    @discord.ui.button(label="❌ Annuler", style=discord.ButtonStyle.secondary)
    async def cancel(self, i, b):
        await i.response.edit_message(content="❌ Kick annulé", embed=None, view=None)




