async def send_mod_log(guild, action, mod, target, reason=None, duration=None, extra=None):
    """Envoie un log de modération.

    Phase 3.7 : envoie AUSSI dans le salon unifié (ulogger2026) si configuré.
    Le canal legacy `mod_log_channel` continue de fonctionner pour la rétrocompat.
    """
    # ───── Salon unifié (Phase 3.7) ─────
    try:
        action_to_event = {
            'warn':        ulogger2026.EventType.MOD_WARN,
            'unwarn':      ulogger2026.EventType.MOD_UNWARN,
            'mute':        ulogger2026.EventType.MOD_MUTE,
            'unmute':      ulogger2026.EventType.MOD_UNMUTE,
            'kick':        ulogger2026.EventType.MOD_KICK,
            'ban':         ulogger2026.EventType.MOD_BAN,
            'unban':       ulogger2026.EventType.MOD_UNBAN,
            'timeout':     ulogger2026.EventType.MOD_TIMEOUT,
            'purge':       ulogger2026.EventType.MOD_PURGE,
            'lock':        ulogger2026.EventType.MOD_LOCK,
            'unlock':      ulogger2026.EventType.MOD_UNLOCK,
            'slowmode':    ulogger2026.EventType.MOD_SLOWMODE,
            'infractions': ulogger2026.EventType.COMMAND_EXEC,
            'anti_raid':   ulogger2026.EventType.SEC_RAID,
            'anti_alt':    ulogger2026.EventType.SEC_ALT,
            'anti_newaccount': ulogger2026.EventType.SEC_NEWACCOUNT,
        }
        ev = action_to_event.get(action, ulogger2026.EventType.COMMAND_EXEC)
        action_labels = {
            'warn': "avertissement", 'unwarn': "retrait d'avertissement",
            'mute': "mute", 'unmute': "unmute", 'kick': "expulsion",
            'ban': "bannissement", 'unban': "débannissement",
            'timeout': "timeout", 'purge': "purge de messages",
        }
        verb = action_labels.get(action, action)
        try:
            target_name = f"{target.mention} (`{target}`)" if target else "_cible inconnue_"
        except Exception:
            target_name = "_cible_"
        desc = f"**{verb.capitalize()}** appliqué à {target_name}."
        extra_dict = {}
        if duration:
            extra_dict["⏱️ Durée"] = duration
        if extra:
            extra_dict["ℹ️ Détail"] = str(extra)
        await ulogger2026.log_event(
            bot, guild, ev,
            description=desc,
            user=target,
            moderator=mod,
            reason=reason,
            extra=extra_dict or None,
        )
    except Exception as ex:
        print(f"[UNIFIED MOD LOG] {ex}")

    # ───── Salon legacy (rétrocompat) ─────
    try:
        c = await cfg(guild.id)
        log_ch = guild.get_channel(c.get('mod_log_channel', 0))
        if not log_ch:
            return

        colors = {'warn': 0xF39C12, 'unwarn': 0x2ECC71, 'mute': 0xE67E22, 'unmute': 0x2ECC71, 'kick': 0xE74C3C, 'ban': 0xC0392B, 'unban': 0x27AE60, 'infractions': 0x3498DB}
        emojis = {'warn': '⚠️', 'unwarn': '✅', 'mute': '🔇', 'unmute': '🔊', 'kick': '👢', 'ban': '🔨', 'unban': '🔓', 'infractions': '📋'}
        titles = {'warn': 'Avertissement', 'unwarn': 'Warn supprimé', 'mute': 'Mute', 'unmute': 'Unmute', 'kick': 'Expulsion', 'ban': 'Bannissement', 'unban': 'Débannissement', 'infractions': 'Consultation infractions'}

        e = discord.Embed(
            color=colors.get(action, C.ORANGE),
            timestamp=now()
        )
        e.set_author(name=f"{emojis.get(action, '🔨')} {titles.get(action, action.upper())}", icon_url=guild.icon.url if guild.icon else None)
        e.add_field(name="👮 Modérateur", value=f"{mod.mention}\n`{mod.id}`", inline=True)
        e.add_field(name="👤 Membre", value=f"{target.mention}\n`{target.id}`", inline=True)

        if duration:
            e.add_field(name="⏱️ Durée", value=duration, inline=True)
        if reason:
            e.add_field(name="📝 Raison", value=reason[:1024], inline=False)
        if extra:
            e.add_field(name="ℹ️ Info", value=extra, inline=False)

        e.set_thumbnail(url=target.display_avatar.url)
        e.set_footer(text=f"ID cible: {target.id}")
        await webhook_send(log_ch, 'mod_log', embed=e)
    except Exception as ex:
        print(f"[MOD LOG ERROR] {ex}")

# NOTE: ModerationPanel (View V1, embed) supprime — remplace par ModerationPanelV2 (LayoutView).
# Jamais instancie (seule ref externe etait dans MainPanel V1, lui aussi supprime).

class ModerationPanelV2(LayoutView):
    """Panneau de modération en V2 — config rôles + salon logs."""

    def __init__(self, u, g):
        super().__init__(timeout=600)
        self.u = u
        self.g = g
        self._loading = True
        # Build initial (sera complété en async)

    async def interaction_check(self, i):
        return i.user.id == self.u.id

    async def render_to(self, interaction: discord.Interaction, *, edit: bool = True):
        """Construit le LayoutView et l'envoie/édite via interaction."""
        c = await cfg(self.g.id)

        # Compter les infractions
        inf_count = 0
        try:
            async with get_db() as db:
                async with db.execute('SELECT COUNT(*) FROM infractions WHERE guild_id=?', (self.g.id,)) as cur:
                    row = await cur.fetchone()
                    inf_count = row[0] if row else 0
        except Exception as ex:
            print(f"[MOD-V2] Erreur count infractions: {ex}")

        # Récupérer les éléments configurés
        log_ch = self.g.get_channel(c.get('mod_log_channel', 0))
        warn_role = self.g.get_role(c.get('mod_warn_role', 0))
        mute_role = self.g.get_role(c.get('mod_mute_role', 0))
        inf_role = self.g.get_role(c.get('mod_infractions_role', 0))
        clear_role = self.g.get_role(c.get('mod_clear_role', 0))

        def dot(item):
            return f"🔘 {item.mention if hasattr(item, 'mention') else item.name}" if item else "⚪ _non défini_"

        # Reconstruire les boutons à chaque render (pour les ré-attacher)
        self.clear_items()

        b_logs = Button(label="📜 Salon Logs", style=discord.ButtonStyle.primary, custom_id="mpv2_set_logs")
        b_logs.callback = self._cb_set_logs
        b_warn = Button(label="⚠️ Rôle warn", style=discord.ButtonStyle.primary, custom_id="mpv2_set_warn")
        b_warn.callback = self._cb_set_warn
        b_mute = Button(label="🔇 Rôle mute", style=discord.ButtonStyle.primary, custom_id="mpv2_set_mute")
        b_mute.callback = self._cb_set_mute
        b_inf = Button(label="📋 Rôle infractions", style=discord.ButtonStyle.primary, custom_id="mpv2_set_inf")
        b_inf.callback = self._cb_set_inf
        b_clear = Button(label="🧹 Rôle clear", style=discord.ButtonStyle.primary, custom_id="mpv2_set_clear")
        b_clear.callback = self._cb_set_clear
        b_back = Button(label="◀️ Retour", style=discord.ButtonStyle.secondary, custom_id="mpv2_back")
        b_back.callback = self._cb_back

        items: list = []
        if self.g.icon:
            items.append(v2_section(
                v2_title("🔨 Modération"),
                v2_subtitle(f"`{inf_count}` infractions enregistrées"),
                accessory=v2_thumb(self.g.icon.url),
            ))
        else:
            items.append(v2_title("🔨 Modération"))
            items.append(v2_subtitle(f"`{inf_count}` infractions enregistrées"))

        items.append(v2_divider())
        items.append(v2_body(
            f"📜 **Salon logs** · {dot(log_ch)}\n"
            f"⚠️ **Rôle /warn** · {dot(warn_role)}\n"
            f"🔇 **Rôle /mute** · {dot(mute_role)}\n"
            f"📋 **Rôle /infractions** · {dot(inf_role)}\n"
            f"🧹 **Rôle /mod clear** · {dot(clear_role)}"
        ))
        items.append(v2_divider())

        items.append(discord.ui.ActionRow(b_logs, b_warn, b_mute, b_inf, b_clear))
        items.append(discord.ui.ActionRow(b_back))

        self.add_item(v2_container(*items, color=Palette.WARNING))

        await _afficher_panneau(self, interaction, edit)

    async def _open_channel_picker(self, interaction, key, label):
        """Phase 3.0k : V2 native picker (plus de transition V2->V1 qui plantait)."""
        v = V2GenericChannelPicker(
            self.u, self.g,
            config_key=key,
            return_panel_factory=lambda: ModerationPanelV2(self.u, self.g),
            title=f"📜 {label}",
            description=f"Sélectionne le salon. {len(list(self.g.text_channels))} disponibles.",
            color=0xE67E22,
        )
        await v.render_to(interaction, edit=True)

    async def _open_role_picker(self, interaction, key, label):
        """Phase 3.0k : V2 native picker."""
        v = V2GenericRolePicker(
            self.u, self.g,
            config_key=key,
            return_panel_factory=lambda: ModerationPanelV2(self.u, self.g),
            title=f"⚙️ {label}",
            description="Sélectionne le rôle minimum requis pour cette commande.",
            color=0xE67E22,
        )
        await v.render_to(interaction, edit=True)

    async def _cb_set_logs(self, i):
        await self._open_channel_picker(i, 'mod_log_channel', 'Salon Logs')

    async def _cb_set_warn(self, i):
        await self._open_role_picker(i, 'mod_warn_role', 'Rôle /warn')

    async def _cb_set_mute(self, i):
        await self._open_role_picker(i, 'mod_mute_role', 'Rôle /mute')

    async def _cb_set_inf(self, i):
        await self._open_role_picker(i, 'mod_infractions_role', 'Rôle /infractions')

    async def _cb_set_clear(self, i):
        await self._open_role_picker(i, 'mod_clear_role', 'Rôle /mod clear')

    async def _cb_back(self, i):
        # Refonte 2026-08 : retour direct à la racine /configure (MainPanelV2).
        v = MainPanelV2(self.u, self.g)
        await v.render_to(i, edit=True)


