# Phase 15 : warnings APIs mortes — PERSISTÉS sur disque (24h cooldown)
# Avant : set RAM qui se vidait à chaque redémarrage → spam de warnings après chaque push
# Maintenant : JSON sur disque, warning au max 1× par 24h par (guild, platform)
# On utilise le même répertoire que la DB (DB_PATH) pour la persistance Railway
def _api_warning_state_file_path():
    """Retourne le chemin du fichier JSON de persistance des warnings."""
    from pathlib import Path
    if os.path.exists('/data'):
        d = Path('/data/api_warnings')
    else:
        d = Path('./data/api_warnings')
    try:
        d.mkdir(parents=True, exist_ok=True)
    except (OSError, PermissionError):
        d = Path('/tmp/api_warnings')
        try:
            d.mkdir(parents=True, exist_ok=True)
        except Exception:
            pass
    return d / "state.json"


# ─── tree.sync() conditionnel (gain quota Discord + boot plus rapide) ─────────
# Le sync global Discord est lent et compte dans le quota. Si l'ensemble des
# commandes (noms + descriptions + params) est INCHANGÉ depuis le dernier boot,
# on SKIP le sync. On stocke un hash stable sur le volume persistant (même répertoire
# que la DB). GARDE-FOUS : env FORCE_SYNC=1 force le sync ; en cas de DOUTE/erreur
# de hash, on SYNC (comportement actuel préservé, jamais de régression).
def _sync_hash_file_path():
    """Chemin du fichier qui mémorise le hash des commandes (persistance Railway)."""
    from pathlib import Path
    if os.path.exists('/data'):
        d = Path('/data/cmd_sync')
    else:
        d = Path('./data/cmd_sync')
    try:
        d.mkdir(parents=True, exist_ok=True)
    except (OSError, PermissionError):
        d = Path('/tmp/cmd_sync')
        try:
            d.mkdir(parents=True, exist_ok=True)
        except Exception:
            pass
    return d / "tree_hash.txt"


def _compute_tree_hash(tree) -> str:
    """Hash stable de l'ensemble des commandes globales.

    On sérialise nom + description + paramètres (nom/type/required/description)
    de CHAQUE commande — y compris les SOUS-commandes des groupes — trié pour
    être déterministe indépendamment de l'ordre d'enregistrement. Tout est
    défensif (getattr) : si une version de discord.py change une API, on lève →
    l'appelant fera SYNC (fail-safe, jamais de régression).
    """
    import hashlib

    def _one(cmd) -> str:
        name = getattr(cmd, "qualified_name", None) or getattr(cmd, "name", "?")
        desc = getattr(cmd, "description", "") or ""
        params = []
        # app_commands.Command expose .parameters ; les groupes n'en ont pas.
        for p in (getattr(cmd, "parameters", None) or []):
            ptype = getattr(getattr(p, "type", None), "value", getattr(p, "type", ""))
            params.append(
                f"{getattr(p, 'name', '')}:{ptype}:"
                f"{int(bool(getattr(p, 'required', False)))}:"
                f"{getattr(p, 'description', '') or ''}"
            )
        params.sort()
        ctype = type(cmd).__name__  # distingue Command / Group / ContextMenu
        return f"{ctype}|{name}|{desc}|{'§'.join(params)}"

    parts = []
    for cmd in tree.get_commands():
        parts.append(_one(cmd))
        # Groupes : descendre dans les sous-commandes (sinon un changement de
        # description d'une sous-commande passerait inaperçu → sync skippé à tort).
        walk = getattr(cmd, "walk_commands", None)
        if callable(walk):
            try:
                for sub in walk():
                    if sub is not cmd:
                        parts.append(_one(sub))
            except Exception:
                # En cas de souci d'introspection, on ajoute un marqueur qui
                # forcera une différence de hash → sync (fail-safe).
                parts.append(f"WALKERR|{getattr(cmd, 'name', '?')}")
    parts.sort()
    blob = "\n".join(parts).encode("utf-8")
    return hashlib.sha256(blob).hexdigest()


_api_warning_cooldown_seconds = 24 * 3600  # 24h
_api_warning_state: dict[str, float] = {}  # key = "guild_id:platform" → timestamp
_api_warning_state_loaded = False


def _load_api_warning_state():
    global _api_warning_state, _api_warning_state_loaded
    if _api_warning_state_loaded:
        return
    try:
        p = _api_warning_state_file_path()
        if p.exists():
            with open(p, encoding='utf-8') as f:
                _api_warning_state = json.load(f) or {}
    except Exception as ex:
        print(f"[_load_api_warning_state] {ex}")
        _api_warning_state = {}
    _api_warning_state_loaded = True


def _save_api_warning_state():
    try:
        p = _api_warning_state_file_path()
        p.write_text(
            json.dumps(_api_warning_state, indent=2),
            encoding='utf-8',
        )
    except Exception as ex:
        print(f"[_save_api_warning_state] {ex}")


async def _warn_api_dead(guild, platform: str, reason: str):
    """Envoie UN seul warning par 24h par guild/plateforme dans le salon de logs.

    Phase 15 : persisté sur disque pour survivre aux redémarrages.
    """
    _load_api_warning_state()
    key = f"{guild.id}:{platform}"
    now_ts = time.time()
    last_ts = _api_warning_state.get(key, 0)
    if now_ts - last_ts < _api_warning_cooldown_seconds:
        return  # Déjà warn dans les 24h
    _api_warning_state[key] = now_ts
    _save_api_warning_state()
    try:
        await ulogger2026.log_event(
            bot, guild, ulogger2026.EventType.BOT_INFO,
            title_override=f"⚠️ API {platform.title()} indisponible",
            description=(
                f"**Les publications {platform} ne peuvent pas être détectées automatiquement.**\n\n"
                f"📡 Cause : {reason}\n\n"
                "💡 Solution : publie manuellement dans le salon configuré. "
                "Le bot continuera de vérifier en arrière-plan au cas où l'API revient."
            ),
            extra={"🛠️ Action": "Aucune (la détection auto est en panne) · Prochaine alerte dans 24h max"},
        )
    except Exception as ex:
        print(f"[_warn_api_dead] {platform}: {ex}")

