ticket_group = app_commands.Group(
    name="ticket",
    description="🎫 Priority + templates de réponse + stats tickets",
)


def _tix_is_staff(member: discord.Member) -> bool:
    """True si peut gérer templates + voir stats."""
    try:
        return (
            member.id == SUPER_OWNER_ID
            or (member.guild and member.id == member.guild.owner_id)
            or member.guild_permissions.administrator
            or member.guild_permissions.manage_messages
        )
    except Exception:
        return False


async def _tix_is_in_ticket(channel) -> bool:
    """Check si on est dans un channel ticket actuel (status open)."""
    if not isinstance(channel, discord.TextChannel):
        return False
    try:
        async with get_db() as db:
            async with db.execute(
                "SELECT 1 FROM tickets WHERE channel_id=? AND status='open'",
                (channel.id,),
            ) as cur:
                return (await cur.fetchone()) is not None
    except Exception:
        return False


@ticket_group.command(name="search", description="🔎 Liste les tickets ouverts (option : seulement les non pris)")
@app_commands.describe(non_pris="N'afficher que les tickets PAS encore pris en charge")
async def ticket_search_cmd(i: discord.Interaction, non_pris: bool = False):
    # #18 : triage des tickets — LECTURE SEULE (le bot ne ferme/mute jamais un ticket).
    if not _tix_is_staff(i.user):
        return await i.response.send_message("❌ Réservé au staff.", ephemeral=True)
    try:
        await i.response.defer(ephemeral=True)
    except Exception:
        pass
    try:
        q = ("SELECT id, channel_id, user_id, claimed_by, created_at FROM tickets "
             "WHERE guild_id=? AND status='open'")
        if non_pris:
            q += " AND (claimed_by IS NULL OR claimed_by=0)"
        q += " ORDER BY created_at ASC LIMIT 40"
        async with get_db() as db:
            async with db.execute(q, (i.guild.id,)) as cur:
                rows = await cur.fetchall()
    except Exception as ex:
        return await i.followup.send(f"❌ Erreur : `{ex}`", ephemeral=True)
    if not rows:
        return await i.followup.send("✅ Aucun ticket ouvert" + (" non pris." if non_pris else "."), ephemeral=True)
    lines = []
    for tid, chid, uid, claimed, cat in rows:
        ch = i.guild.get_channel(int(chid)) if chid else None
        chm = ch.mention if ch else f"`#{chid}`"
        claim_txt = f"pris par <@{int(claimed)}>" if claimed else "**non pris**"
        age = ""
        try:
            if cat:
                st = datetime.fromisoformat(cat)
                if st.tzinfo is None:
                    st = st.replace(tzinfo=timezone.utc)
                age = f" · <t:{int(st.timestamp())}:R>"
        except Exception:
            pass
        lines.append(f"🎫 #{tid} {chm} · <@{int(uid)}> · {claim_txt}{age}")
    txt = ("**🔎 Tickets ouverts" + (" (non pris)" if non_pris else "") + f"** ({len(rows)})\n"
           + "\n".join(lines))
    await i.followup.send(txt[:1900], ephemeral=True)


@ticket_group.command(name="queue", description="📊 Charge des tickets par staff + nombre de non assignés")
async def ticket_queue_cmd(i: discord.Interaction):
    # #19 : équilibrage de charge — LECTURE SEULE.
    if not _tix_is_staff(i.user):
        return await i.response.send_message("❌ Réservé au staff.", ephemeral=True)
    try:
        await i.response.defer(ephemeral=True)
    except Exception:
        pass
    try:
        async with get_db() as db:
            async with db.execute(
                "SELECT claimed_by, COUNT(*) FROM tickets WHERE guild_id=? AND status='open' "
                "GROUP BY claimed_by", (i.guild.id,)) as cur:
                rows = await cur.fetchall()
    except Exception as ex:
        return await i.followup.send(f"❌ Erreur : `{ex}`", ephemeral=True)
    unclaimed = 0
    by_staff = []
    for claimed, cnt in rows:
        if not claimed:
            unclaimed += int(cnt)
        else:
            by_staff.append((int(claimed), int(cnt)))
    by_staff.sort(key=lambda x: -x[1])
    txt = "**📊 Charge des tickets ouverts**\n"
    txt += (f"🆕 **Non assignés : `{unclaimed}`** — à prendre en charge\n\n" if unclaimed
            else "✅ Aucun ticket non assigné.\n\n")
    if by_staff:
        txt += "\n".join(f"👮 <@{sid}> · `{cnt}` ticket(s)" for sid, cnt in by_staff[:30])
        if len(by_staff) > 1:
            _least = by_staff[-1]
            txt += f"\n\n💡 Le moins chargé : <@{_least[0]}> (`{_least[1]}`)."
    else:
        txt += "_Aucun ticket actuellement pris en charge._"
    await i.followup.send(txt[:1900], ephemeral=True)


