@bot.event
async def on_member_ban(guild, user):
    """Sauvegarde les informations du membre banni pour détection de comptes secondaires"""
    try:
        # Récupérer le hash de l'avatar
        avatar_hash = str(user.avatar.key) if user.avatar else "default"
        
        # Essayer de récupérer la raison du ban
        reason = "Non spécifiée"
        try:
            ban_entry = await guild.fetch_ban(user)
            if ban_entry.reason:
                reason = ban_entry.reason
        except:
            pass
        
        # Sauvegarder les infos du ban
        await save_ban_info(guild.id, user.id, user.name, avatar_hash, reason)
        print(f"[BAN] Sauvegardé: {user.name} ({user.id}) sur {guild.name}")
        
    except Exception as ex:
        print(f"[BAN] Erreur sauvegarde: {ex}")
    # LOG « qui a banni qui » (owner). Ban MANUEL (Discord) → auteur via audit. Ban par le
    # BOT (commande/sanction) = DÉJÀ loggé par sanction() → _log_audited l'ignore (pas de
    # double-log). FAIL-SAFE.
    try:
        await _log_audited(
            guild, ulogger2026.EventType.MOD_BAN,
            discord.AuditLogAction.ban, user.id,
            lambda a: (f"🔨 **{a}** a banni {user.mention} (`{user}`)."
                       if a else f"🔨 {user.mention} (`{user}`) a été banni."),
            user=user,
        )
    except Exception as ex:
        print(f"[on_member_ban log] {ex}")

@bot.event
async def on_member_remove(m):
    # VEILLEUR questions sans réponse : l'auteur quitte → on ne suit plus ses questions.
    try:
        _unanswered_clear_for_author(m.guild.id, m.id)
    except Exception:
        pass
    # owner 2026-06-30 : DÉGRADATION CRESCENDO — purge l'état de restriction d'un membre qui
    # part (cache RAM + ligne DB) → pas de « restriction fantôme » s'il revient. FAIL-SAFE.
    try:
        asyncio.create_task(recidivism_module.forget(m.guild.id, m.id))
    except Exception:
        pass
    # LOG « qui a expulsé qui » (owner) : on distingue un KICK d'un départ VOLONTAIRE via
    # l'audit (action kick, fenêtre courte) → require_actor=True : pas d'entrée kick = simple
    # départ → AUCUN log. Kick par le bot = ignoré. (Un BAN provoque aussi ce départ mais
    # SANS entrée kick → pas de double-log ; le ban est loggé par on_member_ban.) FAIL-SAFE.
    try:
        if getattr(m, 'guild', None) is not None and not getattr(m, 'bot', False):
            await _log_audited(
                m.guild, ulogger2026.EventType.MOD_KICK,
                discord.AuditLogAction.kick, m.id,
                lambda a: f"👢 **{a}** a expulsé {m.mention} (`{m}`).",
                require_actor=True, user=m,
            )
    except Exception as ex:
        print(f"[on_member_remove kick log] {ex}")

    # ═══ Tracking stats journalières ═══
    try:
        today = now().strftime('%Y-%m-%d')
        async with get_db() as db:
            await db.execute('''
                INSERT INTO daily_guild_stats (guild_id, date, left_members)
                VALUES (?, ?, 1)
                ON CONFLICT(guild_id, date) DO UPDATE SET left_members = left_members + 1
            ''', (m.guild.id, today))
            await db.commit()
    except: pass

    # ═══ Phase 139 : Observabilité (leave tracking pour retention) ═══
    try:
        await obs_module.record_leave(m.guild.id, m.id)
    except Exception as ex:
        print(f"[on_member_remove obs_record_leave] {ex}")

    # ═══ Log unifié (Phase 3.7) ═══
    try:
        await ulogger2026.log_member_leave(bot, m.guild, m)
    except Exception as ex:
        print(f"[UNIFIED LOG member_leave] {ex}")
    
    try:
        async with get_db() as db:
            async with db.execute("SELECT id, channel_id, claimed_by, answers FROM tickets WHERE guild_id=? AND user_id=? AND status='open'", (m.guild.id, m.id)) as c:
                tks = await c.fetchall()
        for tk in tks:
            ans = {}
            try: ans = json.loads(tk[3]) if tk[3] else {}
            except: pass
            ti = {'id': tk[0], 'user': m.id, 'claimed': tk[2] or 0, 'answers': ans}
            ch = m.guild.get_channel(tk[1])
            await send_ticket_log(m.guild, 'leave', m, ti)
            if ch:
                leave_e = discord.Embed(color=C.ORANGE, timestamp=now())
                leave_e.set_author(name="🚪 Utilisateur parti", icon_url=m.display_avatar.url if m.display_avatar else None)
                leave_e.description = f"**{m.display_name}** (`{m.name}`) a quitté le serveur."
                leave_e.set_thumbnail(url=m.display_avatar.url if m.display_avatar else None)
                await webhook_send(ch, 'ticket', embed=leave_e)
    except: pass

    # ═══ Phase 28.3 : Goodbye message ═══
    try:
        await _handle_goodbye(m)
    except Exception as ex:
        print(f"[goodbye] {ex}")


async def _handle_goodbye(member):
    """Phase 28.3 — envoie le message de goodbye."""
    c = await cfg(member.guild.id)
    if not c.get('goodbye_enabled', False):
        return
    ch_id = int(c.get('goodbye_channel', 0) or 0)
    if not ch_id:
        return
    ch = member.guild.get_channel(ch_id)
    if not ch:
        return
    perms = ch.permissions_for(member.guild.me)
    if not (perms.send_messages and perms.embed_links):
        return
    tpl = c.get('goodbye_message', '') or ''
    try:
        text = tpl.format(
            user=member.mention,
            user_name=member.display_name,
            guild=member.guild.name,
            count=member.guild.member_count or 0,
        )
    except Exception as ex:
        text = f"😢 {member.display_name} a quitté. _(erreur template: {ex})_"
    # Phase 83 : LayoutView V2 — section avec avatar en thumb accessory
    _gb_text = text
    _gb_avatar = member.display_avatar.url if member.display_avatar else None
    _gb_guild_line = f"{member.guild.name} · {member.guild.member_count or 0} membres"

    class _GoodbyeLayout(LayoutView):
        def __init__(self):
            super().__init__(timeout=None)
            items = [
                v2_title("😢 Au revoir"),
                v2_subtitle(_gb_guild_line),
                v2_divider(),
            ]
            # Section avec avatar en thumb accessory
            if _gb_avatar:
                items.append(v2_section(
                    v2_body(_gb_text),
                    accessory=v2_thumb(_gb_avatar),
                ))
            else:
                items.append(v2_body(_gb_text))
            self.add_item(v2_container(*items, color=0xED4245))

    try:
        await ch.send(view=_GoodbyeLayout())
    except Exception as ex:
        print(f"[goodbye send V2] {ex}")


# ═══════════════════════════════════════════════════════════════════════════════
#  Phase 26.1 : DÉTECTION DES BOOSTS NITRO
# ═══════════════════════════════════════════════════════════════════════════════

async def _audit_actor(guild, action, *, target_id=None, within_sec: int = 15):
    """« QUI a fait quoi à qui » (owner 2026-06-14) : retrouve l'AUTEUR d'une action via
    les AUDIT LOGS Discord. Renvoie (actor_user_or_None, reason_or_None).

    Les events gateway (on_member_update, on_guild_role_update…) ne disent PAS qui a agi
    → on lit l'entrée d'audit correspondante (action + cible + fenêtre temporelle récente).
    FAIL-SAFE : nécessite la perm « Voir les logs d'audit » ; sinon (None, None). N'appeler
    QUE quand un log va effectivement être émis (1 appel API audit par event loggé)."""
    try:
        me = guild.me
        if me is None or not me.guild_permissions.view_audit_log:
            return (None, None)
        cutoff = discord.utils.utcnow() - timedelta(seconds=within_sec)
        async for entry in guild.audit_logs(action=action, limit=6):
            try:
                if entry.created_at is not None and entry.created_at < cutoff:
                    break  # entrées triées récent→ancien : au-delà de la fenêtre = stop
                if target_id is not None:
                    tid = getattr(getattr(entry, 'target', None), 'id', None)
                    if tid is not None and int(tid) != int(target_id):
                        continue
                return (entry.user, getattr(entry, 'reason', None))
            except Exception:
                continue
    except discord.Forbidden:
        return (None, None)
    except Exception:
        return (None, None)
    return (None, None)


async def _log_audited(guild, event_type, actions, target_id, desc_fn, *,
                       channel=None, require_actor=False, user=None):
    """Loggue un event d'audit (création/suppression/permission/sanction) AVEC son AUTEUR
    (via _audit_actor) et en IGNORANT les actions AUTOMATIQUES du bot — sinon les logs sont
    NOYÉS par la création/suppression incessante des salons d'event (owner « pas de logs
    inutiles »). `actions` = une AuditLogAction ou une liste (essayées dans l'ordre).
    `desc_fn(actor)` -> description (si elle renvoie un faux → pas de log). L'auteur est
    passé en `moderator=` (rendu joli par le logger). `require_actor=True` → ne loggue QUE
    si un auteur a été trouvé (sert au KICK : sans entrée d'audit kick = simple départ
    volontaire → on ne loggue rien). FAIL-SAFE."""
    try:
        if not isinstance(actions, (list, tuple)):
            actions = [actions]
        actor, reason = (None, None)
        for _act in actions:
            actor, reason = await _audit_actor(guild, _act, target_id=target_id)
            if actor is not None:
                break
        if require_actor and actor is None:
            return  # pas d'auteur trouvé → événement non confirmé (ex. départ ≠ kick)
        me = guild.me
        if actor is not None and me is not None and actor.id == me.id:
            return  # action automatique du bot → pas de log (anti-spam)
        _desc = desc_fn(actor)
        if not _desc:
            return  # pas de description → pas de log (garde)
        await ulogger2026.log_event(
            bot, guild, event_type,
            description=_desc,
            user=user,                     # cible → champ « 👤 Concerné » (@mention cliquable)
            moderator=actor,
            reason=(str(reason)[:300] if reason else None),
            channel=channel,
        )
    except Exception as ex:
        print(f"[_log_audited {getattr(event_type, 'value', '?')}] {ex}")


@bot.event
async def on_member_update(before, after):
    """Détecte les changements pertinents : boost Nitro (Phase 26.1) +
    impersonation staff (Phase 147)."""
    try:
        # Boost détection : premium_since passe de None → not None
        if before.premium_since is None and after.premium_since is not None:
            await _handle_boost_started(after)
        # owner 2026-07-17 : ARRÊT de boost (premium_since était set → devient None) = « on descend »
        # → nudge GENTIL (throttle 1×/jour). Avant on ne faisait rien « pour éviter de spammer » :
        # le throttle quotidien lève cette réserve.
        elif before.premium_since is not None and after.premium_since is None:
            await _handle_boost_stopped(after)
    except Exception as ex:
        print(f"[on_member_update boost] {ex}")
    # owner 2026-06-30 : DÉGRADATION CRESCENDO — si un membre DÉJÀ restreint (check O(1)) gagne un
    # rôle / l'admin (potentiellement une immunité), on recalcule TOUT DE SUITE son palier au lieu
    # d'attendre le cycle 12 h → recompute détecte l'immunité et le libère (rôle + DB). FAIL-OPEN.
    try:
        if (not getattr(after, 'bot', False)
                and recidivism_module.tier_of(after.guild.id, after.id)
                and (set(before.roles) != set(after.roles)
                     or before.guild_permissions.administrator != after.guild_permissions.administrator)):
            asyncio.create_task(recidivism_module.recompute(after.guild, after))
    except Exception as ex:
        print(f"[on_member_update recidivism] {ex}")
    # Phase 147 : check impersonation sur changement de nick
    try:
        await impersonation_module.on_member_update_hook(before, after)
    except Exception as ex:
        print(f"[on_member_update impersonation] {ex}")

    # Surveillance profils (owner 2026-06-21) : si le NOM change → re-scan termes anti-TOS
    # (la dédup évite de re-alerter un terme déjà signalé). INFORMATIF, FAIL-SAFE.
    try:
        if (getattr(before, 'display_name', None) != getattr(after, 'display_name', None)
                or getattr(before, 'global_name', None) != getattr(after, 'global_name', None)
                or getattr(before, 'name', None) != getattr(after, 'name', None)):
            await _flag_dangerous_profile(after, on_join=False)
    except Exception as ex:
        print(f"[on_member_update profile scan] {ex}")

    # LOGS unifiés (quick-win pro) : changements de RÔLES et de PSEUDO — donnée d'audit
    # clé (« qui a donné le rôle Staff ? »). DANS ce handler existant (jamais un 2e
    # @bot.event). FAIL-SAFE : log_event no-op si logs non configurés / catégorie off.
    try:
        if not after.bot:
            default_role = after.guild.default_role
            bset, aset = set(before.roles), set(after.roles)
            added = [r for r in after.roles if r not in bset and r != default_role]
            removed = [r for r in before.roles if r not in aset and r != default_role]
            if added or removed:
                # QUI a donné/retiré le rôle ? (audit). Changement AUTOMATIQUE par le bot
                # (rôles d'event, auto-rôle, dé-impersonation…) = bruit → on NE loggue PAS.
                actor, reason = await _audit_actor(
                    after.guild, discord.AuditLogAction.member_role_update, target_id=after.id)
                _me = after.guild.me
                _is_bot = actor is not None and _me is not None and actor.id == _me.id
                # On loggue UNIQUEMENT si un AUTEUR HUMAIN est identifié : actor None (pas
                # d'audit / introuvable) OU bot automatique (rôles d'event, auto-rôle…) =
                # bruit → PAS de log. Évite le spam du backfill de rôles + le « inconnu ».
                if actor is None or _is_bot:
                    pass
                else:
                    parts = []
                    if added:
                        parts.append("➕ " + ", ".join(r.mention for r in added[:10]))
                    if removed:
                        parts.append("➖ " + ", ".join(r.mention for r in removed[:10]))
                    _extra = {"👤 Par": actor.mention}
                    if reason:
                        _extra["📝 Raison"] = str(reason)[:300]
                    await ulogger2026.log_event(
                        bot, after.guild, ulogger2026.EventType.MEMBER_UPDATE,
                        description=f"🎭 **{actor}** a modifié les rôles de {after.mention} :\n" + "\n".join(parts),
                        user=after, extra=_extra,
                    )
            if (before.nick or '') != (after.nick or ''):
                # Pseudo : on ne loggue QUE si c'est QUELQU'UN D'AUTRE (staff) qui l'a changé
                # — un membre qui change SON propre pseudo = bruit inutile (anti-spam owner).
                nactor, _nr = await _audit_actor(
                    after.guild, discord.AuditLogAction.member_update, target_id=after.id)
                _me = after.guild.me
                _is_bot = nactor is not None and _me is not None and nactor.id == _me.id
                _is_self = nactor is not None and nactor.id == after.id
                if nactor is not None and not _is_bot and not _is_self:
                    await ulogger2026.log_event(
                        bot, after.guild, ulogger2026.EventType.MEMBER_UPDATE,
                        description=(f"✏️ **{nactor}** a changé le pseudo de {after.mention} : "
                                     f"`{before.nick or before.name}` → `{after.nick or after.name}`"),
                        user=after, extra={"👤 Par": nactor.mention},
                    )
    except Exception as ex:
        print(f"[on_member_update log] {ex}")

    # ⏱️ TIMEOUT NATIF Discord (clic droit → « Exclure temporairement », owner 2026-06-21).
    # On détecte qu'un MODÉRATEUR a posé/retiré un timeout À LA MAIN (hors commandes du bot,
    # qui se loggent déjà via leur propre flux de sanction → on saute l'auteur = bot pour
    # éviter le double-log). On veut QUI / QUOI / QUAND / COMBIEN / SUR QUI, avec la personne
    # ET le modérateur en @mention cliquable (rendu par _format_user). Catégorie Modération
    # = « logs moyens ». FAIL-SAFE : sans perm audit → pas d'auteur → on ne loggue pas (plutôt
    # qu'un « inconnu » trompeur).
    try:
        if not after.bot:
            _bt = getattr(before, 'timed_out_until', None)
            _at = getattr(after, 'timed_out_until', None)
            if _bt != _at:
                _nowu = discord.utils.utcnow()
                _at_active = bool(_at and _at > _nowu)
                _bt_active = bool(_bt and _bt > _nowu)
                if _at_active:
                    # POSÉ ou PROLONGÉ → qui l'a fait, pourquoi, jusqu'à quand.
                    tactor, treason = await _audit_actor(
                        after.guild, discord.AuditLogAction.member_update, target_id=after.id)
                    _me = after.guild.me
                    if tactor is not None and not (_me is not None and tactor.id == _me.id):
                        _ts = int(_at.timestamp())
                        await ulogger2026.log_event(
                            bot, after.guild, ulogger2026.EventType.MOD_TIMEOUT,
                            description=(f"⏱️ **{tactor}** a exclu temporairement {after.mention} "
                                         f"jusqu'au <t:{_ts}:F> (<t:{_ts}:R>)."),
                            user=after, moderator=tactor,
                            reason=(str(treason)[:300] if treason else None),
                            extra={"⏳ Fin de l'exclusion": f"<t:{_ts}:F> · <t:{_ts}:R>"},
                        )
                elif _bt_active and not _at_active:
                    # RETIRÉ À LA MAIN avant son terme (un mod lève l'exclusion) → qui l'a levée.
                    uactor, ureason = await _audit_actor(
                        after.guild, discord.AuditLogAction.member_update, target_id=after.id)
                    _me = after.guild.me
                    if uactor is not None and not (_me is not None and uactor.id == _me.id):
                        await ulogger2026.log_event(
                            bot, after.guild, ulogger2026.EventType.MOD_UNMUTE,
                            description=(f"🔊 **{uactor}** a levé l'exclusion temporaire de "
                                         f"{after.mention} (avant son terme)."),
                            user=after, moderator=uactor,
                            reason=(str(ureason)[:300] if ureason else None),
                        )
    except Exception as ex:
        print(f"[on_member_update timeout] {ex}")


