async def _handle_antiraid_join(member):
    """Détecte les vagues d'arrivées et isole les comptes concernés.

    SEUL système anti-raid depuis 08/2026 : le précédent (clé `anti_raid` +
    `raid_config`) le neutralisait au lieu de le compléter — voir le commentaire
    en tête de `on_member_join`.

    Renvoie True si une action a été appliquée AU MEMBRE DÉCLENCHEUR, pour que
    l'appelant s'arrête et ne le sanctionne pas une seconde fois.

    Le compteur d'arrivées est incrémenté À CHAQUE APPEL, même hors raid : c'est
    lui qui permet de détecter la vague. Ne jamais sortir avant.
    """
    c = await cfg(member.guild.id)

    # ── Reprise de l'ancien système, une fois par serveur ────────────────────
    # Un serveur qui avait configuré l'anti-raid legacy verrait sinon sa protection
    # tomber en silence. On reprend ses réglages en gardant, pour chaque valeur, la
    # PLUS PROTECTRICE des deux (seuil le plus bas, fenêtre la plus large, âge de
    # compte le plus exigeant). On ne peut donc que renforcer, jamais affaiblir.
    if c.get('anti_raid') and not c.get('antiraid_enabled', False):
        legacy = c.get('raid_config', {}) or {}
        try:
            await db_set(member.guild.id, 'antiraid_join_threshold', min(
                int(c.get('antiraid_join_threshold', 5) or 5),
                int(legacy.get('join_threshold', 10) or 10)))
            await db_set(member.guild.id, 'antiraid_join_window_sec', max(
                int(c.get('antiraid_join_window_sec', 10) or 10),
                int(legacy.get('join_interval', 10) or 10)))
            await db_set(member.guild.id, 'antiraid_min_account_age_days', max(
                int(c.get('antiraid_min_account_age_days', 7) or 7),
                int(legacy.get('min_account_age', 7) or 7)))
            if not int(c.get('antiraid_log_channel', 0) or 0):
                await db_set(member.guild.id, 'antiraid_log_channel',
                             int(c.get('log_anti_raid', 0) or 0))
            await db_set(member.guild.id, 'antiraid_enabled', True)
            await db_set(member.guild.id, 'anti_raid', 0)
            print(f"[ANTIRAID] guild={member.guild.id} réglages legacy repris")
            c = await cfg(member.guild.id)
        except Exception as ex:
            print(f"[ANTIRAID migration] {ex}")

    if not c.get('antiraid_enabled', False):
        return False

    threshold = int(c.get('antiraid_join_threshold', 5))
    window = int(c.get('antiraid_join_window_sec', 10))
    min_age_days = int(c.get('antiraid_min_account_age_days', 7))
    action = str(c.get('antiraid_action', 'kick'))

    now_ts = time.time()
    joins = _recent_joins.setdefault(member.guild.id, [])
    # Purge anciens (garde uniquement les joins dans la fenêtre)
    cutoff = now_ts - window
    joins[:] = [entry for entry in joins if isinstance(entry, tuple) and entry[0] > cutoff]
    joins.append((now_ts, member.id))

    # Compte d'âge suspect ?
    account_age_days = (datetime.now(timezone.utc) - member.created_at).days
    is_suspect = account_age_days < min_age_days

    if len(joins) < threshold:
        return False  # Pas encore raid : le join est compté, rien à appliquer

    # ── Raid détecté ──
    print(f"[ANTIRAID] guild={member.guild.id} {len(joins)} joins en {window}s → RAID")

    # TASK C.1 : ouvre/prolonge la fenêtre de suppression des bienvenues
    # individuelles → un seul récap groupé sera posté en fin de vague.
    mark_welcome_raid(member.guild.id)

    # Récupérer les membres récents pour action
    recent_member_ids = [mid for (_, mid) in joins[-threshold:]]
    recent_members = []
    for mid in recent_member_ids:
        m = member.guild.get_member(mid)
        # IMMUNITÉ (audit 2026-06-21) : owner / super-owner / immunisés JAMAIS isolés pendant
        # un raid (aligne sur _kick_young_account ; sinon le super-owner rejoignant en plein
        # raid se faisait retirer ses rôles + timeout 28 j).
        if (m and not m.bot and m.id != member.guild.owner_id
                and not owner_ids_module.is_super_owner(m.id)
                and not await is_fully_immune(m)):
            recent_members.append(m)

    # Appliquer l'action
    applied = 0
    failed = 0
    for m in recent_members:
        try:
            if action in ('kick', 'ban'):
                # RÈGLE FONDATEUR-ONLY : raid → on ISOLE chaque compte (jamais kick/ban auto).
                await isolate_member(m, f"Anti-Raid auto : {len(joins)} joins en {window}s")
            elif action == 'lockdown':
                # Lockdown = élève verification level + auto-restore après 10 min
                try:
                    previous_level = member.guild.verification_level
                    await member.guild.edit(verification_level=discord.VerificationLevel.highest, reason="Anti-Raid lockdown")
                    # Schedule restoration
                    async def _restore_lockdown(guild, prev):
                        try:
                            await asyncio.sleep(600)  # 10 minutes
                            await guild.edit(verification_level=prev, reason="Anti-Raid lockdown terminé")
                            print(f"[ANTIRAID] guild={guild.id} lockdown restauré à {prev}")
                        except Exception as ex:
                            # CRITIQUE : si la restauration échoue, le serveur reste verrouillé.
                            _logerr("security.lockdown_restore", ex, guild_id=getattr(guild, "id", 0))
                    asyncio.create_task(_restore_lockdown(member.guild, previous_level))
                except Exception as ex:
                    _logerr("security.lockdown_set", ex, guild_id=getattr(member.guild, "id", 0))
                # Pas d'action sur le membre individuellement en lockdown mode
                break
            applied += 1
        except Exception as ex:
            print(f"[ANTIRAID action] {ex}")
            failed += 1

    # Journal unifié + casier. L'ancien système alimentait send_log('anti_raid'),
    # pas celui-ci : les raids n'apparaissaient donc ni dans le journal unifié ni
    # dans l'historique des membres. Capacité reprise ici.
    try:
        await send_log(
            member.guild, 'anti_raid', member, None,
            f"Raid détecté : {len(joins)} arrivées en {window}s",
            f"Action: {action.upper()} · {applied}/{len(recent_members)} membre(s)",
        )
    except Exception as ex:
        print(f"[ANTIRAID send_log] {ex}")

    # Log dans le salon dédié
    log_ch_id = int(c.get('antiraid_log_channel', 0) or 0)
    log_ch = member.guild.get_channel(log_ch_id) if log_ch_id else None
    if log_ch:
        try:
            e = discord.Embed(
                title="🚨 RAID DÉTECTÉ",
                description=(
                    f"**{len(joins)}** joins en `{window}`s (seuil : `{threshold}`)\n"
                    f"**Action** : `{action}` appliquée à `{applied}`/`{len(recent_members)}` membres"
                ),
                color=0xE74C3C,
                timestamp=datetime.now(timezone.utc),
            )
            e.add_field(name="🆕 Membres concernés", value="\n".join(f"• {m.mention} (`{m.id}`)" for m in recent_members[:10]) or "_aucun_", inline=False)
            if is_suspect:
                e.add_field(name="⚠️ Compte suspect", value=f"Le dernier compte a `{account_age_days}`j d'âge (seuil : `{min_age_days}`j)", inline=False)
            await log_ch.send(embed=e)
        except Exception as ex:
            print(f"[ANTIRAID log] {ex}")

    # Reset le tracker après action
    _recent_joins[member.guild.id] = []


def _welcome_quick_buttons(guild):
    """Boutons d'accueil LINK (Règlement · Rôles · Présente-toi · Support) — quick-win pro.
    Salons DÉTECTÉS par nom (zéro config requise) : un bouton n'apparaît que si son salon
    existe (dégradation propre). Boutons URL = persistants par nature (aucun dispatch →
    survivent aux reboots, pas de « Échec de l'interaction »)."""
    try:
        def find(*kw):
            for ch in guild.text_channels:
                n = (ch.name or '').lower()
                if any(k in n for k in kw):
                    return ch
            return None
        specs = [
            ("📜 Règlement", find('règlement', 'reglement', 'rules', 'règles', 'regles')),
            ("🎭 Rôles", find('rôle', 'role', 'roles')),
            ("👋 Présente-toi", find('présent', 'present', 'introduce', 'intro')),
            ("🎫 Support", find('support', 'ticket', 'aide', 'help')),
        ]
        btns = []
        for label, ch in specs:
            if ch:
                url = f"https://discord.com/channels/{guild.id}/{ch.id}"
                btns.append(discord.ui.Button(label=label, style=discord.ButtonStyle.link, url=url))
        v = discord.ui.View(timeout=None)
        for b in btns[:4]:   # max 4 liens → on laisse la place au bouton langue (≤5/rangée)
            v.add_item(b)
        # owner 2026-06-30 : INTERNATIONAL — bouton « 🌍 Ma langue » TOUJOURS présent à l'accueil
        # (custom_id onb_lang matché globalement par OnboardingView, enregistrée au boot). Le
        # nouveau membre choisit sa langue tout de suite. Bilingue.
        v.add_item(discord.ui.Button(label="🌍 Ma langue / My language",
                                     style=discord.ButtonStyle.secondary, custom_id="onb_lang"))
        return v
    except Exception:
        return None




async def _track_welcome_msg(guild_id: int, channel_id: int, message_id: int):
    """owner 2026-06-30 : enregistre une carte d'accueil pour la purge périodique (elle RESTE
    visible `welcome_lifetime_minutes` puis est supprimée → le chat ne s'encombre pas). FAIL-SAFE."""
    try:
        async with get_db() as db:
            await db.execute(
                "INSERT OR REPLACE INTO welcome_msgs(guild_id, channel_id, message_id) VALUES(?,?,?)",
                (int(guild_id), int(channel_id), int(message_id)))
            await db.commit()
    except Exception as ex:
        print(f"[_track_welcome_msg] {ex}")


@tasks.loop(minutes=10)
async def welcome_cleanup_task():
    """owner 2026-06-30 : « la carte reste pas mal de temps puis, toutes les heures, celles de
    tous les arrivants se suppriment ». On supprime les cartes d'accueil plus vieilles que
    `welcome_lifetime_minutes` (déf 60). get_partial_message → suppression SANS fetch (anti-429).
    Reboot-safe (table SQLite). FAIL-SAFE."""
    try:
        async with get_db() as db:
            async with db.execute(
                "SELECT guild_id, channel_id, message_id, "
                "CAST((julianday('now') - julianday(posted_at)) * 1440 AS INTEGER) AS age_min "
                "FROM welcome_msgs") as cur:
                rows = await cur.fetchall()
    except Exception:
        rows = []
    for gid, ch_id, msg_id, age_min in rows:
        try:
            c = await cfg(int(gid))
            life = int(c.get('welcome_lifetime_minutes', 60) or 60)
            if int(age_min or 0) < life:
                continue
            guild = bot.get_guild(int(gid))
            ch = guild.get_channel(int(ch_id)) if guild else None
            if ch is not None:
                try:
                    await ch.get_partial_message(int(msg_id)).delete()
                except discord.NotFound:
                    pass
                except Exception:
                    pass
            try:
                async with get_db() as db:
                    await db.execute(
                        "DELETE FROM welcome_msgs WHERE guild_id=? AND message_id=?",
                        (int(gid), int(msg_id)))
                    await db.commit()
            except Exception:
                pass
            await asyncio.sleep(0.3)   # throttle anti-429
        except Exception:
            continue


@welcome_cleanup_task.before_loop
async def _welcome_cleanup_before():
    await bot.wait_until_ready()


async def _handle_welcome(member):
    """Phase 28.3 — envoie le message de welcome."""
    c = await cfg(member.guild.id)
    if not c.get('welcome_enabled', False):
        return
    ch_id = int(c.get('welcome_channel', 0) or 0)
    if not ch_id:
        return
    ch = member.guild.get_channel(ch_id)
    if not ch:
        return
    perms = ch.permissions_for(member.guild.me)
    if not (perms.send_messages and perms.embed_links):
        return
    # TASK C.1 : pendant une vague de raid détectée, on NE poste PAS une bienvenue
    # par arrivée (anti-spam). On compte l'arrivée pour le récap groupé de fin de
    # vague. FAIL-SAFE : hors raid → comportement normal.
    if _defer_welcome_during_raid(member.guild.id, ch):
        return
    # I2 : langue d'accueil. Le membre vient d'arriver → pas encore de préférence,
    # donc lang_of retombe sur sa locale Discord puis la langue officielle du serveur,
    # puis FR. FAIL-SAFE total : toute erreur → "fr".
    try:
        _wlang = await i18n_module.lang_of(member.id, guild_id=member.guild.id)
    except Exception:
        _wlang = "fr"
    tpl = c.get('welcome_message', '') or ''
    fmt = dict(
        user=member.mention,
        user_name=member.display_name,
        guild=member.guild.name,
        count=member.guild.member_count or 0,
    )
    try:
        if tpl:
            # L'owner a configuré un message custom → il PRIME (on respecte sa rédaction).
            text = tpl.format(**fmt)
        else:
            # Aucun template configuré → ligne d'accueil par défaut DANS LA LANGUE.
            text = i18n_module.t("welcome.default_line", _wlang, **fmt)
    except Exception as ex:
        text = i18n_module.t("welcome.default_line", _wlang, **fmt) or \
            f"👋 Bienvenue {member.mention} ! _(erreur template: {ex})_"
    # TASK C.4 : accueil BILINGUE FR/EN. On NE casse PAS le FR existant : la ligne EN
    # est AJOUTÉE sous la ligne FR. Si la locale Discord du membre est anglophone, on
    # affiche EN en premier (plus naturel pour lui) ; sinon FR puis EN compact. Fail-safe :
    # toute erreur de template EN est ignorée → l'accueil FR part quand même.
    if (not c.get('welcome_compact', True)) and c.get('welcome_bilingual', True):
        tpl_en = (c.get('welcome_message_en', '') or '').strip()
        if tpl_en:
            try:
                text_en = tpl_en.format(**fmt)
            except Exception:
                text_en = ''
            if text_en:
                try:
                    loc = str(getattr(member, 'locale', '') or '').lower()
                except Exception:
                    loc = ''
                # Locale anglophone connue → EN d'abord (le membre est probablement EN).
                if loc.startswith('en'):
                    text = f"{text_en}\n-# {text}"
                else:
                    text = f"{text}\n-# {text_en}"
    # C4 : DÉCOUVRABILITÉ de l'entraide à l'accueil. Ligne FR+EN pointant vers le salon
    # d'entraide — UNIQUEMENT si l'entraide est CONFIGURÉE (sinon rien). Salon public
    # (zéro MP, aucune mention). _entraide_request_channel renvoie None si OFF/non réglé.
    try:
        _entr_ch = await _entraide_request_channel(member.guild)
        if _entr_ch is not None and not c.get('welcome_compact', True):
            # I2 : renvoi entraide DANS LA LANGUE du nouveau (repli FR). On garde le
            # 2e libellé EN compact pour rester compréhensible si la langue est exotique.
            _hint = i18n_module.t("welcome.entraide_hint", _wlang, channel=f"<#{_entr_ch.id}>")
            if _wlang != "en":
                _hint_en = i18n_module.t("welcome.entraide_hint", "en", channel=f"<#{_entr_ch.id}>")
                if _hint_en and _hint_en != _hint:
                    _hint = f"{_hint} · {_hint_en}"
            text += f"\n-# {_hint}"
    except Exception:
        pass
    # owner 2026-06-30 : encadrement MINIMAL — une seule ligne, PAS d'avatar (welcome_compact).
    e = discord.Embed(description=text, color=0x57F287)
    if not c.get('welcome_compact', True):
        e.set_author(name=f"👋 {i18n_module.t('welcome.author', _wlang)}",
                     icon_url=member.display_avatar.url)
    try:
        _wv = _welcome_quick_buttons(member.guild)
        if _wv is not None:
            _wm = await ch.send(content=member.mention, embed=e, view=_wv)
        else:
            _wm = await ch.send(content=member.mention, embed=e)
        # owner 2026-06-30 : PLUS d'auto-suppression 20 s — la carte RESTE visible, puis la purge
        # périodique (welcome_cleanup_task) la retire après `welcome_lifetime_minutes`. On l'enregistre.
        try:
            await _track_welcome_msg(member.guild.id, ch.id, getattr(_wm, 'id', 0))
        except Exception:
            pass
        print(f"[WELCOME] posté msg={getattr(_wm, 'id', 0)} ch={ch.id} guild={member.guild.id} "
              f"→ purge dans ~{int(c.get('welcome_lifetime_minutes', 60) or 60)} min")
    except Exception as ex:
        print(f"[welcome send] {ex}")


