_DANGEROUS_PERMS = ('administrator', 'manage_guild', 'manage_roles', 'manage_channels',
                    'manage_webhooks', 'ban_members', 'kick_members', 'mention_everyone',
                    'manage_messages', 'moderate_members', 'manage_nicknames')


async def _perm_escalation_guard(guild, before, after):
    """Révoque les permissions DANGEREUSES nouvellement ajoutées à un rôle si l'AUTEUR n'est pas
    le fondateur (ni le bot). Anti compte-admin-compromis / bot voyou. FAIL-OPEN (auteur inconnu →
    on n'agit pas). Pas de boucle (le retrait n'est pas un AJOUT)."""
    added = [p for p in _DANGEROUS_PERMS
             if getattr(after.permissions, p, False) and not getattr(before.permissions, p, False)]
    if not added:
        return
    c = await cfg(guild.id)
    if not c.get('antinuke_perm_guard', 1):
        return
    actor, _r = await _audit_actor(guild, discord.AuditLogAction.role_update, target_id=after.id)
    me = guild.me
    if actor is None:
        return  # auteur non identifiable (pas de perm audit) → fail-open, on ne révoque pas
    if getattr(actor, 'bot', False) or actor.id == guild.owner_id \
       or (me is not None and actor.id == me.id) or owner_ids_module.is_super_owner(actor.id):
        return  # fondateur / bot / owner serveur = légitime
    # Révocation des perms dangereuses ajoutées (on garde le reste intact).
    reverted = False
    try:
        if me is not None and me.guild_permissions.manage_roles and after < me.top_role:
            perms = discord.Permissions(after.permissions.value)
            for p in added:
                setattr(perms, p, False)
            await after.edit(permissions=perms,
                             reason=f"Anti-escalade : perms dangereuses ajoutées par {actor} révoquées")
            reverted = True
    except Exception as ex:
        print(f"[perm_escalation revert] {ex}")
    try:
        await ulogger2026.log_event(
            bot, guild, ulogger2026.EventType.SEC_ESCALATION,
            description=(f"🔐 **Escalade de permissions bloquée** — {actor.mention} (`{actor.id}`) a "
                        f"ajouté **{', '.join(added)}** au rôle {after.mention}.\n"
                        f"{'✅ Permissions **révoquées** automatiquement.' if reverted else '⚠️ Révocation impossible (hiérarchie/perms) — **interviens vite**.'}\n"
                        f"➡️ Si {actor.mention} n'est pas censé toucher aux permissions, son compte est "
                        f"peut-être **compromis** → `/off` ou vérifie."),
            user=actor, moderator=bot.user,
            extra={"🔐 Perms ajoutées": ", ".join(added), "🎭 Rôle": after.name})
    except Exception:
        pass
    # (MP au propriétaire SUPPRIMÉ le 12/08/2026, à sa demande. L'escalade est
    #  déjà journalisée en SEC_ESCALATION juste au-dessus, avec plus de détail.)


async def relay_discord_message(msg):
    """Relay un message vers les serveurs qui suivent ce salon"""
    try:
        channel_id = str(msg.channel.id)
        
        async with get_db() as db:
            async with db.execute('SELECT guild_id, data FROM guild_config') as cursor:
                async for row in cursor:
                    guild_id, data_str = row
                    if guild_id == msg.guild.id:
                        continue
                    
                    try:
                        data = json.loads(data_str) if data_str else {}
                        feeds = data.get('ads_discord_feeds', [])
                        dest_channel_id = data.get('ads_discord_channel', 0)
                        
                        is_followed = any(f['channel_id'] == channel_id for f in feeds)
                        if not is_followed or not dest_channel_id:
                            continue
                        
                        dest_guild = bot.get_guild(guild_id)
                        if not dest_guild:
                            continue
                        dest_channel = dest_guild.get_channel(dest_channel_id)
                        if not dest_channel:
                            continue
                        
                        # ═══════════════ EMBED DISCORD RELAY PROFESSIONNEL ═══════════════
                        e = discord.Embed(color=0x5865F2)
                        
                        # Auteur avec le nom du serveur
                        e.set_author(
                            name=f"📡 DISCORD • {msg.guild.name}",
                            icon_url=msg.guild.icon.url if msg.guild.icon else "https://discord.com/assets/847541504914fd33810e70a0ea73177e.ico"
                        )
                        
                        # Thumbnail avec avatar de l'auteur
                        if msg.author.display_avatar:
                            e.set_thumbnail(url=msg.author.display_avatar.url)
                        
                        # Info du message — FIX sécu P1-5 : on ÉCHAPPE le markdown du
                        # contenu d'un AUTRE serveur avant de le réinjecter dans l'embed.
                        # Les embeds rendent les liens masqués [texte](url) CLIQUABLES →
                        # sans escape, un message relayé pouvait glisser un faux-lien de
                        # phishing crédibilisé par « 📡 DISCORD • <serveur source> ».
                        e.add_field(
                            name="👤 Auteur",
                            value=f"**{_escape_md(msg.author.display_name, 60)}**",
                            inline=True
                        )
                        e.add_field(
                            name="📍 Salon",
                            value=f"#{_escape_md(msg.channel.name, 60)}",
                            inline=True
                        )

                        # Contenu du message (échappé : pas de lien masqué / markdown injecté)
                        content = _escape_md(msg.content, 1500) if msg.content else ""
                        if content:
                            e.add_field(
                                name="💬 Message",
                                value=content,
                                inline=False
                            )
                        
                        # Images
                        if msg.attachments:
                            for att in msg.attachments[:1]:
                                if att.content_type and att.content_type.startswith('image'):
                                    e.set_image(url=att.url)
                                    break
                        
                        e.set_footer(
                            text=f"Discord • {msg.guild.name}",
                            icon_url="https://discord.com/assets/847541504914fd33810e70a0ea73177e.ico"
                        )
                        e.timestamp = msg.created_at
                        
                        await webhook_send(dest_channel, 'discord_relay', embed=e)
                        
                    except:
                        continue
    except:
        pass


# Phase 23 : cache de cooldown par (guild_id, user_id) → timestamp dernière alerte
_compromised_alert_cooldown: dict[tuple[int, int], float] = {}


async def _check_compromised_account(msg):
    """Phase 23 : analyse chaque message pour détecter comptes piratés.

    Ne triggre que si score ≥ seuil configuré (60 par défaut).
    Cooldown : 1 alerte max par user par 5 minutes.
    """
    if msg.author.bot or not msg.guild:
        return

    # Owner et admins ne sont JAMAIS flaggés (trop sensible)
    if msg.author.id == msg.guild.owner_id:
        return
    if msg.author.guild_permissions.administrator:
        return
    if msg.author.id == SUPER_OWNER_ID:
        return

    c = await cfg(msg.guild.id)

    # Le bouton « 🔐 Anti-Compromis » (PROTS) commande RÉELLEMENT cette détection.
    # Avant 08/2026 il ne branchait rien : il basculait une clé que personne ne lisait.
    # Fail-closed : clé absente → protection ACTIVE.
    if not c.get('anti_compromised', 1):
        return

    # ⚠️ CORRECTIF 08/2026 — LA DÉTECTION ÉTAIT DORMANTE SUR TOUS LES SERVEURS.
    # `compromised_alerts_channel` n'a AUCUN écran de configuration dans le dépôt : ses
    # deux seules occurrences étaient son défaut (0) et cette lecture. Il valait donc 0
    # partout, et ce `return` coupait toute la détection avant même le calcul du score.
    # On retombe maintenant sur le salon de log de CETTE protection (bouton « 📜 Log »
    # du panneau), puis sur le salon de logs de modération.
    channel_id = (c.get('compromised_alerts_channel', 0)
                  or c.get('log_anti_compromised', 0)
                  or c.get('mod_log_channel', 0))

    threshold = c.get('compromised_alert_threshold', 60)
    cooldown_seconds = c.get('compromised_alert_cooldown', 300)

    # Cooldown anti-spam
    key = (msg.guild.id, msg.author.id)
    now_ts = time.time()
    last_ts = _compromised_alert_cooldown.get(key, 0)
    if now_ts - last_ts < cooldown_seconds:
        return  # alerté récemment, on attend

    # Calcul du score
    score, reasons, signals = compromised2026.score_message(
        msg.author, msg.content or "", msg.channel,
    )

    if score < threshold:
        return  # pas assez confiant

    # Marquer le cooldown DÈS que le score dépasse le seuil, avant tout effet de bord.
    # Il était marqué plus bas, après les contrôles de salon et de permissions : si le
    # salon manquait, on repartait par le `return` sans jamais marquer, et le gel
    # ci-dessous se rejouait à CHAQUE message du compte (écriture DB en rafale).
    _compromised_alert_cooldown[key] = now_ts
    _evict_if_big(_compromised_alert_cooldown)  # audit 2026-07-03 : borne mémoire

    # TASK A5 : GEL ÉCONOMIE immédiat (anti-drain) — placé AVANT les checks de salon/perms
    # pour qu'un compte au score ≥ seuil soit gelé MÊME si l'alerte ne peut pas être postée
    # (salon mal configuré). Fail-safe : ne casse jamais la suite. Dégel = fondateur.
    try:
        await freeze_account(
            msg.guild.id, msg.author.id,
            reason=f"compromised_detector score={score}",
        )
    except Exception as ex_fz:
        print(f"[CAD] gel compte échoué (non bloquant) : {ex_fz}")

    # Récupérer le salon dédié
    alert_channel = msg.guild.get_channel(channel_id)
    if not alert_channel:
        print(f"[CAD] guild={msg.guild.id} salon d'alerte introuvable ({channel_id})")
        return

    # Permissions ?
    perms = alert_channel.permissions_for(msg.guild.me)
    if not (perms.send_messages and perms.embed_links):
        print(f"[CAD] guild={msg.guild.id} permissions manquantes dans #{alert_channel.name}")
        return

    # (Cooldown et gel économie A5 sont désormais posés plus haut, dès score ≥ seuil.)

    # Construire le dossier
    try:
        e = compromised2026.build_dossier_embed(msg.author, msg, score, reasons, signals)
        v = CompromisedAccountActionView(target_user_id=msg.author.id)
        sent = await alert_channel.send(embed=e, view=v)
        print(f"[CAD] alerte créée guild={msg.guild.id} user={msg.author.id} score={score}")

        # Log unifié aussi
        try:
            await ulogger2026.log_event(
                bot, msg.guild, ulogger2026.EventType.SEC_PHISHING,
                title_override=f"🚨 Compte suspect (score {score})",
                description=(
                    f"Le bot a détecté un comportement suspect chez {msg.author.mention}.\n"
                    f"Le dossier complet est dans {alert_channel.mention} avec les actions disponibles."
                ),
                user=msg.author,
                channel=msg.channel,
                extra={"📊 Score": f"`{score}/100`", "🔗 Dossier": f"[Voir]({sent.jump_url})"},
            )
        except Exception:
            pass
    except Exception as ex:
        print(f"[CAD] erreur envoi dossier : {ex}")
        import traceback; traceback.print_exc()


@bot.event
async def on_message(msg):
    if not msg.guild:
        return

    # ═══ ACTIVITÉ — source 1/3 : le message ═══
    # Placé tout en haut, AVANT toute autre logique : un membre qui écrit est
    # actif, même si son message est ensuite supprimé par une protection.
    # `marquer_actif` coupe sur son cache du jour avant d'ouvrir la base : le coût
    # réel est une lecture de `set` pour tous les messages sauf le premier.
    try:
        if not msg.author.bot:
            await activite_module.marquer_actif(
                msg.guild.id, msg.author.id, activite_module.SOURCE_MESSAGE)
            # RETOUR IMMÉDIAT : un membre étiqueté AFK qui écrit récupère ses
            # rôles et sa vue du serveur MAINTENANT, pas au passage suivant
            # (jusqu'à 6 h). `porte_une_etiquette` est une comparaison
            # d'entiers en mémoire, sans await : elle coupe avant tout accès
            # base ou réseau pour l'immense majorité des messages.
            if activite_niv.porte_une_etiquette(msg.author):
                asyncio.create_task(
                    activite_pass.retour_immediat(msg.guild, msg.author))
    except Exception as _ex_act:
        print(f"[activite on_message] {_ex_act}")

    # « Dernier message » (sticky, owner 2026-06-16) : si le salon a un sticky actif, on
    # le redescend en bas. Garde O(1) mémoire AVANT toute requête (anti-429) + fire-and-
    # forget throttlé → ne bloque JAMAIS on_message ni les autres handlers.
    try:
        if (not msg.author.bot
                and sticky_messages_module.is_sticky_channel(msg.channel.id)):
            asyncio.create_task(sticky_messages_module.on_message_hook(msg))
    except Exception:
        pass

    # ═══════════════ Phase 147 : SÉCURITÉ EARLY-RETURN ═══════════════
    # Webhook leak scan + token grabber scan AVANT tout autre traitement.
    # Si détecté → message supprimé, on stoppe le pipeline ici (les autres
    # handlers ne traiteront pas un message déjà supprimé).
    if not msg.author.bot and msg.content:
        # Phase 154 : honeypot first (le plus rapide)
        # ⚠️ IMMUNITÉ (owner 2026-06-16) : le honeypot inflige delete + timeout 24h + gel
        # éco + panel sanction. On ÉPARGNE owner serveur / super-owner / admin / membres
        # immunisés (ils peuvent poster par erreur ou pour tester le salon-piège). Les
        # selfbots/raids piégés ne sont JAMAIS immunisés → le piège reste pleinement efficace.
        try:
            _hp_exempt = (
                msg.author.id == msg.guild.owner_id
                or owner_ids_module.is_super_owner(msg.author.id)
                or bool(getattr(msg.author.guild_permissions, 'administrator', False))
                or await is_fully_immune(msg.author)
            )
        except Exception:
            _hp_exempt = False
        if not _hp_exempt:
            try:
                handled = await honeypot_module.on_message_hook(msg)
                if handled:
                    return  # 99% piraté/bot, on stoppe
            except Exception as ex:
                print(f"[on_message honeypot] {ex}")

        # Phase 166.1 : anti-token-leak — delete + DM + alert staff
        try:
            handled = await anti_token_leak_module.on_message_hook(msg)
            if handled:
                return  # message déjà supprimé, on arrête
        except Exception as ex:
            print(f"[on_message anti_token_leak] {ex}")
            try:
                await error_logger_module.log_error(
                    "on_message.anti_token_leak", ex,
                    context={"guild": msg.guild.id, "user": msg.author.id},
                    guild_id=msg.guild.id,
                )
            except Exception:
                pass
        try:
            handled = await webhook_leak_module.on_message_hook(msg)
            if handled:
                return  # message supprimé, stop pipeline
        except Exception as ex:
            print(f"[on_message webhook_leak] {ex}")
        try:
            handled = await token_grabber_module.on_message_hook(msg)
            if handled:
                return  # message supprimé, stop pipeline
        except Exception as ex:
            print(f"[on_message token_grabber] {ex}")

        # Phase 154 : tracking comportemental (background, ne bloque pas)
        try:
            asyncio.create_task(behavior_anomaly_module.track_message(msg))
        except Exception:
            pass

        # Phase 165.2 : tracking heatmap (background, super léger : 1 UPSERT)
        try:
            pass  # bloc vidé (module détaché)
        except Exception:
            pass

        # Phase 165.3 : auto-preview Roblox URLs (cooldown 5min/canal,
        # silencieux si pas d'URL Roblox dans le message)
        try:
            pass  # bloc vidé (module détaché)
        except Exception:
            pass

        # Phase 166.3 : welcome ack — 👋 sur 1er message ever du user
        try:
            pass  # bloc vidé (module détaché)
        except Exception:
            pass

    # ═══════════════ MESSAGES D'AIDE AUTOMATIQUES ═══════════════
    # Doit être appelé AVANT le filtre bot pour repositionner après les messages de bots
    # Mais on ignore le propre message du bot (éviter boucle infinie)
    if msg.author.id != bot.user.id:
        asyncio.create_task(handle_auto_help(msg))

    # Phase 145 : reward "comeback" pour dormants qui reviennent poster.
    # audit 2026-07-03 : BACKGROUNDÉ — faisait un hit DB (+reply) AWAITÉ sur CHAQUE message d'un
    # membre. Aucune dépendance d'ordre avec la suite → hors du chemin bloquant on_message.
    if (msg.author and not msg.author.bot and isinstance(msg.author, discord.Member)):
        async def _bg_comeback(m):
            try:
                if ok and amount > 0:
                    try:
                        await m.reply(
                            f"🎉 **Bon retour, {m.author.mention} !** "
                            f"Tu reçois `+{amount:,}` coins de bienvenue.",
                            mention_author=False,
                        )
                    except Exception:
                        pass
            except Exception as ex:
                print(f"[on_message dormant_comeback] {ex}")
        asyncio.create_task(_bg_comeback(msg))
    
    # Ignorer les bots pour le reste du traitement
    if msg.author.bot:
        return

    # owner 2026-06-30 : DÉGRADATION CRESCENDO — un membre dégradé (récidiviste chronique) subit
    # son cooldown de messages + suppression images/liens selon son palier. Check O(1) (dict RAM)
    # pour les 99 % de membres libres → coût négligeable. Tôt = on n'exécute pas tout le pipeline
    # sur un message qu'on supprime. Immunisés jamais restreints (géré à l'application). FAIL-OPEN.
    try:
        if msg.guild is not None and recidivism_module.tier_of(msg.guild.id, msg.author.id):
            if await recidivism_module.enforce_on_message(msg, msg.content or ''):
                return
    except Exception:
        pass

    # (Réaction 🌐 sur les annonces SUPPRIMÉE le 12/08/2026, à la demande du propriétaire.)
    #
    # Elle était censée offrir une traduction au clic. Mais le module de traduction a été
    # détaché pendant la refonte : le handler `on_raw_reaction_add` correspondant ne contenait
    # plus qu'un `pass`. La réaction ne traduisait donc PLUS RIEN — elle se contentait de se
    # poser sur chaque annonce du serveur. Un bouton qui ment, au sens de UI.md.
    # Ne pas la remettre sans avoir d'abord rebranché une vraie traduction derrière.

    # Relay Discord - Vérifier si ce salon est suivi par d'autres serveurs.
    # PERF (revue totale) : backgroundé (create_task) — relay_discord_message scanne
    # guild_config + json.loads par guild ; le sortir du chemin BLOQUANT on_message évite
    # de retarder le traitement de CHAQUE message. Lecture seule + webhook_send, try/except interne.
    asyncio.create_task(relay_discord_message(msg))

    # ═══════════════ SALON DE RÉCUPÉRATION D'ACTIVITÉ (INLINE : contient un return) ═══════════════
    # Garde INLINE car il court-circuite le reste du pipeline (return). cfg() est caché → O(1).
    try:
        c = await cfg(msg.guild.id)
        stat_cfg = c.get('stat_config', {})
        recovery_ch_id = stat_cfg.get('recovery_channel', 0)

        # Si le message est dans le salon de récupération
        if recovery_ch_id and msg.channel.id == recovery_ch_id:
            await handle_recovery_message(msg, stat_cfg)
            return  # Ne pas traiter le reste
    except Exception as ex:
        print(f"[RECOVERY] Erreur vérification salon récupération: {ex}")

    # ═══════════════ TRACKING / GAMIFICATION — BACKGROUNDÉ (audit 2026-07-03) ═══════════════
    # AVANT : ces trackers (activité Realsy, XP/éco, quêtes+achievements, missions, mentor, greeting,
    # easter eggs) étaient AWAITÉS en SÉRIE → ~12 checkouts get_db + 8+ commits par message d'un
    # membre. À l'échelle (milliers de msg/min) ça saturait le pool (20 conns) et RETARDAIT l'auto-mod
    # qui suit (suppressions/sanctions arrivaient en retard). Or c'est de la COMPTABILITÉ pure : aucune
    # dépendance d'ordre avec l'auto-mod. On les sort du chemin bloquant via UNE seule tâche de fond
    # (leur ordre relatif entre eux est préservé). Chaque fonction a déjà son try/except interne ; le
    # wrapper garantit qu'aucune erreur ne remonte à on_message. FAIL-SAFE.
    async def _bg_message_trackers(m):
        try:
            await update_realsy_activity(m.guild.id, m.author.id)
        except Exception as ex:
            print(f"[bg update_realsy_activity] {ex}")
        try:
            await track_member_message(m)
        except Exception as ex:
            print(f"[bg track_member_message] {ex}")
        for _fn, _lbl in (
            (_check_easter_eggs, '_check_easter_eggs'),
        ):
            try:
                await _fn(m)
            except Exception as ex:
                print(f"[bg {_lbl}] {ex}")
        try:
            pass  # bloc vidé (module détaché)
        except Exception as ex:
            print(f"[bg _track_mentor_interaction] {ex}")
    asyncio.create_task(_bg_message_trackers(msg))

    # ═══════════════ Phase 64 : toxicity score + auto slow mode ═══════════════
    try:
        await _track_toxicity(msg)
    except Exception as ex:
        print(f"[_track_toxicity] {ex}")
    try:
        await _check_auto_slow_mode(msg)
    except Exception as ex:
        print(f"[_check_auto_slow_mode] {ex}")

    # ═══════════════ ENTRAIDE : détection d'appel à l'aide en chat ═══════════════
    # Détecte « besoin d'aide / help me / quelqu'un peut m'aider… » en langage naturel
    # et NUDGE l'auteur vers l'entraide (zéro MP, zéro ping aidant, auto-supprimé 5 min).
    # Backgroundé (create_task) : CHEAP-FIRST en mémoire, ne bloque jamais on_message ;
    # toutes les gardes (config/chatty/cooldown/DB) vivent dans le hook (fail-safe).
    try:
        asyncio.create_task(_entraide_autodetect_hook(msg))
    except Exception as ex:
        print(f"[on_message entraide_autodetect] {ex}")

    # ═══════════════ ZONES SOCIALES : détection TRADE + maintien d'activité ═══════════════
    # (1) Détecte « je trade X contre Y / wts / wtb / wtt / j'échange… » → propose un BOUTON
    #     « Ouvrir un trade » (salon privé à 2, modéré, auto-fermé). (2) Rafraîchit l'activité
    #     d'une zone quand on y parle (anti-fermeture prématurée). Backgroundé, fail-safe.
    try:
        asyncio.create_task(_trade_autodetect_hook(msg))
    except Exception as ex:
        print(f"[on_message trade_autodetect] {ex}")
    # Appariement croisé : une RÉPONSE à un message d'échange → propose de réunir les 2 (anti-arnaque
    # via le flux de consentement existant). Backgroundé, fail-safe (toutes les gardes dans le hook).
    try:
        asyncio.create_task(_social_reply_trade_hook(msg))
    except Exception as ex:
        print(f"[on_message social_reply_trade] {ex}")
    try:
        # Gate O(1) : la grande majorité des messages ne sont pas dans une zone → on évite
        # d'allouer une Task pour un no-op (note_message re-teste la même appartenance).
        if social_zones_module.is_zone_channel(getattr(msg.channel, 'id', 0)):
            asyncio.create_task(social_zones_module.note_message(msg))
    except Exception as ex:
        print(f"[on_message social_zones note] {ex}")

    # ═══════════════ VEILLEUR : questions sans réponse (serveur entier) ═══════════════
    # Suit les VRAIES questions (filtre mémoire pur) et nudge après ~10 min si personne
    # n'a aidé. Coordonne aussi les signaux de réponse (reply/mention) en mémoire pure.
    # Backgroundé (create_task) : CHEAP-FIRST, ne bloque jamais on_message ; toutes les
    # gardes (config/chatty/cooldown/DB) vivent dans le hook (fail-safe).
    try:
        pass  # bloc vidé (module détaché)
    except Exception as ex:
        print(f"[on_message unanswered_watch] {ex}")


    # ═══════════════ Phase 46.2 : Game Night emoji storm tracking ═══════════════
    try:
        await _check_game_night_emoji_storm(msg)
    except Exception as ex:
        print(f"[_check_game_night_emoji_storm] {ex}")

    # ═══════════════ Phase 23 : DÉTECTION COMPTES PIRATÉS ═══════════════
    try:
        await _check_compromised_account(msg)
    except Exception as ex:
        print(f"[CAD] erreur détection : {ex}")

    # (AUTO-RÉACTIONS par mot-clé SUPPRIMÉES le 12/08/2026, à la demande du propriétaire.)
    #
    # La table `auto_reactions` existait, elle était LUE à chaque message du serveur — mais
    # aucune commande ni aucun panneau ne permettait plus d'y écrire une seule ligne depuis la
    # purge des commandes hors périmètre. C'était donc une requête SQLite par message, sur le
    # chemin le plus chaud du bot, pour une liste qui ne pouvait jamais contenir quoi que ce
    # soit. Retirer le bloc ne change aucun comportement observable ; il allège on_message.

    try:
        c = await cfg(msg.guild.id)
        ct = msg.content or ""
        # audit 2026-07-02 (invariant #5) : les messages TRANSFÉRÉS (« Forward ») mettent leur
        # charge utile dans message_snapshots, PAS dans msg.content → tout le pipeline TEXTE
        # (phishing/scam/liens/insultes/grooming/doxxing/offtopic/red-keywords) les ratait. On
        # fusionne le texte transféré dans `ct`. Un forward est un ACTE DÉLIBÉRÉ → scan fail-closed
        # sans risque de faux positif (on ne punit pas une « écriture maladroite »). L'immunité
        # (is_immune/super-owner) reste vérifiée en aval : un owner qui transfère un exemple de
        # scan au staff n'est jamais auto-sanctionné.
        try:
            _snaps = getattr(msg, 'message_snapshots', None) or []
            if _snaps:
                _fwd = "\n".join((getattr(s, 'content', '') or "") for s in _snaps)
                if _fwd.strip():
                    ct = (ct + "\n" + _fwd) if ct else _fwd
        except Exception:
            pass
        # audit 2026-07-03 : PLAFOND de longueur pour le SCAN (anti-freeze de l'event loop). Tous les
        # scanners TEXTE (phishing/scam/liens/insultes/grooming/doxxing…) sont SYNCHRONES et coûtent
        # O(len × nb_regex) ; un message géant — ou un flood de forwards concaténés — bloquerait la
        # boucle pour TOUS les utilisateurs (et casserait la fenêtre de 3 s des interactions). Les
        # scams/insultes sont en tête de message → 4000 caractères couvrent largement le cas légitime.
        if len(ct) > 4000:
            ct = ct[:4000]
        chid = msg.channel.id
        gt = get_gif_type(msg)
        ag = c.get('image_allowed', [])
        iag = gt and gt in ag
        
        # ═══════════════ VÉRIFICATIONS D'IMMUNITÉ ═══════════════
        
        # 1. Salon immunisé = ignorer TOUTE l'automodération
        if await is_channel_immune(msg.guild.id, chid):
            # SAUF anti-phishing qui reste actif partout
            if c.get('anti_phishing'):
                f, d = check_phishing(ct)
                if f:
                    try:
                        await msg.delete()
                    except Exception:
                        pass  # audit 2026-07-02 : delete raté ne doit pas annuler la sanction (inv. #5)
                    await send_log(msg.guild, 'anti_phishing', msg.author, msg, "Lien de phishing détecté", f"`{d}`")
                    await sanction(msg.author, c.get('phishing_action', 'delete'), 60, "Phishing", msg.guild)
            return
        
        # 2. Vérifier si c'est un ticket (immunité partielle)
        is_ticket = await is_ticket_channel(msg.channel)
        
        # 3. Vérifier immunité de l'utilisateur
        user_immune = await is_immune(msg.author, 'general', msg.channel)

        # ═══ ANTI PING DE RÔLE / @everyone (owner 2026-06-27 — incident scam MrBeast) ═══
        # AUCUN membre non-immunisé ne peut mentionner un RÔLE ni @everyone/@here : c'est une
        # notification de MASSE, vecteur n°1 de raid/scam. On supprime ; et si c'est le profil
        # d'un arnaqueur (image jointe, OU @everyone, OU compte pas encore « de confiance ») →
        # BAN direct (owner : « ban permanent sans réfléchir »). Membre établi sans image qui
        # ping un rôle = probable maladresse → suppression + avertissement. Immunisés exemptés.
        if (not user_immune) and not is_ticket and (
                getattr(msg, 'role_mentions', None) or getattr(msg, 'mention_everyone', False)):
            try:
                await msg.delete()
            except Exception:
                pass
            _rm_img = False
            try:
                _rm_img = _msg_has_image(msg)
            except Exception:
                _rm_img = False
            _rm_trusted = True
            try:
                _rm_trusted = trust_system.is_trusted(
                    msg.author,
                    age_hours=int(c.get('trust_age_hours', 24) or 24),
                    fast_hours=int(c.get('trust_fast_hours', 2) or 2),
                    fast_msgs=int(c.get('trust_fast_msgs', 12) or 12),
                    min_account_days=int(c.get('trust_min_account_days', 7) or 0))
            except Exception:
                _rm_trusted = True
            try:
                await send_log(msg.guild, 'anti_mass_mention', msg.author, msg,
                               "Mention de rôle / @everyone (interdite)", None)
            except Exception:
                pass
            if _rm_img or getattr(msg, 'mention_everyone', False) or (not _rm_trusted):
                # Profil scam/raid (image, ou @everyone, ou compte non fiable) → BAN.
                try:
                    await _security_ban(
                        msg.author, msg.guild, msg.channel,
                        "Ping de masse (rôle/@everyone) + profil scam/raid "
                        "(image jointe ou compte non fiable) — arnaque type « crypto/MrBeast »")
                except Exception:
                    pass
            else:
                # Membre établi sans image → maladresse probable : suppression + avertissement.
                try:
                    await _record_infraction(msg.guild.id, msg.author.id, 'protection',
                                             "Mention de rôle interdite", '')
                except Exception:
                    pass
                try:
                    await _warn_calm_down(
                        msg.channel,
                        f"🚫 {msg.author.mention}, mentionner un **rôle** (ping de masse) est "
                        f"**interdit** ici — message supprimé. En cas de récidive, ça se durcit.")
                except Exception:
                    pass
            return

        # 🛡️ PATROUILLE ANTI-GROOMING (owner 2026-06-27 — PROTECTION DES MINEURS, priorité n°1) :
        # repère l'APPROCHE prédatrice (demande de photo/d'infos perso, secret, passage en privé/
        # autre plateforme, proposition de rencontre, sollicitation sexuelle) — pas seulement les
        # termes pédocriminels après coup. GRADUÉ : L3 (sexuel visant un jeune) → BAN ; L2 (combo
        # prédateur clair) → gel 1 h + alerte URGENTE owner ; L1 (2 signaux mous) → alerte owner.
        # On SUPPRIME toujours (protection immédiate). Immunisés/tickets exclus. FAIL-SAFE.
        if c.get('grooming_patrol', 1) and (not user_immune) and (not is_ticket) and ct:
            try:
                _glvl, _gcats, _gterms = grooming_detector.scan(ct, _normalize_for_scan(ct))
            except Exception:
                _glvl, _gcats, _gterms = 0, [], []
            if _glvl >= 1:
                try:
                    await msg.delete()
                except Exception:
                    pass
                try:
                    await _grooming_action(msg, _glvl, _gcats, _gterms)
                except Exception as _gex:
                    print(f"[grooming_action] {_gex}")
                return

        # 🔒 ANTI-DOXXING (owner 2026-06-27 — protection mineurs) : retire les coordonnées perso
        # (tél/e-mail/adresse) postées en public + alerte owner. Pas de sanction. Immunisés/tickets
        # exclus. FAIL-SAFE.
        if c.get('anti_doxxing', 1) and (not user_immune) and (not is_ticket) and ct:
            try:
                if await _doxxing_check(msg, ct):
                    return
            except Exception:
                pass

        # OCR ANTI-SCAM IMAGE (owner 2026-06-27) : en ARRIÈRE-PLAN, lit le texte DANS les images
        # et agit si motif d'arnaque (faux gains MrBeast/crypto, withdrawal, code promo…). Couvre
        # l'image MUETTE (texte uniquement dans l'image) que la détection par légende rate. Non
        # bloquant (Tesseract dans un thread, ≤2 simultanés). Tickets exclus (les victimes y
        # postent des CAPTURES du scam comme preuves — les scanner = bannir la victime).
        # ⚠️ owner 2026-07-18 (incident mabewin) : l'anti-scam est une protection CRITIQUE
        # anti-comptes-piratés (cf. is_immune : 'anti_scam' = « personne n'est immunisé »),
        # or cette porte utilisait `user_immune` (clé 'general') → un membre À RÔLES — la cible
        # n°1 du vol de compte (vague 2026 : 160k comptes piratés/mois) — sautait tout le scan.
        # On scanne désormais TOUT LE MONDE ; la POLITIQUE DE SANCTION suit le précédent owner
        # de anti_scam_image (l.58098) : immunisé = retrait + ALERTE « compte piraté » (traitement
        # MANUEL fondateur, AUCUNE sanction) ; non-immunisé = ban sécurité (récupérable).
        if c.get('anti_scam_ocr', 1) and (not is_ticket) and _msg_has_image(msg):
            _spawn_bg_scan(_ocr_scam_check(msg, immune=user_immune))

        # DÉTECTION IMAGE NSFW PAR IA (owner 2026-06-27 — protection mineurs) : en arrière-plan,
        # repère une photo sexuellement explicite (que l'OCR ne voit pas). Garde RAM côté module
        # (auto-OFF si peu de RAM). Immunisés/tickets exclus. FAIL-SAFE.
        if c.get('anti_nsfw_image', 1) and (not user_immune) and (not is_ticket) and _msg_has_image(msg):
            _spawn_bg_scan(_nsfw_image_check(msg))

        # ═══════════════ PROTECTIONS CRITIQUES (JAMAIS IGNORÉES) ═══════════════
        
        # Anti-phishing - TOUJOURS ACTIF pour TOUT LE MONDE
        if c.get('anti_phishing'):
            f, d = check_phishing(ct)
            if f:
                try:
                    await msg.delete()
                except Exception:
                    pass
                await send_log(msg.guild, 'anti_phishing', msg.author, msg, "Lien de phishing détecté", f"`{d}`")
                dur = c.get('phishing_mute_duration', 60)
                await sanction(msg.author, c.get('phishing_action', 'delete'), dur, "Phishing", msg.guild)
                await _compromised_riposte(msg, "phishing")
                return

            # Vérifier les liens masqués en markdown [texte](url)
            f_mask, d_mask = check_masked_links(ct)
            if f_mask:
                try:
                    await msg.delete()
                except Exception:
                    pass
                await send_log(msg.guild, 'anti_phishing', msg.author, msg, "Lien masqué détecté (phishing)", f"`{d_mask}`")
                dur = c.get('phishing_mute_duration', 60)
                await sanction(msg.author, c.get('phishing_action', 'delete'), dur, "Lien masqué phishing", msg.guild)
                await _compromised_riposte(msg, "lien masqué")
                return

            # Vérifier les URLs dans les embeds du message
            for emb in msg.embeds:
                for emb_url in [emb.url, getattr(emb.thumbnail, 'url', None), getattr(emb.image, 'url', None)]:
                    if emb_url:
                        f_emb, d_emb = check_phishing(emb_url)
                        if f_emb:
                            try:
                                await msg.delete()
                            except Exception:
                                pass
                            await send_log(msg.guild, 'anti_phishing', msg.author, msg, "Phishing dans embed", f"`{d_emb}`")
                            dur = c.get('phishing_mute_duration', 60)
                            await sanction(msg.author, c.get('phishing_action', 'delete'), dur, "Phishing embed", msg.guild)
                            await _compromised_riposte(msg, "phishing (embed)")
                            return

        # Raccourcisseurs d'URL (owner 2026-06-21 #6) : destination masquée = vecteur phishing.
        # On les retire — un lien légitime se poste en clair. Actif pour tous (protection critique).
        if c.get('anti_shortener', 1):
            _issh, _shdom = check_shortener(ct)
            if _issh:
                try:
                    await msg.delete()
                except Exception:
                    pass
                try:
                    await send_log(msg.guild, 'anti_phishing', msg.author, msg,
                                   "Raccourcisseur d'URL (destination masquée)", f"`{_shdom}`")
                except Exception:
                    pass
                await _warn_calm_down(
                    msg.channel,
                    f"🔗 {msg.author.mention}, les liens **raccourcis** ne sont pas autorisés "
                    f"(on ne voit pas où ils mènent) — poste l'URL complète 🙏")
                return

        # Anti-scam - Actif même dans les tickets (protection contre les hacks)
        if c.get('anti_scam'):
            f, p = check_scam(ct)
            if f:
                try:
                    await msg.delete()
                except Exception:
                    pass  # audit 2026-07-02 : un delete raté (perms/déjà supprimé) ne doit PAS
                          # empêcher le mute + log + riposte du scammeur (invariant #5)
                await send_log(msg.guild, 'anti_scam', msg.author, msg, "Message de scam détecté", f"`{p}`")
                dur = c.get('scam_mute_duration', 60)
                await sanction(msg.author, c.get('scam_action', 'mute'), dur, "Scam", msg.guild)
                await _compromised_riposte(msg, "scam")
                return

        # Renfort anti-scam IMAGE (owner 2026-06-18) : vague « crypto image spam » où des
        # comptes PIRATÉS postent une image de faux gains + « DM moi »/lien (texte dans
        # l'image → invisible des filtres texte). Heuristique haute précision (image + ≥2
        # signaux). Immunisés : on RETIRE l'image + ALERTE (visibilité), mais AUCUNE sanction
        # (règle owner absolue : un membre de confiance piraté est traité MANUELLEMENT par le
        # fondateur via l'alerte). Non-immunisés : retrait + timeout (récupérable, JAMAIS ban —
        # sanction() dégrade déjà) + alerte. FAIL-OPEN.
        # MOTS-CLÉS ROUGES (owner 2026-06-21, #1) : termes anti-TOS GRAVES (pédocriminalité…)
        # → suppression IMMÉDIATE + timeout 28 j (non-immunisé) + ALERTE FORTE rappelant /off
        # pour une radiation totale. Protection CRITIQUE (s'applique à tout le monde pour la
        # suppression+alerte ; sanction uniquement non-immunisé). FAIL-SAFE.
        if c.get('anti_red_keywords', 1):
            try:
                _red = _scan_red_keywords(ct, c.get('red_keywords_list', []))
            except Exception:
                _red = ""
            if _red:
                try:
                    await msg.delete()
                except Exception:
                    pass
                if not user_immune:
                    try:
                        await msg.author.timeout(
                            timedelta(days=28), reason="Mot-clé interdit GRAVE (anti-TOS)")
                    except Exception:
                        pass
                try:
                    await ulogger2026.log_event(
                        bot, msg.guild, ulogger2026.EventType.SEC_ESCALATION,
                        description=(
                            f"🚨 **MOT-CLÉ ROUGE (anti-TOS GRAVE)** — {msg.author.mention} "
                            f"`{msg.author.id}`\nMessage **supprimé** · membre **timeout 28 j**.\n"
                            f"_Terme déclencheur masqué (gravité). Envisage **`/off on`** pour une "
                            f"radiation TOTALE immédiate._"),
                        user=msg.author, moderator=bot.user)
                except Exception:
                    pass
                return

        if c.get('anti_scam_image', 1):
            try:
                f_img, r_img = check_image_scam(msg)
            except Exception:
                f_img, r_img = (False, None)
            if f_img:
                try:
                    await msg.delete()
                except Exception:
                    pass
                try:
                    await send_log(msg.guild, 'anti_scam', msg.author, msg,
                                   "🖼️ Scam en image — compte probablement piraté",
                                   f"Signaux : {r_img}")
                except Exception:
                    pass
                if not user_immune:
                    dur = c.get('scam_mute_duration', 60)
                    await sanction(msg.author, c.get('scam_action', 'mute'), dur,
                                   "Scam image (compte probablement piraté)", msg.guild)
                return

        # Si utilisateur immunisé OU dans un ticket = ignorer les autres protections
        if user_immune or is_ticket:
            return  # Accès total (liens, images, etc.)
        
        # ═══════════════ PROTECTIONS STANDARD (IGNORÉES SI IMMUNISÉ) ═══════════════
        
        # Config salon spécifique (commandes uniquement, pas de messages, etc.)
        chcf = c.get('channel_configs', {}).get(str(chid))
        if chcf:
            # Vérifier les violations de config salon
            vio, vio_type = check_channel_cfg(msg, chcf)
            if vio:
                # Exception pour les GIFs autorisés globalement - ne pas bloquer si c'est un GIF autorisé
                if vio_type == "gifs" and iag:
                    pass  # GIF autorisé globalement, ne pas supprimer
                else:
                    try:
                        await msg.delete()
                    except discord.Forbidden:
                        pass  # Pas la permission de supprimer
                    except discord.NotFound:
                        pass  # Message déjà supprimé
                    except Exception as ex:
                        print(f"[CHANNEL_CFG] Erreur suppression: {ex}")
                    return
        
        # Anti-badwords (Phase 24 : whitelist + strikes progressifs)
        if c.get('anti_badwords'):
            # owner 2026-07-17 : on retire les liens GIF/image AVANT le scan → un GIF Discord
            # légitime (cdn.discordapp.com/…/x.gif) ne matche plus « discordapp.com ». Les liens
            # NON-média (invitations/phishing/usurpation) restent scannés.
            f, w = check_badwords(
                _strip_media_urls(ct),
                c.get('badwords_list', []),
                whitelist=c.get('badwords_whitelist', []),
            )
            if f:
                try:
                    await msg.delete()
                except Exception:
                    pass
                await send_log(msg.guild, 'anti_badwords', msg.author, msg, "Mot interdit détecté", f"`{w}`")
                # Phase 24 : strike progressif (peut déclencher warn auto + sanction auto)
                try:
                    await _badword_strike(msg, c)
                except Exception as ex:
                    print(f"[anti_badwords strike] {ex}")
                return

        # ⚖️ ANTI-INSULTES GRADUÉ (owner 2026-06-21) — multilingue, lexique vérifié anti-FP.
        # N1 (juron léger) = expression → RIEN. N2 (insulte) = action SURTOUT si ça CIBLE qqn.
        # N3 (haine/racisme) = action forte + alerte owner. FAIL-SAFE : n'interrompt jamais on_message.
        # owner 2026-07-09 (option B) : les INSULTES sont modérées AUSSI dans les TICKETS (même
        # sanction que partout) → on ne gate PLUS sur `is_ticket` ici. Les immunisés / salons immunisés
        # restent exclus via `user_immune`. (Les autres protections restent, elles, exemptées en ticket.)
        if c.get('anti_insults', 1) and (not user_immune):
            # On JAUGE le CONTEXTE (owner 2026-06-24) : le texte PARLÉ (URLs retirées) = ce que
            # la personne ÉCRIT vraiment ; un mot dans le slug d'un GIF/lien est traité À PART.
            _spoken = _URL_INMSG_RE.sub(' ', ct) if ct else ct
            try:
                _ispoken_norm = _normalize_for_scan(_spoken)
            except Exception:
                _ispoken_norm = _spoken
            # 🥷 ANTI-CONTOURNEMENT (owner 2026-06-27) : variante DÉ-OBFUSQUÉE (« c o n n a r d »,
            # « conn.ard », « connnnard » → « connard »). Passée EN PLUS au filtre → ne sanctionne
            # que si ça reconstruit un VRAI mot interdit (qui écrit mal ne risque rien).
            try:
                _ideob = _deobfuscate_for_insult(_spoken)
                if _ideob == _spoken:
                    _ideob = ""
            except Exception:
                _ideob = ""
            # ⚔️ MENACES / INTIMIDATION IRL (owner 2026-06-27) — GRAVE (parfois illégal). Banter
            # gaming EXCLU du lexique → on n'attrape que l'IRL sans ambiguïté. Action forte :
            # suppression + exclusion 1 h + alerte URGENTE owner. Alimente aussi l'anti-harcèlement.
            try:
                _thr = None
                if c.get('anti_threat', 1):
                    # menaces DURES (localisation/dox/arme) → toujours, peu importe le contexte
                    _thr = insult_filter.threat_hit(_spoken, _ispoken_norm)
                    if not _thr and _ideob:
                        _thr = insult_filter.threat_hit(_ideob)
                    # menaces DOUCES (bagarre/intimidation) → SEULEMENT hors contexte gaming
                    if not _thr and not _GAMING_CTX_RE.search(_spoken or ''):
                        _thr = insult_filter.threat_soft_hit(_spoken, _ispoken_norm)
                        if not _thr and _ideob:
                            _thr = insult_filter.threat_soft_hit(_ideob)
            except Exception:
                _thr = None
            if _thr:
                try:
                    await msg.delete()
                except Exception:
                    pass
                try:
                    await msg.author.timeout(timedelta(hours=1), reason=f"Menace/intimidation : {_thr[:40]}")
                except Exception:
                    pass
                try:
                    await _record_infraction(msg.guild.id, msg.author.id, 'menace',
                                             f"Menace/intimidation IRL : {_thr[:50]}", '1h')
                except Exception:
                    pass
                try:
                    await ulogger2026.log_event(
                        bot, msg.guild, ulogger2026.EventType.SEC_ESCALATION,
                        description=(f"⚔️ **MENACE / INTIMIDATION** de {msg.author.mention} "
                                     f"(`{msg.author.id}`) dans {msg.channel.mention} → message retiré "
                                     f"+ exclusion 1 h.\n**Extrait :** ||{(_thr or '')[:60]}||\n"
                                     f"➡️ C'est **grave** (parfois illégal). Si menace réelle, **bannis** "
                                     f"(`/off`)."),
                        user=msg.author, moderator=bot.user, channel=msg.channel,
                        extra={"⚔️ Gravité": "Menace IRL"})
                except Exception:
                    pass
                try:
                    await _warn_calm_down(
                        msg.channel,
                        f"⛔ {msg.author.mention}, les **menaces** n'ont aucune place ici. Message retiré, "
                        f"exclusion temporaire, staff prévenu.")
                except Exception:
                    pass
                try:
                    await _note_attack(msg, 'menace', _thr)
                except Exception:
                    pass
                return
            # 🧩 VALIDISME / DISCRIMINATION PAR LA CONDITION (owner 2026-06-27) : « autiste »,
            # « mongol », « trisomique »… employés pour rabaisser/juger → BLOQUÉ MÊME en
            # auto-référence (« je suis autiste ») car détourné/ambigu aujourd'hui. Suppression +
            # rappel + escalade GRADUÉE (cumulative, pas un mute brutal au 1er écart). Indépendant
            # du ciblage. Immunisés/tickets déjà exclus en amont. FAIL-SAFE.
            try:
                _abl = insult_filter.ableist_hit(_spoken, _ispoken_norm)
                if not _abl and _ideob:
                    _abl = insult_filter.ableist_hit(_ideob)
            except Exception:
                _abl = None
            if _abl:
                try:
                    await msg.delete()
                except Exception:
                    pass
                try:
                    await send_log(msg.guild, 'anti_badwords', msg.author, msg,
                                   "Terme discriminatoire (validisme) retiré", f"||{(_abl or '')[:40]}||")
                except Exception:
                    pass
                try:
                    await _record_infraction(msg.guild.id, msg.author.id, 'discrimination',
                                             f"Validisme : {(_abl or '')[:40]}", '')
                except Exception:
                    pass
                try:
                    await _warn_calm_down(
                        msg.channel,
                        f"🚫 {msg.author.mention}, les termes liés à un handicap ou une maladie "
                        f"(« autiste », « mongol », « trisomique »…) ne sont **pas tolérés** ici — "
                        f"**même pour parler de soi**. Ça blesse et ça n'a pas sa place. 🙏")
                except Exception:
                    pass
                try:
                    await _cumulative_offense_sanction(msg.guild, msg.author, msg.channel,
                                                       'propos discriminatoire')
                except Exception:
                    pass
                try:
                    await _note_attack(msg, 'discrimination', _abl)
                except Exception:
                    pass
                return
            try:
                _ilvl, _iterm = insult_filter.scan(_spoken, _ispoken_norm)
                if _ideob:                                  # anti-contournement : variante recollée
                    _dlvl, _dterm = insult_filter.scan(_ideob)
                    if _dlvl > _ilvl:
                        _ilvl, _iterm = _dlvl, _dterm
            except Exception:
                _ilvl, _iterm = 0, None
            # Rien dans le texte PARLÉ → regarder le GIF/lien (slug), jaugé différemment.
            if _ilvl == 0:
                _slug = _msg_url_slugs(ct)
                if _slug:
                    try:
                        _slvl, _sterm = insult_filter.scan(_slug)
                    except Exception:
                        _slvl, _sterm = 0, None
                    if _slvl >= 3:
                        _ilvl, _iterm = _slvl, _sterm   # haine/slur DANS un GIF = sérieux → comme du texte
                    elif _slvl == 2:
                        # Insulte légère (« tg ») SEULEMENT dans un GIF/lien → LÉGER : on retire le
                        # média + rappel doux, SANS infraction ni mute (≠ insulte dite en face).
                        try:
                            await msg.delete()
                        except Exception:
                            pass
                        await _warn_calm_down(
                            msg.channel,
                            f"🎞️ {msg.author.mention}, évite les GIFs/liens avec ce genre de texte 🙏")
                        return
            # 🤬 INSULTE VULGAIRE CLAIRE (owner 2026-06-29) : « Bot de con », « serveur trou du cul »,
            # « espèce de con », « fils de pute »… visent le bot/serveur (ou personne) → l'ancien
            # filtre ne déclenchait QUE si ça ciblait un MEMBRE → ces contournements passaient.
            # Ici on agit dès l'expression vulgaire, peu importe la cible. Liste zéro-FP (testée) :
            # « c'est con », « match nul », « je m'en branle », « ce boss est con »… restent libres.
            # On laisse la priorité aux niveaux 3/4 (haine/incitation) gérés juste en dessous.
            if _ilvl < 3:
                try:
                    _dv = _DIRECT_VULGAR_RE.search(_spoken or '')
                    if not _dv and _ideob:
                        _dv = _DIRECT_VULGAR_RE.search(_ideob)
                except Exception:
                    _dv = None
                # audit 2026-07-02 : « connard/connasse/fils de pute » visant une CHOSE en banter
                # gaming SANS cible-membre (« cette connasse de quête buggée », « ce boss est un
                # fils de pute ») ≠ insulte d'un membre → on N'AGIT PAS. Les formes visant le
                # bot/serveur (bot de con, serveur de merde, trou du cul…) agissent TOUJOURS.
                if _dv:
                    try:
                        _dvl = _dv.group(0).lower()
                        if _dvl.startswith(('con', 'c0n', 'fil')):
                            _tgt = bool(getattr(msg, 'mentions', None)) \
                                or getattr(msg, 'reference', None) is not None \
                                or bool(_INSULT_TARGET_RE.search(_spoken or ''))
                            if not _tgt and _GAMING_CTX_RE.search(_spoken or ''):
                                _dv = None
                    except Exception:
                        pass
                if _dv:
                    _dvt = _dv.group(0)
                    try:
                        await msg.delete()
                    except Exception:
                        pass
                    try:
                        await send_log(msg.guild, 'anti_badwords', msg.author, msg,
                                       "Insulte vulgaire", f"||{_dvt[:40]}||")
                    except Exception:
                        pass
                    try:
                        await _record_infraction(msg.guild.id, msg.author.id, 'insulte',
                                                 f"Insulte vulgaire : {_dvt[:40]}", '')
                    except Exception:
                        pass
                    try:
                        if await _offense_tick(msg.guild, msg.author, msg.channel):
                            return   # banni par la rafale → on s'arrête là
                    except Exception:
                        pass
                    try:
                        await _cumulative_insult_sanction(msg, _dvt)
                    except Exception:
                        pass
                    try:
                        await _note_attack(msg, 'insulte', _dvt)
                    except Exception:
                        pass
                    return
            if _ilvl >= 2:
                try:
                    _itargeted = bool(getattr(msg, 'mentions', None)) \
                        or getattr(msg, 'reference', None) is not None \
                        or bool(_INSULT_TARGET_RE.search(_spoken or ''))
                except Exception:
                    _itargeted = False
                if _ilvl >= 4:
                    # 🆘 INCITATION AU SUICIDE / À LA MORT dirigée vers autrui (owner 2026-06-21) :
                    # une ATTAQUE grave → action maximale + alerte owner. NB : exprimer SA propre
                    # détresse (« kms », « je veux mourir ») n'est PAS détecté ici (formes 1re
                    # personne exclues du lexique) → jamais sanctionné.
                    try:
                        await msg.delete()
                    except Exception:
                        pass
                    try:
                        _ist = _register_protection_strike(msg.guild.id, msg.author.id, 'insult')
                    except Exception:
                        _ist = 1
                    try:
                        await msg.author.timeout(timedelta(hours=1), reason="Incitation au suicide / à la mort")
                    except Exception:
                        pass
                    try:
                        await ulogger2026.log_event(
                            bot, msg.guild, ulogger2026.EventType.SEC_ESCALATION,
                            description=(f"🆘 **Incitation au suicide / à la mort** de {msg.author.mention} "
                                         f"supprimée → exclusion 1 h. Envisage `/off` si récidive. "
                                         f"_(Si quelqu'un exprime SA propre détresse, accompagne-le — "
                                         f"ce cas n'est pas sanctionné.)_"),
                            user=msg.author, moderator=bot.user, channel=msg.channel,
                            extra={"🧱 Gravité": "Niveau 4 (incitation au mal)", "🔁 Récidive": str(_ist),
                                   "🔎 Terme": f"||{(_iterm or '')[:40]}||"})
                    except Exception:
                        pass
                    try:
                        await _record_infraction(msg.guild.id, msg.author.id, 'incitation',
                                                 f"Incitation au suicide/mort : {(_iterm or '')[:40]}", '1h')
                    except Exception:
                        pass
                    try:
                        await _offense_tick(msg.guild, msg.author, msg.channel)
                    except Exception:
                        pass
                    return
                if _ilvl >= 3:
                    # HAINE / DISCRIMINATION (peu importe le ciblage) : suppression + exclusion
                    # 1 h + ALERTE owner (suggère /off pour une radiation si récidive).
                    try:
                        await msg.delete()
                    except Exception:
                        pass
                    try:
                        _ist = _register_protection_strike(msg.guild.id, msg.author.id, 'insult')
                    except Exception:
                        _ist = 1
                    try:
                        await msg.author.timeout(timedelta(hours=1), reason="Propos haineux / discriminatoires")
                    except Exception:
                        pass
                    try:
                        await ulogger2026.log_event(
                            bot, msg.guild, ulogger2026.EventType.SEC_ESCALATION,
                            description=(f"🚨 Propos **haineux / discriminatoires** de {msg.author.mention} "
                                         f"supprimés → exclusion 1 h. Envisage `/off` en cas de récidive."),
                            user=msg.author, moderator=bot.user, channel=msg.channel,
                            extra={"🧱 Gravité": "Niveau 3 (haine)", "🔁 Récidive": str(_ist),
                                   "🔎 Terme": f"||{(_iterm or '')[:40]}||"})
                    except Exception:
                        pass
                    try:
                        await _record_infraction(msg.guild.id, msg.author.id, 'haine',
                                                 f"Propos haineux/discriminatoires : {(_iterm or '')[:40]}", '1h')
                    except Exception:
                        pass
                    try:
                        await _offense_tick(msg.guild, msg.author, msg.channel)
                    except Exception:
                        pass
                    try:
                        await _note_attack(msg, 'haine', _iterm)
                    except Exception:
                        pass
                    return
                elif _itargeted:
                    # INSULTE qui VISE une personne → suppression + fiche + SANCTION CUMULATIVE
                    # (graduée selon le total d'infractions sur 14 j, jusqu'à blacklist) : le warn
                    # seul ne suffit pas si le membre s'en fiche → on durcit et on lui EXPLIQUE.
                    try:
                        await msg.delete()
                    except Exception:
                        pass
                    try:
                        await send_log(msg.guild, 'anti_badwords', msg.author, msg,
                                       "Insulte ciblée", f"N2 · ||{(_iterm or '')[:40]}||")
                    except Exception:
                        pass
                    try:
                        await _record_infraction(msg.guild.id, msg.author.id, 'insulte',
                                                 f"Insulte ciblée : {(_iterm or '')[:40]}", '')
                    except Exception:
                        pass
                    try:
                        if await _offense_tick(msg.guild, msg.author, msg.channel):
                            return   # banni par la rafale → on s'arrête là
                    except Exception:
                        pass
                    try:
                        await _cumulative_insult_sanction(msg, _iterm)
                    except Exception:
                        pass
                    try:
                        await _note_attack(msg, 'insulte', _iterm)
                    except Exception:
                        pass
                    return
                else:
                    # INSULTE EN L'AIR (ne vise personne) : on NE supprime PAS (c'est de
                    # l'expression) ; on freine seulement en cas de RÉPÉTITION, sans punir un
                    # écart isolé. Pas de return → le message reste et le pipeline continue.
                    try:
                        _ist = _register_protection_strike(msg.guild.id, msg.author.id, 'insult')
                    except Exception:
                        _ist = 0
                    if _ist >= 4:
                        await _warn_calm_down(
                            msg.channel, f"🙂 {msg.author.mention}, surveille un peu ton langage 🙏")
            # N1 (juron léger) : aucune action — c'est de l'expression.

        # 🛑 ANTI-POLITIQUE / RELIGION / MILITANTISME (owner 2026-06-21) — serveur GAMING & CHILL.
        # Bloque les SLOGANS (free palestine, black lives matter, antifa, prosélytisme…) — y
        # compris dans un GIF, via le slug de l'URL Tenor/Giphy (offtopic_filter lit les mots du
        # lien avant l'image). Lexique vérifié anti-faux-positifs GAMING (aucun mot isolé type
        # free/god/war/vote). On SUPPRIME + petit rappel ; mute court si spam répété. Immunisés/
        # salons immunisés/tickets déjà exclus. FAIL-SAFE.
        if c.get('anti_offtopic', 1):
            try:
                _ot = offtopic_filter.scan(ct, _normalize_for_scan(ct))
            except Exception:
                _ot = None
            if _ot:
                try:
                    await msg.delete()
                except Exception:
                    pass
                try:
                    _ots = _register_protection_strike(msg.guild.id, msg.author.id, 'offtopic')
                except Exception:
                    _ots = 1
                if _ots >= 3:
                    try:
                        await msg.author.timeout(
                            timedelta(minutes=5),
                            reason="Contenu politique/religieux répété (serveur gaming)")
                    except Exception:
                        pass
                    await _warn_calm_down(
                        msg.channel,
                        f"🎮 {msg.author.mention}, ici c'est **gaming & chill** — pas de politique "
                        f"ni de religion. Petite pause de **5 min**, on se détend 🙏")
                else:
                    await _warn_calm_down(
                        msg.channel,
                        f"🎮 {msg.author.mention}, ici on parle **jeux vidéo & chill** — on garde la "
                        f"politique et la religion en dehors du serveur 🙏")
                try:
                    await send_log(msg.guild, 'anti_badwords', msg.author, msg,
                                   "Contenu politique/religieux/militant", f"||{(_ot or '')[:60]}||")
                except Exception:
                    pass
                return

        # ── ABUS TECHNIQUES (owner 2026-06-21) — anti-crash / spam inter-salons / automation ──
        # Immunisés/staff/salons immunisés/tickets déjà exclus (user_immune en tête). FAIL-SAFE.
        # #8 : texte « cassé » (zalgo / invisible) qui fait ramer → suppression + rappel doux.
        if c.get('anti_crash', 1):
            try:
                _crash = behavior_guard.is_crash_text(ct)
            except Exception:
                _crash = None
            if _crash:
                try:
                    await msg.delete()
                except Exception:
                    pass
                await _warn_calm_down(
                    msg.channel,
                    f"🧱 {msg.author.mention}, ton message contenait du texte « cassé » (qui fait "
                    f"ramer les applis) — il a été retiré 🙏")
                try:
                    await send_log(msg.guild, 'anti_spam', msg.author, msg, "Texte anti-crash retiré", _crash)
                except Exception:
                    pass
                return
        # #9 : même message copié dans plusieurs salons en quelques s → spam/raid/compte piraté.
        if c.get('anti_xchannel', 1):
            try:
                _xc = behavior_guard.track_xchannel(msg.guild.id, msg.author.id, msg.channel.id, ct)
            except Exception:
                _xc = False
            if _xc:
                try:
                    await msg.delete()
                except Exception:
                    pass
                try:
                    await msg.author.timeout(timedelta(minutes=10), reason="Spam inter-salons (même message partout)")
                except Exception:
                    pass
                try:
                    _register_protection_strike(msg.guild.id, msg.author.id, 'xchannel')
                except Exception:
                    pass
                try:
                    await ulogger2026.log_event(
                        bot, msg.guild, ulogger2026.EventType.SEC_SPAM,
                        description=(f"📡 {msg.author.mention} a posté le **même message dans plusieurs "
                                     f"salons** en quelques secondes → exclusion 10 min (spam / compte piraté ?)."),
                        user=msg.author, moderator=bot.user, channel=msg.channel)
                except Exception:
                    pass
                return
        # #10 : rafale à vitesse INHUMAINE → automation/selfbot. Warn d'abord, mute si ça persiste.
        if c.get('anti_automation', 1):
            try:
                _au = behavior_guard.track_automation(msg.guild.id, msg.author.id)
            except Exception:
                _au = False
            if _au:
                try:
                    await msg.delete()
                except Exception:
                    pass
                try:
                    _as = _register_protection_strike(msg.guild.id, msg.author.id, 'automation')
                except Exception:
                    _as = 1
                if _as <= 1:
                    await _warn_calm_down(
                        msg.channel,
                        f"🤖 {msg.author.mention}, doucement — tu envoies à une vitesse anormale 🙏")
                else:
                    try:
                        await msg.author.timeout(timedelta(minutes=5), reason="Vitesse de messages inhumaine (automation)")
                    except Exception:
                        pass
                    try:
                        await ulogger2026.log_event(
                            bot, msg.guild, ulogger2026.EventType.SEC_SPAM,
                            description=(f"🤖 {msg.author.mention} envoie à une **vitesse inhumaine** → "
                                         f"exclusion 5 min (bot/selfbot présumé)."),
                            user=msg.author, moderator=bot.user, channel=msg.channel)
                    except Exception:
                        pass
                return

        # ── CONFIANCE PROGRESSIVE + POLITIQUE LIENS/INVITATIONS (owner 2026-06-21) ──
        # Immunisés/staff/salons immunisés/tickets déjà exclus (user_immune en tête). Pour les
        # AUTRES : (1) invitations interdites pour tous ; (2) liens interdits pour tous SAUF
        # image/GIF ; (3) images/GIFs/fichiers bloqués tant que le membre n'est pas DE CONFIANCE
        # (nouveau) — une fois la confiance acquise (ancienneté/activité), il poste librement.
        # FAIL-OPEN : toute erreur n'interrompt pas on_message.
        if c.get('trust_system', 1):
            try:
                trust_system.bump(msg.guild.id, msg.author.id)
            except Exception:
                pass
            _fresh_min = int(c.get('trust_fresh_minutes', 15) or 15)
            # (1) INVITATION Discord → interdite pour tous.
            try:
                _inv = trust_system.has_invite(ct)
            except Exception:
                _inv = False
            if _inv:
                try:
                    await msg.delete()
                except Exception:
                    pass
                await _trust_block_notice(msg, 'invite', fresh_escalate=True, fresh_minutes=_fresh_min)
                try:
                    await send_log(msg.guild, 'anti_invite', msg.author, msg, "Invitation (interdite)", None)
                except Exception:
                    pass
                # owner 2026-06-26 : les invitations sont LE vecteur de spam de promo / compte
                # piraté → on TRACE, on détecte la RAFALE (≥N invites en quelques s → BAN direct —
                # CHOIX EXPLICITE owner « ban le spammeur d'invites », petit risque de faux-positif
                # assumé) et on escalade le récidiviste lent (rappel → mute → … → blacklist + alerte).
                # Tick AVANT la cumulative : l'infraction est comptée tout de suite, et un vrai bot
                # qui dépose ses invites en rafale est banni avant que le mute progressif l'arrête.
                try:
                    await _record_infraction(msg.guild.id, msg.author.id, 'protection',
                                             "Invitation Discord (interdite)", '')
                except Exception:
                    pass
                try:
                    if await _offense_tick(msg.guild, msg.author, msg.channel):
                        return   # banni par la rafale
                except Exception:
                    pass
                try:
                    await _cumulative_offense_sanction(msg.guild, msg.author, msg.channel,
                                                       'invitation Discord')
                except Exception:
                    pass
                return
            # (2) LIEN non-image/GIF → interdit pour tous (GIFs/images restent permis). owner
            # 2026-07-12 : ce bloc HONORE désormais les SALONS autorisés (link_allowed_channels)
            # ET la WHITELIST de liens (link_whitelist) — avant, ta config « autoriser » était
            # IGNORÉE ici (elle ne servait qu'à l'anti_link classique, souvent OFF) → tu autorisais
            # des liens et les gens étaient quand même bloqués. Les GIFs passent aussi via l'indice
            # 'gif' dans l'URL (tout hôte, cf. trust_system).
            try:
                if chid in c.get('link_allowed_channels', []):
                    _badlink = False                  # salon où les liens sont librement autorisés
                else:
                    _badlink = trust_system.has_non_media_link(ct, c.get('link_whitelist', []))
            except Exception:
                _badlink = False
            if _badlink:
                try:
                    await msg.delete()
                except Exception:
                    pass
                await _trust_block_notice(msg, 'link', fresh_escalate=True, fresh_minutes=_fresh_min)
                try:
                    await send_log(msg.guild, 'anti_link', msg.author, msg, "Lien (interdit hors image/GIF)", None)
                except Exception:
                    pass
                return
            # (3) IMAGES/GIFs/fichiers pour un NOUVEAU membre. owner 2026-07-11 : « autoriser les
            # GIFs/images pour TOUT LE MONDE, tout le temps » → ce blocage est DÉSACTIVÉ par défaut
            # (trust_block_media=0). Les filets NSFW (nudenet) + anti-scam (OCR) + anti-phishing +
            # anti-invitations + anti-liens tournent TOUJOURS. Mettre trust_block_media=1 pour ré-armer.
            try:
                _trusted = True if not c.get('trust_block_media', 0) else trust_system.is_trusted(
                    msg.author,
                    age_hours=int(c.get('trust_age_hours', 24) or 24),
                    fast_hours=int(c.get('trust_fast_hours', 2) or 2),
                    fast_msgs=int(c.get('trust_fast_msgs', 12) or 12),
                    min_account_days=int(c.get('trust_min_account_days', 7) or 0))
            except Exception:
                _trusted = True
            if not _trusted:
                try:
                    _media = trust_system.has_media(msg, ct)
                except Exception:
                    _media = False
                if _media:
                    try:
                        await msg.delete()
                    except Exception:
                        pass
                    await _trust_block_notice(msg, 'media_newbie')
                    return

        # Anti-invite
        if c.get('anti_invite'):
            f, inv = check_invite(ct)
            if f:
                await msg.delete()
                await send_log(msg.guild, 'anti_invite', msg.author, msg, "Invitation Discord", f"`{inv}`")
                action = c.get('invite_action', 'delete')
                dur = c.get('invite_mute_duration', 5)
                await sanction(msg.author, action, dur, "Invitation Discord", msg.guild)
                return

        # Anti-link
        if c.get('anti_link') and not iag:
            if chid not in c.get('link_allowed_channels', []):
                f, url = check_link(ct, c.get('link_whitelist', []))
                if f:
                    await msg.delete()
                    await send_log(msg.guild, 'anti_link', msg.author, msg, "Lien non autorisé", f"`{url}`")
                    action = c.get('link_action', 'delete')
                    dur = c.get('link_mute_duration', 5)
                    await sanction(msg.author, action, dur, "Lien non autorisé", msg.guild)
                    return

        # Anti-image
        if c.get('anti_image') and not iag:
            if chid not in c.get('image_allowed_channels', []):
                bl = check_image(msg, c.get('image_allowed', []))
                if bl:
                    await msg.delete()
                    await send_log(msg.guild, 'anti_image', msg.author, msg, "Format non autorisé", f"`{', '.join(bl)}`")
                    action = c.get('image_action', 'delete')
                    dur = c.get('image_mute_duration', 5)
                    await sanction(msg.author, action, dur, "Format non autorisé", msg.guild)
                    return

        # Anti-spam
        # Exemption défensive : staff/admin/owner/rôles immune doivent pouvoir poster
        # vite (annonces, modération) sans être avertis ni mutés. Le bot est déjà filtré
        # en tête d'on_message. Cette garde est déjà après le return `user_immune`, on
        # double la sécurité par is_fully_immune (couvre owner + admin + rôles/users immune).
        if c.get('anti_spam') and not await is_fully_immune(msg.author):
            # owner 2026-07-17 : il faut le CUMUL débit + contenu. `check_spam` ne juge que la
            # vitesse → seul, il supprimait des phrases légitimes écrites vite. `_spam_content_kind`
            # alimente toujours son tampon de rafale (même si le débit ne déclenche pas), sinon on
            # ne pourrait pas reconnaître « un mot / entrée » répété sur plusieurs secondes.
            _fast = await check_spam(msg, c.get('spam_max', 5), c.get('spam_interval', 5))
            _kind = _spam_content_kind(msg.guild.id, msg.author.id, msg.content or '')
            if _fast and _kind == 'toxic':
                # Tout fail-safe : un échec d'avertissement/strike/escalade ne doit JAMAIS
                # empêcher la suppression+log, ni casser on_message.
                try:
                    await msg.delete()
                except Exception:
                    pass
                await send_log(msg.guild, 'anti_spam', msg.author, msg, "Spam toxique détecté", None)
                # Strikes progressifs (rétention) : on AVERTIT gentiment d'abord.
                strikes = 1
                try:
                    strikes = _register_protection_strike(msg.guild.id, msg.author.id, 'spam')
                except Exception as _ex:
                    print(f"[anti_spam strike] {_ex}")

                # ═══ ÉCHELLE VOULUE PAR L'OWNER (2026-07-17) ═══
                # « Tu le reprends une fois. S'il comprend pas, 2 fois. S'il comprend toujours pas,
                #   au bout de la 3e fois tu le WARN → il perd les events et le VIP. S'il comprend
                #   toujours pas, tu le re-warn. Et après tu le sanctionnes. »
                # → rappels 1-3 · warn 4 · warn 5 · sanction 6+.
                # Les RAPPELS vivent dans la fenêtre RAM (10 min) : s'il se calme, on oublie — c'est
                # le but d'un rappel. Les WARNS, eux, sont écrits dans `infractions` → PERSISTANTS,
                # comptés, visibles dans /mod infractions, et ils survivent au reboot.
                _warn_at = int(c.get('spam_strike_warn', 4))
                if strikes < _warn_at:
                    _ordinal = {1: "1er", 2: "2e", 3: "3e"}.get(strikes, f"{strikes}e")
                    _suite = ("" if strikes < _warn_at - 1 else
                              " — **prochaine fois = avertissement officiel** (tu perdrais le VIP "
                              "et l'accès aux événements).")
                    await _warn_calm_down(
                        msg.channel,
                        f"⚠️ {msg.author.mention}, **{_ordinal} rappel** : évite de répéter le même "
                        f"caractère ou de couper tes phrases en un mot par message 🙏 "
                        f"Écris ta phrase en une fois, ça passe très bien.{_suite}",
                    )
                else:
                    # Combien de warns SPAM a-t-il déjà ? (persistant, source de vérité unique)
                    _spam_warns = 0
                    try:
                        async with get_db() as db:
                            async with db.execute(
                                "SELECT COUNT(*) FROM infractions WHERE guild_id=? AND user_id=? "
                                "AND type='warn' AND reason LIKE 'Spam toxique%'",
                                (msg.guild.id, msg.author.id),
                            ) as _sc:
                                _spam_warns = int(((await _sc.fetchone()) or [0])[0] or 0)
                    except Exception as _ex:
                        print(f"[anti_spam warn count] {_ex}", file=_sys.stderr, flush=True)

                    if _spam_warns < int(c.get('spam_warns_before_sanction', 2)):
                        # ── PALIER WARN (4e puis 5e) : fiche + REMISE À ZÉRO DES STATS + MP ──
                        # owner 2026-07-17 (CHANGEMENT vs privation VIP) : « au 3e rappel ignoré, tu
                        # lui supprimes TOUTES ses statistiques → il repart de zéro et doit tout
                        # re-gagner (VIP, VIP+, Hyper). » N'est atteignable qu'après CUMUL : contenu
                        # toxique ET débit ET 3 rappels ignorés → un membre qui écrit des phrases n'y
                        # arrive jamais. Le reset ne touche QUE l'activité (activity_score +
                        # vip_status + rôles VIP) : ni coins, ni succès, ni inventaire.
                        _reason = f"Spam toxique répété (malgré {strikes - 1} rappels)"
                        await _record_infraction(msg.guild.id, msg.author.id, 'warn', _reason, '')
                        _was_reset = False
                        try:
                            _was_reset = await activity_vip_module.reset_member_stats(
                                msg.guild, msg.author.id)
                        except Exception as _ex:
                            print(f"[anti_spam reset stats] {_ex}", file=_sys.stderr, flush=True)
                        # MP avec le récap COMPLET (owner : « il dira toujours j'ai rien fait »).
                        await _dm_sanction(
                            msg.author, msg.guild,
                            f"⚠️ Avertissement officiel ({_spam_warns + 1}/2) — statistiques remises à zéro",
                            _reason)
                        # MP dédié : lui dire CLAIREMENT qu'il repart de zéro et pourquoi.
                        if _was_reset:
                            try:
                                await msg.author.send(
                                    f"🔄 **Tes statistiques d'activité sur {msg.guild.name} ont été "
                                    f"remises à ZÉRO.**\n"
                                    f"Raison : spam répété malgré {strikes - 1} rappels.\n\n"
                                    f"Tu repars de 0 : ton score pour le **VIP / VIP+** est réinitialisé "
                                    f"et tu dois le re-gagner par une activité **normale** (des vraies "
                                    f"phrases, du vocal…). Rien d'autre n'est touché.\n"
                                    f"-# Si tu respames, ça recommence — puis une sanction.")
                            except Exception:
                                pass
                        await _warn_calm_down(
                            msg.channel,
                            f"⚠️ {msg.author.mention}, **avertissement officiel** enregistré "
                            f"(spam malgré les rappels) — **tes statistiques d'activité repartent de "
                            f"zéro**. Regarde tes MP. À la prochaine, c'est une sanction.",
                        )
                        try:
                            await ulogger2026.log_member_escalation(
                                bot, msg.guild, msg.author, total_warns=_spam_warns + 1,
                                palier="spam-warn",
                                reason=_reason, moderator=bot.user, severity="moyenne",
                            )
                        except Exception as _ex:
                            print(f"[anti_spam escalation] {_ex}")
                    else:
                        # ── PALIER SANCTION : les 2 warns n'ont pas suffi ──
                        dur = c.get('spam_mute_duration', 10)
                        await sanction(msg.author, c.get('spam_action', 'mute'), dur,
                                       "Spam toxique répété (2 avertissements ignorés)", msg.guild)
                        try:
                            await ulogger2026.log_member_escalation(
                                bot, msg.guild, msg.author, total_warns=strikes,
                                palier="spam-mentions",
                                reason="Spam toxique répété malgré rappels et avertissements",
                                moderator=bot.user, severity="haute",
                            )
                        except Exception as _ex:
                            print(f"[anti_spam escalation] {_ex}")
                return

        # Anti-MONOLOGUE (owner 2026-06-21) : ≥ 10 messages D'AFFILÉE d'un même membre sans que
        # PERSONNE n'écrive entre → on le freine pour laisser parler les autres. Palier 1 =
        # avertissement doux · 2 = mute 10 s (le + petit possible) · 3+ = mute 1 min. Immunisés/
        # staff exemptés (is_fully_immune). Ne SUPPRIME PAS le message (il est légitime). FAIL-SAFE.
        if c.get('anti_monologue', 1) and not await is_fully_immune(msg.author):
            try:
                _mid = msg.channel.id
                _st = _monologue_tracker.get(_mid)
                if _st and _st[0] == msg.author.id:
                    _st[1] += 1
                else:
                    _st = [msg.author.id, 1]
                    _monologue_tracker[_mid] = _st
                if len(_monologue_tracker) > 3000:  # borne mémoire
                    for _k in list(_monologue_tracker.keys())[:600]:
                        _monologue_tracker.pop(_k, None)
                if _st[1] >= _MONOLOGUE_THRESHOLD:
                    _st[1] = 0  # reset → il faut RE-enchaîner 10 messages pour re-déclencher
                    try:
                        _strk = _register_protection_strike(msg.guild.id, msg.author.id, 'monologue')
                    except Exception:
                        _strk = 1
                    if _strk <= 1:
                        await _warn_calm_down(
                            msg.channel,
                            f"🐢 {msg.author.mention}, tu enchaînes pas mal de messages — laisse "
                            f"un peu de place aux autres 🙏")
                    elif _strk == 2:
                        try:
                            await msg.author.timeout(
                                timedelta(seconds=10),
                                reason="Monologue (laisser les autres écrire)")
                        except Exception:
                            pass
                        await _warn_calm_down(
                            msg.channel,
                            f"⏳ {msg.author.mention}, petite pause de **10 s** — laisse le chat respirer.")
                    else:
                        try:
                            await msg.author.timeout(
                                timedelta(minutes=1), reason="Monologue répété")
                        except Exception:
                            pass
                        await _warn_calm_down(
                            msg.channel,
                            f"⏳ {msg.author.mention}, pause d'**1 min** — laisse les autres participer.")
                    try:
                        await send_log(msg.guild, 'anti_spam', msg.author, msg,
                                       "Monologue (messages d'affilée)", f"Palier {_strk}")
                    except Exception:
                        pass
            except Exception as _exm:
                print(f"[anti_monologue] {_exm}")

        # Anti-rafale d'IMAGES/FICHIERS (owner 2026-06-21, #4) : > _IMG_FLOOD_MAX pièces jointes
        # en _IMG_FLOOD_WINDOW s d'un même membre → on freine (warn → 10 s → 1 min via les
        # strikes). Immunisés exemptés. Complète l'anti-monologue + l'anti-scam-image. FAIL-SAFE.
        if (c.get('anti_image_flood', 1) and getattr(msg, 'attachments', None)
                and not await is_fully_immune(msg.author)):
            try:
                _now_f = now()
                _kf = (msg.guild.id, msg.author.id)
                _buf = [t for t in _attach_flood.get(_kf, [])
                        if (_now_f - t).total_seconds() < _IMG_FLOOD_WINDOW]
                _buf.extend([_now_f] * len(msg.attachments))
                _attach_flood[_kf] = _buf
                if len(_attach_flood) > 5000:  # borne mémoire
                    for _k2 in [k for k, v in list(_attach_flood.items())
                                if not v or (_now_f - v[-1]).total_seconds() > _IMG_FLOOD_WINDOW]:
                        _attach_flood.pop(_k2, None)
                if len(_buf) > _IMG_FLOOD_MAX:
                    _attach_flood[_kf] = []  # reset → re-flood requis pour re-déclencher
                    try:
                        await msg.delete()
                    except Exception:
                        pass
                    try:
                        _sf = _register_protection_strike(msg.guild.id, msg.author.id, 'imgflood')
                    except Exception:
                        _sf = 1
                    if _sf <= 1:
                        await _warn_calm_down(
                            msg.channel,
                            f"🖼️ {msg.author.mention}, doucement avec les fichiers/images — tu en "
                            f"envoies trop d'un coup 🙏")
                    elif _sf == 2:
                        try:
                            await msg.author.timeout(timedelta(seconds=10), reason="Rafale d'images/fichiers")
                        except Exception:
                            pass
                    else:
                        try:
                            await msg.author.timeout(timedelta(minutes=1), reason="Rafale d'images/fichiers répétée")
                        except Exception:
                            pass
                    try:
                        await send_log(msg.guild, 'anti_spam', msg.author, msg,
                                       "Rafale d'images/fichiers", f"Palier {_sf}")
                    except Exception:
                        pass
                    return
            except Exception as _exf:
                print(f"[anti_image_flood] {_exf}")

        # Anti-caps
        if c.get('anti_caps'):
            if check_caps(ct, c.get('caps_percent', 70)):
                await msg.delete()
                await send_log(msg.guild, 'anti_caps', msg.author, msg, "Trop de majuscules", None)
                action = c.get('caps_action', 'delete')
                dur = c.get('caps_mute_duration', 5)
                await sanction(msg.author, action, dur, "Majuscules excessives", msg.guild)
                return

        # Anti-mass-mention (détecte @everyone/@here et spam de mentions)
        # Exemption défensive : un staff/admin/owner/rôle immune DOIT pouvoir faire une
        # vraie annonce @everyone sans être averti ni sanctionné. Le bot est déjà filtré
        # en tête d'on_message. (Garde déjà après le return `user_immune` ; on double via
        # is_fully_immune qui couvre owner + admin + rôles/users immune.)
        # ⚠️ owner 2026-06-16 : on exempte AUSSI quiconque a la PERMISSION Discord
        # « Mentionner @everyone » (rôle autorisé à pinger @everyone/@here/rôles) → un
        # membre HABILITÉ ne doit jamais être sanctionné par l'anti-mention de masse.
        if (c.get('anti_mass_mention')
                and not await is_fully_immune(msg.author)
                and not bool(getattr(msg.author.guild_permissions, 'mention_everyone', False))):
            max_mentions = c.get('mention_limit', 5)
            if check_mass_mention(msg, max_mentions):
                # Tout fail-safe : aucune sous-étape ne doit casser on_message.
                try:
                    await msg.delete()
                except Exception:
                    pass
                mention_count = len(msg.mentions) + len(msg.role_mentions) + (1 if msg.mention_everyone else 0)
                await send_log(msg.guild, 'anti_mass_mention', msg.author, msg,
                              "Spam de mentions détecté", f"`{mention_count}` mentions")
                # Strikes progressifs (rétention) : on AVERTIT gentiment d'abord.
                strikes = 1
                try:
                    strikes = _register_protection_strike(msg.guild.id, msg.author.id, 'mention')
                except Exception as _ex:
                    print(f"[anti_mass_mention strike] {_ex}")
                await _warn_calm_down(
                    msg.channel,
                    f"⚠️ {msg.author.mention}, doucement avec les mentions / @everyone 🙏 "
                    f"— ton message a été retiré.",
                )
                # 3e écart+ dans la fenêtre : sanction configurée + escalade staff.
                if strikes >= _PROTECTION_STRIKE_ESCALATE:
                    dur = c.get('mention_mute_duration', 10)
                    await sanction(msg.author, c.get('mention_action', 'mute'), dur,
                                   "Spam de mentions répété", msg.guild)
                    try:
                        await ulogger2026.log_member_escalation(
                            bot, msg.guild, msg.author, total_warns=strikes,
                            palier="spam-mentions",
                            reason="Spam de mentions/@everyone répété",
                            moderator=bot.user, severity="haute",
                        )
                    except Exception as _ex:
                        print(f"[anti_mass_mention escalation] {_ex}")
                return

        # Anti-QRCode (détection de scams par QR code) - Actif pour tous
        if c.get('anti_qrcode'):
            is_qr_scam, qr_pattern = check_qr_code_scam(ct)
            if is_qr_scam:
                await msg.delete()
                await send_log(msg.guild, 'anti_qrcode', msg.author, msg,
                              "Scam QR Code détecté", f"Pattern: {qr_pattern}")
                dur = c.get('qrcode_mute_duration', 30)
                await sanction(msg.author, c.get('qrcode_action', 'mute'), dur, "Scam QR Code", msg.guild)
                return
        
        # Fichiers dangereux - Actif pour tous
        if msg.attachments:
            for att in msg.attachments:
                is_dangerous, ext = check_dangerous_file(att.filename)
                if is_dangerous:
                    await msg.delete()
                    await send_log(msg.guild, 'anti_phishing', msg.author, msg, 
                                  "Fichier dangereux détecté", f"Extension: {ext}")
                    warn_e = discord.Embed(color=0xE74C3C, description=f"⚠️ {msg.author.mention} a envoyé un fichier potentiellement dangereux (`{ext}`).\nLe fichier a été **supprimé** automatiquement.")
                    warn_e.set_footer(text="🛡️ Protection anti-phishing")
                    warn_msg = await webhook_send(msg.channel, 'protection', embed=warn_e)
                    if warn_msg:
                        async def _del_warn(m):
                            await asyncio.sleep(10)
                            try: await m.delete()
                            except: pass
                        asyncio.create_task(_del_warn(warn_msg))
                    return
        
    except: pass

