async def security_check(i: discord.Interaction, command_name: str = "command"):
    """Vérifie la sécurité avant d'exécuter une commande"""
    user_id = i.user.id
    guild_id = i.guild.id if i.guild else 0
    
    # Vérifier blacklist temporaire
    is_blocked, reason = is_blacklisted(user_id)
    if is_blocked:
        return False, f"⛔ Vous êtes temporairement bloqué: {reason}"
    
    # Vérifier rate limit
    if not check_rate_limit(guild_id, user_id, 'command'):
        # Blacklister temporairement si abuse répété
        if user_id in security_attempts:
            security_attempts[user_id]['attempts'] += 1
            if security_attempts[user_id]['attempts'] >= 5:
                blacklist_user(user_id, 10, "Spam de commandes")
                await log_security_event(guild_id, user_id, "RATE_LIMIT_BAN", f"Commande: {command_name}")
        else:
            security_attempts[user_id] = {'attempts': 1, 'last': now()}
            _evict_if_big(security_attempts)
        return False, "⚠️ Trop de commandes ! Attendez un moment."
    
    return True, None

@bot.tree.command(name="configure", description="⚙️ Ouvrir le panneau de configuration")
async def configure_cmd(i: discord.Interaction):
    # Phase 3.0f : defer IMMEDIAT pour ne jamais timeout l'interaction (3s).
    # Tout le travail (DB, build panel) se fait apres avec followup.
    try:
        await i.response.defer(ephemeral=True, thinking=False)
    except (discord.InteractionResponded, discord.NotFound):
        pass

    # ═══════════════ OWNER ONLY - Sécurité maximale ═══════════════
    is_guild_owner = i.user.id == i.guild.owner_id
    is_super_owner = i.user.id == SUPER_OWNER_ID

    if not (is_guild_owner or is_super_owner):
        owner_mention = i.guild.owner.mention if i.guild.owner else "_Inconnu_"
        denied_view = LayoutView(timeout=None)
        denied_view.add_item(v2_container(
            v2_title("⛔ Accès Refusé", level=2),
            v2_body(
                "**Cette commande est réservée au fondateur du serveur.**\n\n"
                f"👑 Fondateur : {owner_mention}"
            ),
            v2_divider(),
            v2_subtitle("Seul le propriétaire du serveur peut configurer le bot · Sécurité"),
            color=Palette.DANGER,
        ))
        return await i.followup.send(view=denied_view, ephemeral=True)

    # Vérification anti-spam (rapide, en RAM)
    ok, msg = await security_check(i, "configure")
    if not ok:
        return await i.followup.send(msg, ephemeral=True)

    # Log l'acces - en best-effort, pas bloquant
    try:
        await log_security_event(i.guild.id, i.user.id, "CONFIG_ACCESS", "Ouverture du panneau de configuration")
    except Exception as ex:
        print(f"[CONFIGURE] log_security_event echoue: {ex}")

    try:
        v = MainPanelV2(i.user, i.guild)
        # L'interaction est déjà acquittée (defer anti-429 plus haut) : on ne
        # peut pas passer par render_to(), on charge donc le résumé d'état à la
        # main avant l'envoi. refresh() est fail-open, il ne peut pas empêcher
        # l'ouverture du panneau.
        await v.refresh()
        await i.followup.send(view=v, ephemeral=True)
    except Exception as ex:
        print(f"[CONFIGURE] erreur build/send MainPanelV2: {ex}")
        import traceback
        traceback.print_exc()
        try:
            await i.followup.send(
                f"❌ Erreur lors de l'ouverture du panneau : `{type(ex).__name__}: {ex}`",
                ephemeral=True,
            )
        except Exception:
            pass

