async def check_mod_perm(i, cmd_key):
    """Vérifie si l'utilisateur a la permission pour cette commande de modération"""
    c = await cfg(i.guild.id)
    role_id = c.get(cmd_key, 0)
    
    # Admins et owner ont toujours accès
    if i.user.guild_permissions.administrator or i.user.id == i.guild.owner_id:
        return True
    
    # Découplé (audit admin) : l'immunité exempte des FILTRES anti-spam/liens, elle ne
    # confère PLUS de pouvoir de modération. La permission mod dérive UNIQUEMENT de
    # admin Discord / owner / rôle mod configuré (sinon un VIP immunisé pour poster des
    # liens pouvait warn/mute/kick — escalade de privilège non voulue).
    # Vérifier si l'utilisateur a le rôle configuré
    if role_id:
        role = i.guild.get_role(role_id)
        if role and role in i.user.roles:
            return True
    
    return False

# ═══════════════════════════════════════════════════════════════════════════════
#                              🧹 CLEAR / PURGE  (staff, rôle configurable)
# ═══════════════════════════════════════════════════════════════════════════════
# owner 2026-07-01 : commande staff pour vider un salon. « clear N » ou « clear tout »,
# SANS recréer/cloner le salon (on purge le MÊME salon). Prend TOUS les messages en compte :
# discord.py purge(bulk=True) fait du BULK pour les < 14 jours (optimal) et bascule en
# suppression UN-PAR-UN pour les > 14 jours (limite API Discord — incontournable). Permission
# via `mod_clear_role` (customisable dans /configure → Modération), admin/owner toujours OK.
_clear_tasks: set = set()  # réfs aux purges « tout » en tâche de fond (anti-GC)


async def _do_clear(ch, limit, moderator) -> int:
    """Purge le salon (bulk < 14j + individuel > 14j). limit=None → TOUT. Retourne le nombre
    supprimé, -1 si permission manquante, -2 sur autre erreur. FAIL-SAFE."""
    try:
        deleted = await ch.purge(
            limit=limit, bulk=True,
            reason=f"/mod clear par {moderator} ({getattr(moderator, 'id', '?')})")
        return len(deleted)
    except discord.Forbidden:
        return -1
    except Exception as ex:
        print(f"[_do_clear] {ex}")
        return -2


async def _clear_audit_log(guild, ch, moderator, deleted: int, limit) -> bool:
    """Trace la purge dans le salon de logs mod (mod_log_channel) — sink fiable même si la purge
    « tout » dépasse la fenêtre d'interaction de 15 min. Retourne True si posté. FAIL-SAFE."""
    try:
        c = await cfg(guild.id)
        lch = guild.get_channel(int(c.get('mod_log_channel', 0) or 0))
        if lch is None:
            return False
        scope = "tout le salon" if limit is None else f"{limit} demandé(s)"
        e = discord.Embed(
            title="🧹 Clear (purge)",
            description=(f"{getattr(moderator, 'mention', moderator)} a vidé {ch.mention}\n"
                         f"**{deleted}** message(s) supprimé(s) · portée : {scope}"),
            color=0xED4245, timestamp=now())
        try:
            e.set_footer(text=f"Mod: {moderator} · {getattr(moderator, 'id', '?')}")
        except Exception:
            pass
        await lch.send(embed=e, allowed_mentions=discord.AllowedMentions.none())
        return True
    except Exception as ex:
        print(f"[_clear_audit_log] {ex}")
        return False


async def _run_clear_and_report(guild, ch, limit, moderator) -> int:
    deleted = await _do_clear(ch, limit, moderator)
    if deleted >= 0:
        posted = await _clear_audit_log(guild, ch, moderator, deleted, limit)
        # Purge « tout » en tâche de fond SANS salon de logs configuré → confirmation minimale
        # dans le salon vidé (auto-supprimée), sinon le mod n'a aucun retour de fin.
        if not posted and limit is None:
            try:
                await ch.send(f"🧹 Salon vidé — **{deleted}** message(s) supprimé(s).",
                              delete_after=30, allowed_mentions=discord.AllowedMentions.none())
            except Exception:
                pass
    return deleted


class ClearAllConfirmView(discord.ui.View):
    """Confirmation « tout supprimer » (destructif/irréversible) — auteur uniquement, 60 s."""
    def __init__(self, user_id: int, channel_id: int):
        super().__init__(timeout=60)
        self.user_id = int(user_id)
        self.channel_id = int(channel_id)

    @discord.ui.button(label="🗑️ Tout supprimer", style=discord.ButtonStyle.danger)
    async def _confirm(self, i: discord.Interaction, b: discord.ui.Button):
        if i.user.id != self.user_id:
            return await i.response.send_message("❌ Ce n'est pas ta confirmation.", ephemeral=True)
        if not await check_mod_perm(i, 'mod_clear_role'):
            return await i.response.send_message("❌ Permission requise.", ephemeral=True)
        ch = i.guild.get_channel(self.channel_id) if i.guild else None
        if ch is None:
            return await i.response.edit_message(content="❌ Salon introuvable.", view=None)
        me = i.guild.me
        if not ch.permissions_for(me).manage_messages:
            return await i.response.edit_message(
                content="❌ Il me manque « Gérer les messages » ici.", view=None)
        await i.response.edit_message(
            content=(f"🧹 Suppression de **tous** les messages de {ch.mention} lancée…\n"
                     f"_S'il y a beaucoup d'anciens messages (> 14 j), ça se fait un par un et peut "
                     f"prendre du temps. Le résultat s'affichera dans le salon de logs de modération._"),
            view=None)
        t = asyncio.create_task(_run_clear_and_report(i.guild, ch, None, i.user))
        _clear_tasks.add(t)
        t.add_done_callback(_clear_tasks.discard)

    @discord.ui.button(label="Annuler", style=discord.ButtonStyle.secondary)
    async def _cancel(self, i: discord.Interaction, b: discord.ui.Button):
        if i.user.id != self.user_id:
            return await i.response.send_message("❌", ephemeral=True)
        await i.response.edit_message(content="✋ Annulé — rien n'a été supprimé.", view=None)


@mod_group.command(
    name="clear",
    description="🧹 Vider le salon : tout, ou un nombre précis (sans recréer le salon)")
@app_commands.describe(
    nombre="Nombre de messages à supprimer. Laisse VIDE pour tout supprimer (avec confirmation).")
async def mod_clear(i: discord.Interaction,
                    nombre: Optional[app_commands.Range[int, 1, 100000]] = None):
    if i.guild is None:
        return await i.response.send_message("❌ Serveur uniquement.", ephemeral=True)
    if not await check_mod_perm(i, 'mod_clear_role'):
        return await i.response.send_message(
            "❌ Vous n'avez pas la permission pour `/mod clear`.", ephemeral=True)
    ch = i.channel
    if not isinstance(ch, (discord.TextChannel, discord.Thread, discord.VoiceChannel)):
        return await i.response.send_message(
            "❌ À utiliser dans un salon texte, un fil, ou le chat d'un salon vocal.", ephemeral=True)
    perms = ch.permissions_for(i.guild.me)
    if not (perms.manage_messages and perms.read_message_history):
        return await i.response.send_message(
            "❌ Il me manque « Gérer les messages » et/ou « Voir l'historique » dans ce salon.",
            ephemeral=True)
    # CLEAR TOUT → confirmation (destructif, irréversible).
    if nombre is None:
        return await i.response.send_message(
            f"⚠️ **Supprimer TOUS les messages** de {ch.mention} ?\n"
            f"_Tous les messages seront effacés (les > 14 j un par un si besoin). Le salon **n'est "
            f"pas** recréé/rafraîchi. Action **irréversible**._",
            view=ClearAllConfirmView(i.user.id, ch.id), ephemeral=True)
    # CLEAR N → direct.
    await i.response.defer(ephemeral=True)
    deleted = await _run_clear_and_report(i.guild, ch, int(nombre), i.user)
    if deleted == -1:
        msg = "❌ Permission « Gérer les messages » manquante."
    elif deleted < 0:
        msg = "❌ Erreur pendant la suppression (réessaie)."
    else:
        msg = f"✅ **{deleted}** message(s) supprimé(s) dans {ch.mention}."
    try:
        await i.followup.send(msg, ephemeral=True)
    except Exception:
        pass


