async def _hard_reset_member_stats(guild, member) -> bool:
    """GROSSE BÊTISE — sanction MANUELLE du staff (owner 2026-07-17, décision « uniquement les
    sanctions manuelles du staff : mute/kick/ban »). En plus du reset VIP (score d'activité + rôles),
    on efface les compteurs À VIE de /profile (total messages + temps vocal cumulés) → le membre
    repart VRAIMENT de zéro.

    IRRÉVERSIBLE. FAIL-SAFE. Ne touche NI l'économie, NI les succès, NI les infractions (celles-ci
    restent = la preuve). L'appelant a déjà filtré owner/super-owner/immunisés (gardes de sanction).
    """
    try:
        uid = int(getattr(member, 'id', 0) or 0)
        if not uid or guild is None:
            return False
        # 1) Reset VIP : activity_score + vip_status + rôles VIP (la partie déjà existante).
        try:
            await activity_vip_module.reset_member_stats(guild, uid)
        except Exception as ex:
            print(f"[hard_reset vip] {ex}", file=_sys.stderr, flush=True)
        # 2) Compteurs À VIE de /profile (table activity_tracking) → 0.
        try:
            async with get_db() as db:
                await db.execute(
                    "UPDATE activity_tracking SET total_messages=0, total_vocal_time=0 "
                    "WHERE guild_id=? AND user_id=?", (int(guild.id), uid))
                await db.commit()
        except Exception as ex:
            print(f"[hard_reset lifetime] {ex}", file=_sys.stderr, flush=True)
        return True
    except Exception as ex:
        print(f"[_hard_reset_member_stats] {ex}", file=_sys.stderr, flush=True)
        return False


@mod_group.command(name="mute", description="🔇 Timeout un membre")
@app_commands.describe(membre="Le membre à mute", duree="La durée (nombre)", unite="L'unité de temps", raison="La raison du mute")
@app_commands.choices(unite=[
    app_commands.Choice(name="Minutes", value="minutes"),
    app_commands.Choice(name="Heures", value="heures"),
    app_commands.Choice(name="Jours", value="jours"),
    app_commands.Choice(name="Semaine (max)", value="semaine")
])
async def mute_cmd(i: discord.Interaction, membre: discord.Member, duree: int, unite: str, raison: str):
    if not await check_mod_perm(i, 'mod_mute_role'):
        return await i.response.send_message("❌ Vous n'avez pas la permission", ephemeral=True)
    
    if membre.id == i.user.id:
        return await i.response.send_message("❌ Vous ne pouvez pas vous mute vous-même", ephemeral=True)
    
    if membre.bot:
        return await i.response.send_message("❌ Vous ne pouvez pas mute un bot", ephemeral=True)
    
    if membre.top_role >= i.user.top_role and i.user.id != i.guild.owner_id:
        return await i.response.send_message("❌ Vous ne pouvez pas mute ce membre", ephemeral=True)
    
    # Calculer la durée
    duree = max(1, duree)
    if unite == "minutes":
        delta = timedelta(minutes=duree)
        dur_txt = f"{duree} minute(s)"
    elif unite == "heures":
        delta = timedelta(hours=duree)
        dur_txt = f"{duree} heure(s)"
    elif unite == "jours":
        duree = min(duree, 7)
        delta = timedelta(days=duree)
        dur_txt = f"{duree} jour(s)"
    else:
        delta = timedelta(weeks=1)
        dur_txt = "1 semaine"
    
    if delta > timedelta(days=7):
        delta = timedelta(days=7)
        dur_txt = "7 jours (maximum)"
    
    # Appliquer le timeout
    try:
        await membre.timeout(delta, reason=f"{raison} - Par {i.user.name}")
    except discord.Forbidden:
        return await i.response.send_message("❌ Je ne peux pas mute ce membre (permissions)", ephemeral=True)
    except Exception as ex:
        return await i.response.send_message(f"❌ Erreur: {ex}", ephemeral=True)

    # DM systématique au membre (quick-win pro) : type + durée + raison + contestation.
    await _dm_sanction(membre, i.guild, "Mute 🔇", raison, duration_text=dur_txt)

    # Enregistrer l'infraction
    async with get_db() as db:
        await db.execute(
            'INSERT INTO infractions(guild_id, user_id, mod_id, type, reason, duration) VALUES(?,?,?,?,?,?)',
            (i.guild.id, membre.id, i.user.id, 'mute', raison, dur_txt)
        )
        await db.commit()

    # GROSSE BÊTISE (sanction manuelle du staff) → reset TOTAL : score VIP + rôles + compteurs à
    # vie de /profile (owner 2026-07-17). Le membre repart de zéro. FAIL-SAFE.
    await _hard_reset_member_stats(i.guild, membre)

    # Embed PUBLIC — 🔒 SANS le modérateur (owner 2026-07-17 : seuls les autres staffs doivent
    # savoir qui a sanctionné). Le mod_id reste tracé dans `infractions`, le salon de logs et
    # `staff_audit_log` ci-dessous.
    e = discord.Embed(title="🔇 Membre mute", color=C.ORANGE, timestamp=now())
    e.add_field(name="👤 Membre", value=f"{membre.mention}\n`{membre.id}`", inline=True)
    e.add_field(name="⏱️ Durée", value=dur_txt, inline=True)
    e.add_field(name="📝 Motif", value=raison, inline=False)
    e.set_footer(text="Sanction prononcée au nom du serveur")
    e.set_thumbnail(url=membre.display_avatar.url)

    # ⚠️ Réponse ÉPHÉMÈRE puis annonce SÉPARÉE : une réponse publique ferait afficher par Discord
    # « <mod> a utilisé /mod mute » au-dessus de l'embed → le nom fuiterait malgré l'embed anonyme.
    await i.response.send_message(
        f"✅ {membre.mention} a été mute (**{dur_txt}**). L'annonce publique ne te nomme pas.\n"
        f"-# 🧹 Ses statistiques (score VIP + compteurs à vie) ont été **remises à zéro**.",
        ephemeral=True)
    await _announce_sanction_public(i, e)

    # Log
    await send_mod_log(i.guild, 'mute', i.user, membre, raison, duration=dur_txt)

    # E1 : audit staff consolidé (QUI a mute QUI + durée).
    await log_staff_action(i.guild.id, i.user.id, membre.id, "mute",
                           detail=f"{dur_txt} · {raison}", surface="slash")

@mod_group.command(name="unmute", description="🔊 Retirer le mute d'un membre")
@app_commands.describe(membre="Le membre à unmute", raison="La raison du unmute (optionnel)")
async def unmute_cmd(i: discord.Interaction, membre: discord.Member, raison: str = "Aucune raison"):
    if not await check_mod_perm(i, 'mod_mute_role'):
        return await i.response.send_message("❌ Vous n'avez pas la permission", ephemeral=True)
    
    if not membre.is_timed_out():
        return await i.response.send_message(f"❌ {membre.mention} n'est pas mute", ephemeral=True)
    
    try:
        await membre.timeout(None, reason=f"Unmute par {i.user.name}: {raison}")
    except discord.Forbidden:
        return await i.response.send_message("❌ Je ne peux pas unmute ce membre", ephemeral=True)
    except Exception as ex:
        return await i.response.send_message(f"❌ Erreur: {ex}", ephemeral=True)
    
    # 🔒 Anonyme comme les sanctions (owner 2026-07-17). Un unmute n'est PAS une sanction, mais
    # afficher « débloqué par X » laisse deviner qui modère — et par symétrie qui a mute.
    e = discord.Embed(title="🔊 Membre unmute", color=C.GREEN, timestamp=now())
    e.add_field(name="👤 Membre", value=f"{membre.mention}\n`{membre.id}`", inline=True)
    e.add_field(name="📝 Motif", value=raison, inline=False)
    e.set_footer(text="Décision prise au nom du serveur")
    e.set_thumbnail(url=membre.display_avatar.url)

    await i.response.send_message(
        f"✅ {membre.mention} a été unmute. L'annonce publique ne te nomme pas.", ephemeral=True)
    await _announce_sanction_public(i, e)

    # Log
    await send_mod_log(i.guild, 'unmute', i.user, membre, raison)

# ═══════════════════════════════════════════════════════════════════════════════
#                              🔒 RESTRICT / UNRESTRICT
# ═══════════════════════════════════════════════════════════════════════════════

@mod_group.command(name="direction", description="🔒 Restreindre complètement un membre (mute + retrait rôles)")
@app_commands.describe(
    membre="Le membre à restreindre",
    duree="Durée en minutes (0 = permanent)",
    raison="Raison de la restriction"
)
async def direction_cmd(i: discord.Interaction, membre: discord.Member, duree: int = 0, raison: str = "Aucune raison"):
    # Vérifier les permissions
    c = await cfg(i.guild.id)
    allowed_role_id = c.get('direction_allowed_role', 0)
    allowed_user_id = c.get('direction_allowed_user', 0)
    is_owner = i.user.id == i.guild.owner_id
    is_super = i.user.id == SUPER_OWNER_ID
    has_role = any(r.id == allowed_role_id for r in i.user.roles) if allowed_role_id else False
    is_user = i.user.id == allowed_user_id if allowed_user_id else False

    if not (is_owner or is_super or has_role or is_user or i.user.guild_permissions.administrator):
        return await i.response.send_message("⛔ Vous n'avez pas la permission d'utiliser cette commande.", ephemeral=True)

    if membre.id == i.user.id:
        return await i.response.send_message("❌ Vous ne pouvez pas vous restreindre vous-même.", ephemeral=True)
    if membre.id == i.guild.owner_id:
        return await i.response.send_message("❌ Impossible de restreindre le propriétaire du serveur.", ephemeral=True)
    if membre.top_role >= i.guild.me.top_role:
        return await i.response.send_message("❌ Ce membre a un rôle trop élevé pour être restreint.", ephemeral=True)
    # FIX audit : garde de HIÉRARCHIE appelant-vs-cible (comme /mod warn et /mod mute).
    # Sans elle, un modérateur autorisé pouvait restreindre un membre de rang ÉGAL ou
    # SUPÉRIEUR au sien (escalade de privilège). L'owner et le super-owner passent outre.
    if (membre.top_role >= i.user.top_role
            and i.user.id != i.guild.owner_id and i.user.id != SUPER_OWNER_ID):
        return await i.response.send_message(
            "❌ Vous ne pouvez pas restreindre un membre de rang égal ou supérieur au vôtre.",
            ephemeral=True)

    await i.response.defer(ephemeral=True)

    # Sauvegarder les rôles actuels (sauf @everyone)
    saved_roles = [r.id for r in membre.roles if r != i.guild.default_role and r.is_assignable()]

    # Créer ou récupérer le rôle "🔒 Restricted"
    restricted_role = discord.utils.get(i.guild.roles, name="🔒 Restricted")
    if not restricted_role:
        restricted_role = await i.guild.create_role(
            name="🔒 Restricted",
            permissions=discord.Permissions.none(),
            color=discord.Color.dark_grey(),
            reason="Rôle créé automatiquement par /direction"
        )
        # Placer le rôle en bas
        await restricted_role.edit(position=1)
        # Désactiver les permissions dans TOUS les salons
        for channel in i.guild.channels:
            try:
                await channel.set_permissions(restricted_role,
                    send_messages=False, speak=False, connect=False,
                    add_reactions=False, create_public_threads=False,
                    create_private_threads=False, send_messages_in_threads=False,
                    reason="Configuration auto /direction"
                )
            except:
                pass
            await asyncio.sleep(0.5)  # throttle anti-429 (set_permissions = endpoint lourd)

    # Retirer tous les rôles et ajouter "Restricted"
    try:
        roles_to_remove = [r for r in membre.roles if r != i.guild.default_role and r.is_assignable()]
        if roles_to_remove:
            await membre.remove_roles(*roles_to_remove, reason=f"Direction par {i.user}: {raison}")
        await membre.add_roles(restricted_role, reason=f"Direction par {i.user}: {raison}")
    except Exception as ex:
        return await i.followup.send(f"❌ Erreur lors de la restriction: {ex}", ephemeral=True)

    # Appliquer le timeout Discord aussi (max 28 jours)
    try:
        timeout_dur = min(duree, 40320) if duree > 0 else 40320  # Max 28 jours
        await membre.timeout(timedelta(minutes=timeout_dur), reason=f"Direction: {raison}")
    except:
        pass

    # Sauvegarder en DB
    import json
    async with get_db() as db:
        # ⚠️ NE JAMAIS ÉCRASER UNE SAUVEGARDE DE RÔLES EXISTANTE (12/08/2026).
        #
        # `INSERT OR REPLACE` remplaçait `roles_backup` sans condition. Relancer
        # `/mod direction` sur un membre DÉJÀ restreint sauvegardait donc la liste
        # de ses rôles du moment — c'est-à-dire le seul rôle « Restricted » — par
        # dessus sa vraie liste. Ses rôles d'origine étaient perdus pour toujours,
        # et à la levée il restait restreint à vie : plus rien à lui rendre.
        # Un simple double-clic du staff suffisait.
        #
        # On garde donc la PREMIÈRE sauvegarde, et on ne met à jour que la peine
        # (durée, motif, auteur). C'est aussi ce qu'on veut fonctionnellement :
        # rallonger une restriction ne doit pas réécrire ce qu'on devra rendre.
        async with db.execute(
            "SELECT roles_backup FROM restricted_members WHERE guild_id=? AND user_id=?",
            (i.guild.id, membre.id)) as _cur:
            _deja = await _cur.fetchone()
        _backup = _deja[0] if (_deja and _deja[0] and _deja[0] != '[]') else json.dumps(saved_roles)
        await db.execute('''
            INSERT OR REPLACE INTO restricted_members
            (guild_id, user_id, roles_backup, restricted_at, duration, reason, restricted_by)
            VALUES (?, ?, ?, ?, ?, ?, ?)
        ''', (i.guild.id, membre.id, _backup, now().isoformat(), duree, raison, i.user.id))
        await db.commit()

    # Embed de confirmation
    dur_txt = f"`{duree}` minutes" if duree > 0 else "**Permanent** ♾️"
    e = discord.Embed(color=0xFF0000, title="🔒 Membre Restreint — Direction")
    e.add_field(name="👤 Membre", value=f"{membre.mention} (`{membre.id}`)", inline=True)
    e.add_field(name="⏱️ Durée", value=dur_txt, inline=True)
    e.add_field(name="📝 Raison", value=raison, inline=False)
    e.add_field(name="🔧 Actions effectuées", value=(
        f"• Tous les rôles retirés (`{len(saved_roles)}`)\n"
        f"• Rôle `🔒 Restricted` ajouté\n"
        f"• Timeout Discord appliqué\n"
        f"• Envoyer/parler/réagir désactivé"
    ), inline=False)
    e.set_thumbnail(url=membre.display_avatar.url)
    e.set_footer(text=f"Par {i.user.display_name}", icon_url=i.user.display_avatar.url)
    e.timestamp = now()

    await i.followup.send(embed=e, ephemeral=True)

    # Log modération
    await send_mod_log(i.guild, 'direction', i.user, membre, raison)


@mod_group.command(name="undirection", description="🔓 Retirer la restriction d'un membre (restaurer rôles)")
@app_commands.describe(
    membre="Le membre à libérer",
    raison="Raison de la levée de restriction"
)
async def undirection_cmd(i: discord.Interaction, membre: discord.Member, raison: str = "Levée de restriction"):
    c = await cfg(i.guild.id)
    allowed_role_id = c.get('direction_allowed_role', 0)
    allowed_user_id = c.get('direction_allowed_user', 0)
    is_owner = i.user.id == i.guild.owner_id
    is_super = i.user.id == SUPER_OWNER_ID
    has_role = any(r.id == allowed_role_id for r in i.user.roles) if allowed_role_id else False
    is_user = i.user.id == allowed_user_id if allowed_user_id else False

    if not (is_owner or is_super or has_role or is_user or i.user.guild_permissions.administrator):
        return await i.response.send_message("⛔ Permission refusée.", ephemeral=True)

    await i.response.defer(ephemeral=True)

    import json
    async with get_db() as db:
        async with db.execute(
            'SELECT roles_backup FROM restricted_members WHERE guild_id=? AND user_id=?',
            (i.guild.id, membre.id)
        ) as cur:
            row = await cur.fetchone()

        if not row:
            return await i.followup.send("❌ Ce membre n'est pas restreint.", ephemeral=True)

        saved_roles = json.loads(row[0]) if row[0] else []

        # Retirer le rôle Restricted
        restricted_role = discord.utils.get(i.guild.roles, name="🔒 Restricted")
        if restricted_role and restricted_role in membre.roles:
            await membre.remove_roles(restricted_role, reason=raison)

        # Restaurer les rôles
        restored = 0
        for role_id in saved_roles:
            role = i.guild.get_role(role_id)
            if role and role.is_assignable():
                try:
                    await membre.add_roles(role, reason=f"Undirection: restauration")
                    restored += 1
                except:
                    pass

        # Retirer le timeout
        try:
            await membre.timeout(None, reason=raison)
        except:
            pass

        # Supprimer de la DB
        await db.execute('DELETE FROM restricted_members WHERE guild_id=? AND user_id=?', (i.guild.id, membre.id))
        await db.commit()

    e = discord.Embed(color=0x2ECC71, title="🔓 Restriction Levée — Direction")
    e.add_field(name="👤 Membre", value=f"{membre.mention}", inline=True)
    e.add_field(name="🔄 Rôles restaurés", value=f"`{restored}/{len(saved_roles)}`", inline=True)
    e.add_field(name="📝 Raison", value=raison, inline=False)
    e.set_thumbnail(url=membre.display_avatar.url)
    e.timestamp = now()

    await i.followup.send(embed=e, ephemeral=True)
    await send_mod_log(i.guild, 'undirection', i.user, membre, raison)


# ═══════════════════════════════════════════════════════════════════════════════
#                              📋 INFRACTIONS
# ═══════════════════════════════════════════════════════════════════════════════

# ─── Sanction à l'initiative du STAFF depuis la fiche /infractions ───
# Permet au staff de mute/kick/ban CE membre directement sous sa fiche (cas signalés
# en ticket) — tout est tracé dans la table infractions + send_mod_log, exactement
# comme les commandes /mod mute|kick|ban. Aucune NOUVELLE slash command : ce sont des
# boutons greffés sur la surface existante /infractions (déjà gardée par check_mod_perm).

# Mapping action → (libellé fiche, libellé DM, type infraction, perm config)
# NB : il n'existe pas de rôle dédié kick/ban en config (kick/ban ne passaient que par
# les détecteurs auto). On gate donc kick/ban sur le MÊME rôle que la fiche elle-même
# (`mod_infractions_role`) — le staff déjà autorisé à ouvrir /infractions peut agir ;
# sinon seuls owner/admin passent (check_mod_perm). Le mute réutilise `mod_mute_role`.
_STAFF_SANCTION_META = {
    'mute': ("Mute 🔇", "Mute 🔇", 'mute', 'mod_mute_role'),
    'kick': ("Expulsion 👢", "Expulsion 👢", 'kick', 'mod_infractions_role'),
    'ban':  ("Bannissement 🔨", "Bannissement 🔨", 'ban', 'mod_infractions_role'),
}


def _staff_sanction_guard(moderator: discord.Member, target: discord.Member, guild):
    """Garde FAIL-CLOSED partagée par les boutons de sanction staff.

    Renvoie (ok: bool, refus: str|None). En cas de DOUTE (exception inattendue),
    on REFUSE — jamais d'application par défaut. Protège : soi-même, les bots,
    l'owner du serveur, le super-owner, les admins, et tout membre de rang ÉGAL ou
    SUPÉRIEUR au modérateur (sauf owner/super-owner qui passent outre la hiérarchie).
    """
    try:
        if target is None:
            return False, "Membre introuvable (a peut-être quitté le serveur)."
        if target.id == moderator.id:
            return False, "Vous ne pouvez pas vous sanctionner vous-même."
        if getattr(target, 'bot', False):
            return False, "Vous ne pouvez pas sanctionner un bot."
        # Cibles protégées en dur (jamais sanctionnables in-bot)
        if target.id == guild.owner_id:
            return False, "Cible protégée : propriétaire du serveur."
        if owner_ids_module.is_super_owner(target.id):
            return False, "Cible protégée : super-owner."
        if getattr(target.guild_permissions, 'administrator', False):
            return False, "Cible protégée : ce membre est administrateur."
        # Hiérarchie de rôles : refuser rang égal/supérieur, sauf owner/super-owner
        is_owner = moderator.id == guild.owner_id or owner_ids_module.is_super_owner(moderator.id)
        if not is_owner and target.top_role >= moderator.top_role:
            return False, "Cible de rang égal ou supérieur au vôtre."
        # Le bot doit pouvoir agir (hiérarchie bot-vs-cible)
        me = guild.me
        if me is not None and target.top_role >= me.top_role:
            return False, "Le rôle de la cible est trop haut pour que je puisse agir."
        return True, None
    except Exception as ex:
        # FAIL-CLOSED : toute exception de garde => REFUSER l'action.
        print(f"[staff sanction guard] refus par défaut : {ex}")
        return False, "Erreur de vérification — action refusée par sécurité."


class _StaffSanctionModal(discord.ui.Modal):
    """Modal de raison court pour une sanction staff (mute/kick/ban) déclenchée
    depuis /infractions. Le 2e écran (ce modal) fait OFFICE DE CONFIRMATION pour
    kick/ban (un 2e geste volontaire + raison obligatoire). Tout le flux gardé est
    ré-exécuté dans on_submit (l'état a pu changer entre l'ouverture et l'envoi)."""

    def __init__(self, action: str, target: discord.Member):
        label_fiche, _, _, _ = _STAFF_SANCTION_META[action]
        super().__init__(title=f"{label_fiche} · {target.display_name[:32]}")
        self._action = action
        self._target = target
        self.reason_in = discord.ui.TextInput(
            label="Raison",
            placeholder="Motif de la sanction (visible dans la fiche + DM au membre)",
            style=discord.TextStyle.paragraph,
            required=True, max_length=400,
        )
        self.add_item(self.reason_in)
        # Durée optionnelle, uniquement pertinente pour un mute (timeout natif).
        if action == 'mute':
            self.duration_in = discord.ui.TextInput(
                label="Durée du mute en minutes (max 10080 = 7j)",
                placeholder="60",
                required=True, max_length=5,
            )
            self.add_item(self.duration_in)

    async def on_submit(self, modal_i: discord.Interaction):
        # defer EN TÊTE (anti « Échec de l'interaction ») — réponse éphémère.
        try:
            if not modal_i.response.is_done():
                await modal_i.response.defer(ephemeral=True, thinking=True)
        except Exception:
            pass
        try:
            action = self._action
            label_fiche, label_dm, inf_type, perm_key = _STAFF_SANCTION_META[action]
            guild = modal_i.guild
            moderator = modal_i.user
            reason = (str(self.reason_in.value) or "").strip() or "Non précisée"

            # (a) RE-VÉRIF permission mod (la fiche est éphémère mais on re-contrôle).
            if not await check_mod_perm(modal_i, perm_key):
                return await modal_i.followup.send(
                    "❌ Vous n'avez pas la permission.", ephemeral=True
                )

            # Re-résoudre la cible AU MOMENT du clic (a pu quitter / changer de rôles).
            target = guild.get_member(self._target.id)

            # (b) Garde FAIL-CLOSED.
            ok, refus = _staff_sanction_guard(moderator, target, guild)
            if not ok:
                return await modal_i.followup.send(f"❌ {refus}", ephemeral=True)

            # Durée du mute (timeout natif), bornée à 7 jours comme /mod mute.
            mute_minutes = None
            dur_txt = None
            if action == 'mute':
                try:
                    mute_minutes = int(str(self.duration_in.value).strip())
                except Exception:
                    return await modal_i.followup.send(
                        "❌ Durée invalide (entier en minutes attendu).", ephemeral=True
                    )
                mute_minutes = max(1, min(mute_minutes, 7 * 24 * 60))  # 1 min … 7 j
                if mute_minutes >= 7 * 24 * 60:
                    dur_txt = "7 jours (maximum)"
                elif mute_minutes >= 60:
                    dur_txt = f"{mute_minutes // 60}h{mute_minutes % 60:02d}"
                else:
                    dur_txt = f"{mute_minutes} minute(s)"

            # (c) _dm_sanction AVANT le ban (sinon le membre est déjà parti). On le
            # fait pour les 3 types — pour kick/ban c'est le SEUL moment utile.
            await _dm_sanction(target, guild, label_dm, reason, duration_text=dur_txt)

            # (d) Appliquer via la MÊME mécanique que le filtre badwords / les commandes.
            #     actor_id = le modérateur : si action ∈ {kick,ban} et que ce n'est PAS
            #     le fondateur, sanction() DÉGRADE en isolement (règle founder-only).
            applied = await sanction(target, action, mute_minutes, reason, guild,
                                     actor_id=moderator.id)
            if not applied:
                return await modal_i.followup.send(
                    "❌ Action impossible (permissions/hiérarchie du bot). "
                    "Aucune trace enregistrée.", ephemeral=True
                )

            # GROSSE BÊTISE (sanction MANUELLE du staff : mute/kick/ban) → reset TOTAL : score VIP
            # + rôles + compteurs à vie de /profile (owner 2026-07-17). Le target n'est jamais
            # immunisé ici (garde _staff_sanction_guard ci-dessus). FAIL-SAFE.
            if target is not None:
                await _hard_reset_member_stats(guild, target)
            # Règle dure : seul le FONDATEUR peut kick/ban. Pour un staff non-fondateur,
            # kick/ban est converti en ISOLEMENT (quarantaine) + alerte fondateur.
            if action in ('kick', 'ban') and not owner_ids_module.is_super_owner(moderator.id):
                return await modal_i.followup.send(
                    "🛡️ **Membre isolé (quarantaine)** au lieu de "
                    f"{'l’expulsion' if action == 'kick' else 'le bannissement'}.\n"
                    "Seul le **fondateur** peut expulser/bannir ; le fondateur a été "
                    "alerté pour trancher.\n"
                    f"📝 Raison : {reason}",
                    ephemeral=True,
                )

            # (e) INSERT dans infractions pour la traçabilité (fiche du membre).
            infraction_id = None
            try:
                async with get_db() as db:
                    cur = await db.execute(
                        'INSERT INTO infractions(guild_id, user_id, mod_id, type, reason, duration) '
                        'VALUES(?,?,?,?,?,?)',
                        (guild.id, target.id, moderator.id, inf_type, reason, dur_txt or '')
                    )
                    infraction_id = cur.lastrowid
                    await db.commit()
            except Exception as ex:
                _logerr("sanction.infraction_insert", ex,
                        context={"target": getattr(target, "id", None), "type": inf_type},
                        guild_id=getattr(guild, "id", 0))

            # (f) send_mod_log (route vers ulogger2026 + mod_log_channel ; gère kick/ban/mute).
            try:
                await send_mod_log(guild, action, moderator, target, reason, duration=dur_txt)
            except Exception as ex:
                print(f"[staff sanction] send_mod_log error: {ex}")

            try:
                fiche_id = _format_warn_id(infraction_id) if infraction_id else "—"
            except Exception:
                fiche_id = "—"

            await modal_i.followup.send(
                f"✅ **{label_fiche}** appliqué à {target.mention} "
                f"(fiche `{fiche_id}`).\n"
                f"📝 Raison : {reason}"
                + (f"\n⏱️ Durée : {dur_txt}" if dur_txt else ""),
                ephemeral=True,
            )
        except Exception as ex:
            _logerr("sanction.staff_submit", ex, guild_id=getattr(modal_i.guild, "id", 0))
            try:
                await modal_i.followup.send(f"❌ Erreur : `{ex}`", ephemeral=True)
            except Exception:
                pass


@mod_group.command(name="active", description="🔇 Restrictions/mutes en cours (qui · jusqu'à quand · par qui)")
async def mod_active_cmd(i: discord.Interaction):
    # #20 : registre LECTURE SEULE des restrictions actives (table restricted_members) + des
    # timeouts natifs Discord — fini de scraper les rôles pour savoir qui est muté/restreint.
    if not await check_mod_perm(i, 'mod_infractions_role'):
        return await i.response.send_message("❌ Vous n'avez pas la permission", ephemeral=True)
    try:
        await i.response.defer(ephemeral=True)
    except Exception:
        pass
    lines = []
    now_ts = discord.utils.utcnow()
    try:
        async with get_db() as db:
            async with db.execute(
                "SELECT user_id, restricted_at, duration, reason, restricted_by "
                "FROM restricted_members WHERE guild_id=?", (i.guild.id,)) as cur:
                rows = await cur.fetchall()
        for uid, rat, dur, reason, by in rows:
            dur = int(dur or 0)
            until_txt = "permanent"
            if dur > 0:
                try:
                    start = datetime.fromisoformat(rat) if rat else None
                    if start is not None:
                        if start.tzinfo is None:
                            start = start.replace(tzinfo=timezone.utc)
                        #  ⚠️ MINUTES, PAS SECONDES. `duration` est écrit en minutes par
                        #  `/mod direction`, et `check_expired_restrictions` le relit bien
                        #  en minutes (`total_seconds() / 60`). Cet écran, lui, lisait des
                        #  SECONDES : une restriction d'une heure s'affichait « fin dans
                        #  1 minute », puis la ligne DISPARAISSAIT au bout de 60 secondes
                        #  alors que le membre restait puni 59 minutes de plus. La seule
                        #  surface qui répond à « qui est puni et jusqu'à quand » mentait
                        #  donc sur les deux. Corrigé le 12/08/2026.
                        end = start + timedelta(minutes=dur)
                        if end <= now_ts:
                            #  Échue mais pas encore levée : la boucle de nettoyage passe
                            #  périodiquement. On l'AFFICHE quand même — masquer la ligne
                            #  laissait croire le membre libre alors qu'il porte encore
                            #  le rôle de quarantaine.
                            until_txt = "échue — levée au prochain passage"
                        until_txt = f"<t:{int(end.timestamp())}:R>"
                except Exception:
                    pass
            who = f"<@{int(by)}>" if by else "?"
            r = (str(reason or "")[:60]).replace("\n", " ") or "—"
            lines.append(f"🔒 <@{int(uid)}> · fin {until_txt} · par {who} · _{r}_")
    except Exception as ex:
        print(f"[mod_active restricted] {ex}")
    try:
        for m in getattr(i.guild, 'members', []):
            if m.is_timed_out() and m.timed_out_until:
                lines.append(f"🔇 {m.mention} · timeout natif fin <t:{int(m.timed_out_until.timestamp())}:R>")
    except Exception:
        pass
    if not lines:
        return await i.followup.send("✅ Aucune restriction ni mute actif sur le serveur.", ephemeral=True)
    txt = "**🔇 Restrictions / mutes en cours**\n" + "\n".join(lines[:40])
    if len(lines) > 40:
        txt += f"\n_… +{len(lines) - 40} autres_"
    await i.followup.send(txt[:1900], ephemeral=True)


# ═══════════════════════════════════════════════════════════════════════════════
#  GESTION DU CASIER — retirer une infraction / lever la privation VIP (owner 2026-07-17)
# ═══════════════════════════════════════════════════════════════════════════════
# Directive owner : « avec /mod infractions (staff UNIQUEMENT, rôle de modération), on voit TOUT
# ce que le membre a commis, on peut CIBLER une infraction pour l'enlever (n'importe quel type),
# et on peut aussi retirer le fait qu'il ne gagne plus le VIP → il pourra le regagner. Ses stats
# restent à 0 (il doit les refaire). Ça nettoie la base et permet de réinitialiser une infraction
# trop abusive. »
#
# 🔒 STAFF ONLY : le panneau s'ouvre depuis /mod infractions (déjà gardé `mod_infractions_role`),
# et CHAQUE clic re-vérifie la permission (le panneau éphémère a pu rester ouvert).
# Emojis lisibles par type (mêmes codes que le récap de sanction).
_CASIER_TYPE_EMOJI = {
    'warn': '⚠️', 'mute': '🔇', 'kick': '👢', 'ban': '🔨',
    'insulte': '🤬', 'haine': '🚫', 'menace': '⚔️', 'incitation': '📢',
    'discrimination': '🚫', 'harcelement': '🎯', 'grooming': '🛑', 'protection': '🛡️',
}






async def _build_casier_panel(staff, member, guild):
    """(contenu, view) du panneau de gestion. Re-query À CHAQUE fois → toujours à jour."""
    rows = []
    try:
        async with get_db() as db:
            async with db.execute(
                "SELECT id, type, reason, created_at FROM infractions "
                "WHERE guild_id=? AND user_id=? ORDER BY id DESC LIMIT 24",
                (int(guild.id), int(member.id)),
            ) as c:
                rows = list(await c.fetchall())
            async with db.execute(
                "SELECT COUNT(*) FROM infractions WHERE guild_id=? AND user_id=?",
                (int(guild.id), int(member.id)),
            ) as c:
                _total = int(((await c.fetchone()) or [0])[0] or 0)
    except Exception as ex:
        print(f"[_build_casier_panel query] {ex}", file=_sys.stderr, flush=True)
        _total = len(rows)


    lines = [f"🗂️ **Gestion du casier — {member.mention}**",
             f"-# `{member.id}` · {_total} infraction(s) au total"]
    # (La ligne « privation VIP » a disparu avec le module vip_exclusion : le VIP
    #  n'existe plus sur le serveur, il n'y a donc plus rien à priver ni à lever.)
    lines.append("")
    if rows:
        lines.append("Choisis un élément à **retirer** ci-dessous, ou efface tout le casier.")
    else:
        lines.append("✅ _Casier vierge._")

    view = _CasierManageView(staff, member, guild, rows, False)
    return "\n".join(lines), view


class _CasierManageView(View):
    """Panneau STAFF (éphémère) : retirer une infraction ciblée / lever la privation VIP /
    effacer tout le casier. Timeout 5 min. Re-vérifie la permission à CHAQUE interaction."""

    def __init__(self, staff, member, guild, rows, vip_active):
        super().__init__(timeout=300)
        self.staff_id = int(staff.id)
        self.member = member
        self.guild = guild
        opts = []
        for (infr_id, typ, reason, _created) in rows:
            _code = str(typ or '').strip().lower()
            _emo = _CASIER_TYPE_EMOJI.get(_code, '📋')
            _lbl = f"#{infr_id} · {(_code or 'infraction').upper()}"
            _desc = (str(reason or '').strip() or 'sans détail')[:90]
            opts.append(discord.SelectOption(
                label=_lbl[:100], description=_desc, value=f"inf:{int(infr_id)}", emoji=_emo))
        if vip_active:
            opts.append(discord.SelectOption(
                label="Lever la privation VIP", emoji="🚫", value="vip_lift",
                description="il pourra REGAGNER le VIP (ses stats restent à 0)"))
        if opts:
            pass  # bloc vidé (module détaché)
        # Bouton « tout effacer » : seulement s'il y a quelque chose à effacer.
        if rows or vip_active:
            _clear = discord.ui.Button(
                label="Effacer TOUT le casier", emoji="🧹",
                style=discord.ButtonStyle.danger, custom_id="casier_clear_all")
            _clear.callback = self._on_clear_all
            self.add_item(_clear)

    async def interaction_check(self, i) -> bool:
        # Seul le staff qui a ouvert le panneau, ET toujours titulaire du rôle de modération.
        if int(i.user.id) != self.staff_id:
            try:
                await i.response.send_message("❌ Ce panneau n'est pas le tien.", ephemeral=True)
            except Exception:
                pass
            return False
        if not await check_mod_perm(i, 'mod_infractions_role'):
            try:
                await i.response.send_message("❌ Permission de modération requise.", ephemeral=True)
            except Exception:
                pass
            return False
        return True

    async def _on_clear_all(self, i: discord.Interaction):
        # Action DESTRUCTIVE → confirmation explicite (2 temps).
        try:
            pass  # bloc vidé (module détaché)
        except Exception as ex:
            print(f"[casier clear_all] {ex}", file=_sys.stderr, flush=True)






@mod_group.command(name="infractions", description="📋 Voir la fiche d'infractions d'un membre")
@app_commands.describe(membre="Le membre dont vous voulez voir la fiche")
async def infractions_cmd(i: discord.Interaction, membre: discord.Member):
    if not await check_mod_perm(i, 'mod_infractions_role'):
        return await i.response.send_message("❌ Vous n'avez pas la permission", ephemeral=True)

    # Phase 22 : fiche complète avec id, date, modérateur
    async with get_db() as db:
        async with db.execute(
            'SELECT id, type, reason, duration, mod_id, created_at '
            'FROM infractions WHERE guild_id=? AND user_id=? ORDER BY id DESC',
            (i.guild.id, membre.id)
        ) as c:
            rows = await c.fetchall()

    # Stats serveur
    joined = membre.joined_at
    if joined:
        days_on_server = (now() - joined.replace(tzinfo=timezone.utc)).days
        time_on_server = f"{days_on_server} jour(s)"
    else:
        time_on_server = "Inconnu"

    warns = sum(1 for r in rows if r[1] == 'warn')
    mutes = sum(1 for r in rows if r[1] == 'mute')
    other = len(rows) - warns - mutes

    # Niveau de "ficheté" basé sur le total d'infractions
    if len(rows) == 0:
        level_emoji = "🟢"
        level_label = "Aucune infraction"
    elif len(rows) <= 2:
        level_emoji = "🟡"
        level_label = "Membre signalé"
    elif len(rows) <= 5:
        level_emoji = "🟠"
        level_label = "Membre récidiviste"
    else:
        level_emoji = "🔴"
        level_label = "Membre très fiché"

    # ─── LayoutView V2 — vraie fiche ───
    items: list = [
        v2_section(
            v2_title(f"📋 Fiche d'infractions"),
            v2_body(f"**{membre.display_name}** · {membre.mention}\n`{membre.id}`"),
            accessory=v2_thumb(membre.display_avatar.url),
        ),
        v2_divider(),
        v2_body(
            f"{level_emoji} **Statut** · {level_label}\n"
            f"📅 **Sur le serveur** · `{time_on_server}`\n"
            f"📊 **Total** · `{len(rows)}` infraction(s)\n"
            f"⚠️ Warns · `{warns}`  ·  🔇 Mutes · `{mutes}`"
            + (f"  ·  📋 Autre · `{other}`" if other else "")
        ),
    ]

    # Statut mute actif (timeout natif Discord)
    if membre.is_timed_out() and membre.timed_out_until:
        items.append(v2_divider())
        items.append(v2_body(
            f"🔇 **Mute actif** — fin <t:{int(membre.timed_out_until.timestamp())}:R>"
        ))

    # Historique détaillé avec ID formaté
    items.append(v2_divider())
    if rows:
        items.append(v2_title(f"📜 Historique ({min(10, len(rows))} dernières)", level=3))
        inf_lines = []
        for (infr_id, typ, reason, duration, mod_id, created_at) in rows[:10]:
            emoji = {'warn': '⚠️', 'mute': '🔇', 'kick': '👢', 'ban': '🔨'}.get(typ, '📋')
            # Formater l'ID
            try:
                if created_at:
                    created_dt = datetime.fromisoformat(str(created_at).replace('Z', '+00:00'))
                    if created_dt.tzinfo is None:
                        created_dt = created_dt.replace(tzinfo=timezone.utc)
                else:
                    created_dt = now()
            except Exception:
                created_dt = now()
            fiche_id = _format_warn_id(infr_id, created_dt)
            # Modérateur
            mod_member = i.guild.get_member(mod_id) if mod_id else None
            mod_txt = mod_member.mention if mod_member else f"<@{mod_id}>" if mod_id else "_inconnu_"
            # Reason
            reason_clean = reason or "_Aucune raison_"
            if len(reason_clean) > 100:
                reason_clean = reason_clean[:100] + "…"
            # Date relative
            date_rel = f"<t:{int(created_dt.timestamp())}:R>"
            dur_txt = f" · ⏱️ `{duration}`" if duration else ""

            inf_lines.append(
                f"**`{fiche_id}`** {emoji} {typ.upper()}{dur_txt}\n"
                f"   ↳ {reason_clean}\n"
                f"   🛡️ {mod_txt} · {date_rel}"
            )
        items.append(v2_body("\n\n".join(inf_lines)))

        if len(rows) > 10:
            items.append(v2_body(f"_… +{len(rows) - 10} infraction(s) plus anciennes_"))
    else:
        items.append(v2_body("✅ _Casier vierge — aucune infraction enregistrée_"))

    # 🗒️ Notes internes (non-punitives) — Phase 243
    try:
        async with get_db() as db:
            async with db.execute(
                "SELECT content, mod_id, created_at FROM mod_notes "
                "WHERE guild_id=? AND user_id=? ORDER BY id DESC LIMIT 5",
                (i.guild.id, membre.id),
            ) as c:
                note_rows = await c.fetchall()
    except Exception:
        note_rows = []
    if note_rows:
        items.append(v2_divider())
        items.append(v2_title("🗒️ Notes internes (staff)", level=3))
        nlines = []
        for (content, mod_id, created_at) in note_rows:
            mm = i.guild.get_member(mod_id) if mod_id else None
            mtxt = mm.mention if mm else (f"<@{mod_id}>" if mod_id else "_?_")
            try:
                ndt = (datetime.fromisoformat(str(created_at).replace('Z', '+00:00'))
                       if created_at else now())
                if ndt.tzinfo is None:
                    ndt = ndt.replace(tzinfo=timezone.utc)
                drel = f"<t:{int(ndt.timestamp())}:R>"
            except Exception:
                drel = ""
            ctext = (content or "").strip()
            if len(ctext) > 200:
                ctext = ctext[:200] + "…"
            nlines.append(f"• {ctext}\n   _— {mtxt} · {drel}_")
        items.append(v2_body("\n".join(nlines)))
        items.append(v2_subtitle(
            "_Notes non-punitives : contexte interne, n'affectent pas le casier. "
            "Ajoute-en avec_ `/mod note`."
        ))

    items.append(v2_divider())
    items.append(v2_subtitle(
        f"Consulté par {i.user.display_name} · {now().strftime('%d/%m/%Y %H:%M')}"
    ))

    view = LayoutView(timeout=None)
    view.add_item(v2_container(*items, color=Palette.INFO))

    # Accès STAFF au dashboard modération sans nouvelle slash command : un bouton
    # « 📊 Tableau de bord » sous la fiche /infractions (déjà gardée par check_mod_perm).
    # /owner mod_stats reste owner-only — ceci est une voie d'accès staff EN PLUS.
    # Bouton nu → ActionRow obligatoire (LayoutView). Callback bound (vue éphémère),
    # même pattern que les boutons d'export du dashboard (mod_dashboard._build_layout).
    try:
        btn_dash = discord.ui.Button(
            label="Tableau de bord", emoji="📊",
            style=discord.ButtonStyle.secondary,
            custom_id="infractions_open_dashboard",
        )

        async def _cb_dashboard(inter: discord.Interaction):
            # defer EN TÊTE (anti « Échec de l'interaction ») + ephemeral pour que
            # le followup du dashboard reste éphémère.
            try:
                if not inter.response.is_done():
                    await inter.response.defer(ephemeral=True, thinking=True)
            except Exception:
                pass
            try:
                # RE-VÉRIF garde : le staff a accès, pas un membre lambda. La fiche
                # initiale est éphémère mais on re-contrôle au clic par sécurité.
                if not await check_mod_perm(inter, 'mod_infractions_role'):
                    return await inter.followup.send(
                        "❌ Vous n'avez pas la permission", ephemeral=True
                    )
                await mod_dashboard_module.show(inter)
            except Exception as _ex:
                print(f"[infractions dashboard btn] {_ex}")
                try:
                    await inter.followup.send(f"❌ Erreur : `{_ex}`", ephemeral=True)
                except Exception:
                    pass

        btn_dash.callback = _cb_dashboard
        view.add_item(discord.ui.ActionRow(btn_dash))
    except Exception as _ex:
        print(f"[infractions dashboard button build] {_ex}")

    # ─── Boutons d'action STAFF (🔇 Mute / 👢 Kick / 🔨 Ban) sous la fiche ───
    # Permet de sanctionner CE membre directement (cas signalé en ticket) — sinon
    # kick/ban ne passaient QUE par les détecteurs auto (non tracés). Chaque clic
    # ouvre un modal de raison (= confirmation explicite pour kick/ban) ; tout le flux
    # gardé (perm + FAIL-CLOSED + _dm_sanction + sanction + INSERT + send_mod_log) vit
    # dans _StaffSanctionModal.on_submit. Vue éphémère → callbacks bound (même pattern
    # que le bouton « Tableau de bord » ci-dessus).
    try:
        # Garde pré-calculée : si la cible est protégée, on n'affiche pas les boutons
        # (le modal re-contrôle de toute façon — ceci n'est qu'un confort UX).
        _ok_guard, _refus_guard = _staff_sanction_guard(i.user, membre, i.guild)
        if _ok_guard:
            def _make_sanction_cb(_action: str):
                async def _cb_sanction(inter: discord.Interaction):
                    # Pas de defer ici : on doit répondre par send_modal (le defer
                    # rendrait impossible l'ouverture du modal). Le modal, lui, defer
                    # en tête de son on_submit.
                    try:
                        # RE-VÉRIF perm au clic (la fiche éphémère a pu rester ouverte).
                        _, _, _, _perm = _STAFF_SANCTION_META[_action]
                        if not await check_mod_perm(inter, _perm):
                            return await inter.response.send_message(
                                "❌ Vous n'avez pas la permission.", ephemeral=True
                            )
                        _target = inter.guild.get_member(membre.id)
                        _ok, _refus = _staff_sanction_guard(inter.user, _target, inter.guild)
                        if not _ok:
                            return await inter.response.send_message(
                                f"❌ {_refus}", ephemeral=True
                            )
                        await inter.response.send_modal(
                            _StaffSanctionModal(_action, _target)
                        )
                    except Exception as _ex2:
                        _logerr(f"sanction.btn_{_action}", _ex2)
                        try:
                            if not inter.response.is_done():
                                await inter.response.send_message(
                                    f"❌ Erreur : `{_ex2}`", ephemeral=True
                                )
                        except Exception:
                            pass
                return _cb_sanction

            btn_mute = discord.ui.Button(
                label="Mute", emoji="🔇", style=discord.ButtonStyle.secondary,
                custom_id="infractions_sanction_mute",
            )
            btn_kick = discord.ui.Button(
                label="Kick", emoji="👢", style=discord.ButtonStyle.danger,
                custom_id="infractions_sanction_kick",
            )
            btn_ban = discord.ui.Button(
                label="Ban", emoji="🔨", style=discord.ButtonStyle.danger,
                custom_id="infractions_sanction_ban",
            )
            btn_mute.callback = _make_sanction_cb('mute')
            btn_kick.callback = _make_sanction_cb('kick')
            btn_ban.callback = _make_sanction_cb('ban')
            view.add_item(discord.ui.ActionRow(btn_mute, btn_kick, btn_ban))
    except Exception as _ex:
        _logerr("sanction.buttons_build", _ex)

    # ─── Bouton « 🗂️ Gérer le casier » (owner 2026-07-17) : ouvre un panneau STAFF pour RETIRER
    # une infraction ciblée, LEVER la privation VIP (→ il peut regagner le rôle), ou effacer tout
    # le casier. Re-vérifie la permission au clic. Vue éphémère → callback bound. ───
    try:
        btn_casier = discord.ui.Button(
            label="Gérer le casier", emoji="🗂️",
            style=discord.ButtonStyle.secondary, custom_id="infractions_manage_casier")

        async def _cb_casier(inter: discord.Interaction):
            try:
                if not await check_mod_perm(inter, 'mod_infractions_role'):
                    return await inter.response.send_message(
                        "❌ Vous n'avez pas la permission", ephemeral=True)
                _content, _view = await _build_casier_panel(inter.user, membre, inter.guild)
                await inter.response.send_message(content=_content, view=_view, ephemeral=True)
            except Exception as _ex2:
                print(f"[infractions casier btn] {_ex2}", file=_sys.stderr, flush=True)
                try:
                    if not inter.response.is_done():
                        await inter.response.send_message(f"❌ Erreur : `{_ex2}`", ephemeral=True)
                except Exception:
                    pass

        btn_casier.callback = _cb_casier
        view.add_item(discord.ui.ActionRow(btn_casier))
    except Exception as _ex:
        _logerr("casier.button_build", _ex)

    # FIX audit : EPHEMERAL — la fiche contient les NOTES INTERNES staff
    # (« 🗒️ Notes internes ») qui ne doivent PAS être visibles publiquement.
    await i.response.send_message(view=view, ephemeral=True)

    await send_mod_log(i.guild, 'infractions', i.user, membre, extra=f"Total: {len(rows)} infractions")


@mod_group.command(name="note", description="🗒️ Note interne sur un membre (contexte, sans le sanctionner)")
@app_commands.describe(membre="Le membre concerné", texte="La note (contexte, observation, suivi…)")
async def mod_note_cmd(i: discord.Interaction, membre: discord.Member, texte: str):
    # Note NON-PUNITIVE : scratchpad staff. N'attribue aucun rôle, n'affecte pas
    # le casier — sert juste à partager du contexte entre modérateurs (Phase 243).
    if not await check_mod_perm(i, 'mod_infractions_role'):
        return await i.response.send_message("❌ Vous n'avez pas la permission", ephemeral=True)
    texte = (texte or "").strip()
    if not texte:
        return await i.response.send_message("❌ Note vide.", ephemeral=True)
    try:
        async with get_db() as db:
            await db.execute(
                "CREATE TABLE IF NOT EXISTS mod_notes ("
                "id INTEGER PRIMARY KEY AUTOINCREMENT, guild_id INTEGER, user_id INTEGER, "
                "mod_id INTEGER, content TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP)"
            )
            await db.execute(
                "INSERT INTO mod_notes(guild_id, user_id, mod_id, content) VALUES(?,?,?,?)",
                (i.guild.id, membre.id, i.user.id, texte[:500]),
            )
            await db.commit()
            async with db.execute(
                "SELECT COUNT(*) FROM mod_notes WHERE guild_id=? AND user_id=?",
                (i.guild.id, membre.id),
            ) as c:
                ncount = (await c.fetchone())[0]
    except Exception as ex:
        print(f"[/mod note] {ex}")
        return await i.response.send_message(f"❌ Erreur : `{ex}`", ephemeral=True)

    # E1 : audit staff consolidé (QUI a noté QUI).
    await log_staff_action(i.guild.id, i.user.id, membre.id, "note",
                           detail=texte[:200], surface="slash")

    e = discord.Embed(
        title="🗒️ Note interne ajoutée",
        description=(
            f"Note enregistrée sur {membre.mention} — visible par le staff via "
            f"`/mod infractions`.\n_Non-punitive : aucun rôle, aucun impact sur le casier._"
        ),
        color=discord.Color.light_grey(),
        timestamp=now(),
    )
    e.add_field(name="📝 Note", value=texte[:1024], inline=False)
    e.add_field(name="🗂️ Total notes", value=f"`{ncount}`", inline=True)
    e.set_thumbnail(url=membre.display_avatar.url)
    await i.response.send_message(embed=e, ephemeral=True)
    try:
        await send_mod_log(i.guild, 'note', i.user, membre, texte, extra=f"Total notes: {ncount}")
    except Exception:
        pass

