async def _voice_log_listener(member, before, after):
    """LOG VOCAL (quick-win pro) : émet VOICE_JOIN/LEAVE/MOVE dans le salon de logs
    unifié — la catégorie « Vocal » existait mais AUCUN émetteur ne la remplissait.
    Listener ADDITIF (jamais un 2e @bot.event — piège connu). FAIL-SAFE : log_event
    no-op tout seul si les logs ne sont pas configurés / la catégorie désactivée.
    On ignore les bots et les simples changements mute/sourdine (anti-spam)."""
    try:
        if member is None or member.bot or getattr(member, 'guild', None) is None:
            return
        b = before.channel if before else None
        a = after.channel if after else None
        # 1) CONNEXION vocale (comportement historique join-only anti-bruit ; owner 2026-06-14).
        #    La déconnexion/déplacement + le SELF-mute (l'utilisateur se coupe lui-même) = bruit → ignorés.
        if b is None and a is not None:
            await ulogger2026.log_event(
                bot, member.guild, ulogger2026.EventType.VOICE_JOIN,
                description=f"🎤 {member.mention} a rejoint **{a.name}**", user=member, channel=a)
            return
        # 2) SÉCU (owner 2026-07-11) : SERVER-mute / SERVER-deaf = ACTION DE MODÉRATION → à TRACER
        #    (troll vocal le + courant + repère un modo abusif via l'audit log). ≠ self_mute (ignoré).
        if before is not None and after is not None and a is not None:
            sm = (getattr(before, 'mute', False) != getattr(after, 'mute', False))
            sd = (getattr(before, 'deaf', False) != getattr(after, 'deaf', False))
            if sm or sd:
                actor = None
                try:
                    async for _e in member.guild.audit_logs(
                            limit=4, action=discord.AuditLogAction.member_update):
                        if getattr(_e.target, 'id', None) == member.id:
                            actor = _e.user
                            break
                except Exception:
                    actor = None
                _parts = []
                if sm:
                    _parts.append("🔇 server-mute **activé**" if after.mute else "🔊 server-mute **retiré**")
                if sd:
                    _parts.append("🙉 server-deaf **activé**" if after.deaf else "👂 server-deaf **retiré**")
                await ulogger2026.log_event(
                    bot, member.guild, ulogger2026.EventType.VOICE_MUTE,
                    description=(f"{member.mention} — " + " · ".join(_parts)
                                 + f"\n**Salon :** {a.name}"
                                 + (f"\n**Par :** {actor.mention} (`{actor.id}`)" if actor else
                                    "\n_(auteur introuvable — active « Voir les logs d'audit » côté bot)_")),
                    user=member, moderator=(actor if actor is not None else bot.user), channel=a)
                return
        # 3) DÉBUT de partage d'écran / caméra (protection mineurs : VISIBILITÉ seule, jamais de sanction).
        if before is not None and after is not None and a is not None:
            _stream_on = (not getattr(before, 'self_stream', False)) and getattr(after, 'self_stream', False)
            _video_on = (not getattr(before, 'self_video', False)) and getattr(after, 'self_video', False)
            if _stream_on or _video_on:
                _what = "📺 un partage d'écran" if _stream_on else "📹 sa caméra"
                await ulogger2026.log_event(
                    bot, member.guild, ulogger2026.EventType.VOICE_STREAM,
                    description=f"{member.mention} a démarré **{_what}** dans **{a.name}**",
                    user=member, channel=a)
                return
    except Exception as ex:
        print(f"[voice_log] {ex}")


# ─── ANTI CHANNEL-HOP VOCAL (owner 2026-06-21) ──────────────────────────────────
# Quelqu'un qui ENTRE / SORT / SAUTE des salons vocaux en boucle (pour faire du bruit
# de connexion/déconnexion) → on le FREINE : déconnexion immédiate + escalade graduée
# (déconnexion seule → +exclusion 1 min → +exclusion 5 min) via les strikes, comme
# l'anti-monologue. L'exclusion (timeout) empêche la reconnexion vocale → stoppe le
# manège. Immunisés / owner / staff EXEMPTÉS. Mémoire bornée. 100% FAIL-SAFE.
# NB : le CONTENU vocal (ce qui est dit) reste hors de portée d'un bot ; ici on n'agit
# que sur l'ÉTAT (les transitions de salon), seule chose observable.
_voice_hop_tracker: dict = {}   # (guild_id, user_id) -> [timestamps de transitions de salon]
_VOICE_HOP_MAX = 6              # nb de transitions (join/leave/move)…
_VOICE_HOP_WINDOW = 12.0        # …dans cette fenêtre (s) → déclenche le frein


async def _voice_hop_listener(member, before, after):
    try:
        if member is None or getattr(member, 'bot', False) or member.guild is None:
            return
        # On ne compte QUE les vrais changements de salon. Un mute/sourdine/stream/partage
        # sans bouger de salon (before.channel == after.channel) n'est PAS un hop.
        if before.channel == after.channel:
            return
        c = await cfg(member.guild.id)
        if not c.get('anti_voice_hop', 1):
            return
        if await is_fully_immune(member):
            return  # owner / staff / immunisés jamais freinés
        _nowv = now()
        _k = (member.guild.id, member.id)
        _buf = [t for t in _voice_hop_tracker.get(_k, [])
                if (_nowv - t).total_seconds() < _VOICE_HOP_WINDOW]
        _buf.append(_nowv)
        _voice_hop_tracker[_k] = _buf
        if len(_voice_hop_tracker) > 5000:  # borne mémoire (éviction paresseuse)
            for _kk in [k for k, v in list(_voice_hop_tracker.items())
                        if not v or (_nowv - v[-1]).total_seconds() > _VOICE_HOP_WINDOW]:
                _voice_hop_tracker.pop(_kk, None)
        if len(_buf) < _VOICE_HOP_MAX:
            return
        _voice_hop_tracker[_k] = []  # reset → il faut re-spammer pour re-déclencher
        # Déconnexion immédiate s'il est encore en vocal.
        try:
            if after.channel is not None:
                await member.move_to(
                    None, reason="Anti channel-hop vocal (entrées/sorties répétées)")
        except Exception:
            pass
        # Escalade graduée via les strikes (calque anti-monologue / anti-imgflood).
        try:
            _s = _register_protection_strike(member.guild.id, member.id, 'voicehop')
        except Exception:
            _s = 1
        _action = "déconnecté du vocal"
        try:
            if _s == 2:
                await member.timeout(timedelta(minutes=1),
                                     reason="Channel-hop vocal répété")
                _action = "déconnecté + exclu temporairement **1 min**"
            elif _s >= 3:
                await member.timeout(timedelta(minutes=5),
                                     reason="Channel-hop vocal répété")
                _action = "déconnecté + exclu temporairement **5 min**"
        except Exception:
            pass
        # Log clair (qui / quoi / action / palier) → logs sécu/modération. L'éventuel
        # timeout posé ci-dessus N'EST PAS re-loggé par le détecteur de timeout natif
        # (auteur = bot → sauté), donc ce log est l'unique trace : pas de double.
        try:
            await ulogger2026.log_event(
                bot, member.guild, ulogger2026.EventType.SEC_ESCALATION,
                description=(f"🔁 {member.mention} enchaînait les entrées/sorties vocales "
                             f"en boucle (anti channel-hop) → **{_action}**."),
                user=member, moderator=bot.user,
                extra={"🛡️ Palier": str(_s), "⏱️ Fenêtre": f"{_VOICE_HOP_MAX}+ en {int(_VOICE_HOP_WINDOW)}s"},
            )
        except Exception:
            pass
    except Exception as ex:
        print(f"[_voice_hop_listener] {ex}")


async def _role_mentionable_guard(*args):
    """owner 2026-06-27 : filet anti ping de masse — si un rôle devient mentionnable (créé ou
    modifié ainsi), on le repasse AUSSITÔT en non-mentionnable. Guard anti-boucle : on n'agit
    que si le rôle est encore mentionnable (notre edit le met à False → 2e passage ignoré).
    Le bot ping toujours ses rôles d'event via allowed_mentions(roles=True). FAIL-SAFE."""
    try:
        role = args[-1]  # role_create(role) ou role_update(before, after) → après = le rôle
        if role is None or not getattr(role, 'mentionable', False):
            return
        guild = getattr(role, 'guild', None)
        me = getattr(guild, 'me', None) if guild else None
        if not (me and me.guild_permissions.manage_roles):
            return
        if role.is_default() or role.managed or role >= me.top_role:
            return
        await role.edit(mentionable=False,
                        reason="Anti ping de masse — aucun rôle mentionnable (owner 2026-06-27)")
    except Exception:
        pass


