# ═══════════════════════════════════════════════════════════════════════════════
#  i18n — SÉLECTEUR DE LANGUE (zéro slash, tout bouton/DynamicItem, FAIL-SAFE)
#
#  Serveur INTERNATIONAL : un membre choisit sa langue via un bouton du hub (catégorie
#  « Récit & Aide »). Au clic on : (1) persiste la préférence (i18n.set_user_lang),
#  (2) attribue un ROLE DRAPEAU décoratif (zéro perm) en retirant les autres rôles de
#  langue, (3) confirme en ÉPHÉMÈRE DANS LA LANGUE choisie via i18n.t(). Les boutons
#  de choix sont des DynamicItem (custom_id i18n_setlang:<lang>) → ils survivent au
#  reboot. AUTO-DÉTECTION : à la 1re ouverture sans préférence, on pose la langue
#  déduite de la locale Discord (silencieux, sans MP, sans spam).
# ═══════════════════════════════════════════════════════════════════════════════

# Préfixe des rôles drapeau (décoratifs). Sert à les reconnaître pour en retirer les
# autres quand un membre change de langue. Globe neutre + libellé natif → « 🌐 Français ».
LANG_ROLE_PREFIX = "🌐 "


def _i18n_lang_role_name(lang: str) -> str:
    """Nom du rôle drapeau pour une langue : « 🌐 English ». FAIL-SAFE."""
    try:
        label = i18n_module.LANG_LABELS.get(i18n_module.normalize_lang(lang), lang)
    except Exception:
        label = str(lang)
    return f"{LANG_ROLE_PREFIX}{label}"


def _i18n_all_lang_role_names() -> set:
    """Tous les noms de rôles de langue gérés (pour le nettoyage). FAIL-SAFE."""
    try:
        return {_i18n_lang_role_name(l) for l in i18n_module.SUPPORTED_LANGS}
    except Exception:
        return set()


async def _i18n_assign_lang_role(member, lang) -> None:
    """Attribue le rôle drapeau de `lang` au membre et retire les autres rôles de
    langue. Crée le rôle s'il n'existe pas (décoratif : aucune permission, hoist off,
    mentionnable off). TOTALEMENT FAIL-SAFE : si « Gérer les rôles » manque ou que le
    rôle est trop haut, on n'échoue PAS — la préférence reste enregistrée, on saute
    juste le rôle. Aucune exception ne sort jamais."""
    try:
        guild = getattr(member, "guild", None)
        if guild is None:
            return
        me = guild.me
        if me is None or not me.guild_permissions.manage_roles:
            return  # pas la perm → on garde juste la préférence (fail-safe)

        target_name = _i18n_lang_role_name(lang)
        managed_names = _i18n_all_lang_role_names()

        # Rôle cible : réutilise s'il existe, sinon le crée (décoratif).
        target_role = discord.utils.get(guild.roles, name=target_name)
        if target_role is None:
            try:
                target_role = await guild.create_role(
                    name=target_name,
                    permissions=discord.Permissions.none(),
                    mentionable=False,
                    hoist=False,
                    reason="i18n : rôle de langue décoratif",
                )
            except Exception as ex:
                print(f"[i18n create_role] {ex}")
                target_role = None

        # Retire les AUTRES rôles de langue que le membre porterait déjà.
        try:
            to_remove = [
                r for r in getattr(member, "roles", [])
                if r.name in managed_names and (target_role is None or r.id != target_role.id)
                and r < me.top_role and not r.managed
            ]
            if to_remove:
                await member.remove_roles(*to_remove, reason="i18n : changement de langue")
        except Exception as ex:
            print(f"[i18n remove old lang roles] {ex}")

        # Ajoute le rôle cible (s'il a pu être obtenu et qu'on est au-dessus).
        try:
            if (target_role is not None and target_role < me.top_role
                    and not target_role.managed and target_role not in getattr(member, "roles", [])):
                await member.add_roles(target_role, reason="i18n : langue choisie")
        except Exception as ex:
            print(f"[i18n add lang role] {ex}")
    except Exception as ex:
        print(f"[_i18n_assign_lang_role] {ex}")




async def _i18n_apply_lang(i: discord.Interaction, lang: str) -> None:
    """Cœur commun du choix de langue (appelé par les boutons drapeau). Defer-first,
    persiste la préférence, attribue le rôle drapeau, confirme EN ÉPHÉMÈRE dans la
    langue choisie via i18n.t(). FAIL-SAFE de bout en bout."""
    try:
        lang = i18n_module.normalize_lang(lang)
        if not await _safe_defer(i, ephemeral=True):
            return
        uid = getattr(getattr(i, "user", None), "id", None)
        if uid is not None:
            await i18n_module.set_user_lang(uid, lang)
        member = getattr(i, "user", None)
        if getattr(i, "guild", None) is not None and member is not None:
            await _i18n_assign_lang_role(member, lang)
        # Confirmation DANS la langue choisie (label natif + drapeau).
        try:
            label = i18n_module.lang_choice_label(lang)  # « 🇫🇷 Français »
            msg = i18n_module.t("lang.changed", lang, lang=label)
        except Exception:
            msg = "✅"
        await _safe_followup(i, content=f"✅ {msg}")
    except Exception as ex:
        print(f"[_i18n_apply_lang] {ex}")
        try:
            await _safe_followup(i, content="✅")
        except Exception:
            pass


class LangSelectButton(
    discord.ui.DynamicItem[Button],
    template=r"i18n_setlang:(?P<lang>[a-z]{2})",
):
    """Bouton PERSISTANT d'un drapeau de langue (un par langue supportée). DynamicItem
    → re-capté au reboot via le custom_id i18n_setlang:<lang>. Au clic → applique la
    langue (préférence + rôle + confirmation traduite)."""

    def __init__(self, lang: str):
        self.lang = i18n_module.normalize_lang(lang)
        super().__init__(
            Button(
                label=i18n_module.LANG_LABELS.get(self.lang, self.lang),
                emoji=i18n_module.LANG_FLAGS.get(self.lang) or None,
                style=discord.ButtonStyle.secondary,
                custom_id=f"i18n_setlang:{self.lang}",
            )
        )

    @classmethod
    async def from_custom_id(cls, interaction, item, match):
        return cls(match["lang"])

    async def callback(self, i: discord.Interaction):
        await _i18n_apply_lang(i, self.lang)






